  const RANGES = [
    { key: "1d", name: "r1d" },
    { key: "5d", name: "r5d" },
    { key: "1mo", name: "r1mo" },
    { key: "3mo", name: "r3mo" },
    { key: "6mo", name: "r6mo" },
    { key: "1y", name: "r1y" },
    { key: "5y", name: "r5y" },
    { key: "max", name: "rmax" },
  ];
  const rangeOf = (key) => (RANGES.some((range) => range.key === key) ? key : "1d");
  // The periods the chart offers: those ticked beside "Starts with" (ranges
  // in DEFAULTS), in the chart's own order whatever order they were ticked
