  const LONG_RANGES = ["5y", "max"];
  function chartStyle(setting, range, chosen) {
    if (chosen === "candles" || chosen === "line") return chosen;
    if (setting === "candles" || setting === "line") return setting;
    return LONG_RANGES.includes(rangeOf(range)) ? "line" : "candles";
  }

  // ------------------------------------------------------------- formatting
  function localeOf(hass) {
    return (hass && hass.locale && hass.locale.language) || (hass && hass.language) || "en";
  }

