  // the one chosen in the editor, and the card's own where the picker was
  // emptied.
  const toolIcon = (config, name) => {
    const icon = config[`${name}_icon`];
    return typeof icon === "string" && icon ? icon : DEFAULTS[`${name}_icon`];
  };

  // TradingView's mark, filled in the colour of the link it stands in.
  const TRADINGVIEW_LOGO =
    `<svg viewBox="0 4 35.5 18" aria-hidden="true" focusable="false"><path fill="currentColor" d="M14 22H7V11H0V4h14v18z"/>` +
    `<circle fill="currentColor" cx="20" cy="8" r="4"/><path fill="currentColor" d="M28 22h-8l7.5-18h8L28 22z"/></svg>`;

  // An instrument's page at TradingView, from its symbol there:
  // "XETR:SIE" is /symbols/XETR-SIE/. The German site for a German reader.
  function tradingViewUrl(hass, symbol) {
    const parts = /^([A-Z0-9_]+):([A-Z0-9_.!]+)$/.exec(symbol || "");
    if (!parts) return null;
    const site = localeOf(hass).toLowerCase().startsWith("de") ? "de" : "www";
    return `https://${site}.tradingview.com/symbols/${parts[1]}-${encodeURIComponent(parts[2])}/`;
  }

  // The reader's own number format, as set in their Home Assistant profile -
  // which is not always the one of their language.
  function numberLocale(hass) {
    switch (hass && hass.locale && hass.locale.number_format) {
      case "comma_decimal":
        return "en-US";
      case "decimal_comma":
        return "de";
      case "space_comma":
        return "fr";
      case "quote_decimal":
        return "de-CH";
      case "none":
        return "en-US";
      case "system":
        return undefined;
      default:
        return localeOf(hass);
    }
  }

  const FORMATS = new Map();
  function numberFormat(hass, options) {
    const locale = numberLocale(hass);
    const bare = !!(hass && hass.locale && hass.locale.number_format === "none");
    const opts = bare ? { ...options, useGrouping: false } : options;
    const key = String(locale) + JSON.stringify(opts);
    let format = FORMATS.get(key);
    if (!format) {
      try {
        format = new Intl.NumberFormat(locale, opts);
      } catch (err) {
        format = new Intl.NumberFormat("en", opts);
      }
      FORMATS.set(key, format);
    }
    return format;
  }

  const isNumber = (value) => typeof value === "number" && Number.isFinite(value);

  // A figure out of an attribute or a websocket answer: a number, or nothing.
  function toNumber(value) {
    if (isNumber(value)) return value;
    if (typeof value !== "string" || value.trim() === "") return null;
    const number = Number(value);
    return Number.isFinite(number) ? number : null;
  }

  // Every chart's pair of clip paths gets a number of its own: two charts
  // can stand in one shadow root - the card's and its pop-up's.
  let CLIP_SEQ = 0;

  // Which of the three trend lines and whether the RSI the viewer has switched
  // on. Theirs, not the card's: kept in the browser, the same for every card
  // on it, and all on where nothing is kept or nothing can be.
  const TREND_KEY = "market-ticker-ultra-card:trend-lines";
  const TREND = { sma: true, sma50: true, ema: true, rsi: true };
  try {
    const kept = JSON.parse(localStorage.getItem(TREND_KEY) || "null");
    if (kept && typeof kept === "object") {
      if (kept.sma === false) TREND.sma = false;
      if (kept.sma50 === false) TREND.sma50 = false;
      if (kept.ema === false) TREND.ema = false;
      if (kept.rsi === false) TREND.rsi = false;
    }
  } catch (err) {
    // No storage in this browser: both lines, every time.
  }
  function setTrend(name, on) {
    TREND[name] = !!on;
    try {
      localStorage.setItem(TREND_KEY, JSON.stringify(TREND));
    } catch (err) {
      // Holds until the page is reloaded.
    }
  }

  // Only a real three-letter code goes to the browser as a currency. A unit
  // such as "GBp" - pence, as London quotes its shares - would be read as
  // pounds there, a hundred times too much; it is written behind the number
  // as it stands instead.
  const isCurrency = (code) => typeof code === "string" && /^[A-Z]{3}$/.test(code);

  // A price can have more than two decimals worth showing: a penny stock, a
  // currency pair, a coin.
  //
  // "quoted" is what the integration says the instrument is quoted in - four
  // decimals for a currency pair, where 1.10 and 1.1002 are not the same
  // price. Where it says nothing, the size of the figure decides.
  const priceDigits = (value, quoted) =>
    Math.max(isNumber(quoted) ? quoted : 2, value !== 0 && Math.abs(value) < 1 ? 4 : 2);

  function money(hass, value, currency, signed, quoted) {
    if (!isNumber(value)) return "";
    const most = priceDigits(value, quoted);
    const digits = {
      minimumFractionDigits: Math.min(most, isNumber(quoted) ? Math.max(2, quoted) : 2),
      maximumFractionDigits: most,
      signDisplay: signed ? "exceptZero" : "auto",
    };
    if (isCurrency(currency)) {
      return numberFormat(hass, { style: "currency", currency, ...digits }).format(value);
    }
    const text = numberFormat(hass, digits).format(value);
    return currency ? `${text} ${currency}` : text;
  }

  // A change in percent. The integration gives percentage points: -0.74 is
  // -0.74 %.
  function percent(hass, points, signed = true) {
    if (!isNumber(points)) return "";
    return (
      numberFormat(hass, {
        minimumFractionDigits: 2,
        maximumFractionDigits: 2,
        signDisplay: signed ? "exceptZero" : "auto",
      }).format(points) + "%"
    );
  }

  // How the price has moved over the period a series shows: from the last
  // close before it - or, where the series brings none, from its first bar -
  // to the price now. Null where there is nothing to measure from.
  function periodChange(history, price) {
    if (!history || !history.bars || !history.bars.length) return null;
    const lead = history.lead || [];
    const base = lead.length ? lead[lead.length - 1].c : history.bars[0].o;
    const last = isNumber(price) ? price : history.bars[history.bars.length - 1].c;
    if (!isNumber(base) || !base || !isNumber(last)) return null;
    return { amount: last - base, percent: ((last - base) / base) * 100 };
  }

  // A change as one phrase: the percentage, and the amount in brackets
  // behind it - or whichever of the two there is.
  function bracketed(pct, amount) {
    if (pct && amount) return `${pct} (${amount})`;
    return pct || amount || "";
  }

  function plain(hass, value, digits = 2) {
    if (!isNumber(value)) return "";
    return numberFormat(hass, { minimumFractionDigits: digits, maximumFractionDigits: digits }).format(value);
  }

  function quantity(hass, value) {
    if (!isNumber(value)) return "";
    return numberFormat(hass, { maximumFractionDigits: 6 }).format(value);
  }

  // 18.3M, 1.48T - a volume, a market capitalisation.
  function compact(hass, value, currency, digits = 2) {
    if (!isNumber(value)) return "";
    // Grouped always: the short notation leaves a four-digit figure -
    // 9415 - without its separator otherwise.
    const base = { notation: "compact", maximumFractionDigits: digits, useGrouping: true };
    if (isCurrency(currency)) {
      return numberFormat(hass, { style: "currency", currency, ...base }).format(value);
    }
    return numberFormat(hass, base).format(value);
  }

  // The row's and the tile's way of writing a price: the whole part large,
  // the cents raised beside it over the currency's sign.
  function splitHtml(hass, value, currency, quoted) {
    if (!isNumber(value)) return "";
    const iso = isCurrency(currency);
    const most = priceDigits(value, quoted);
    const parts = numberFormat(hass, {
      ...(iso ? { style: "currency", currency } : {}),
      minimumFractionDigits: Math.min(most, isNumber(quoted) ? Math.max(2, quoted) : 2),
      maximumFractionDigits: most,
    }).formatToParts(value);
    let whole = "";
    let fraction = "";
    let sign = iso ? "" : currency || "";
    for (const part of parts) {
      if (part.type === "fraction") fraction = part.value;
      else if (part.type === "currency") sign = part.value;
      else if (part.type !== "decimal" && part.type !== "literal") whole += part.value;
    }
    return (
      `<span class="int">${escapeHtml(whole)}</span>` +
      `<span class="frac"><span>${escapeHtml(fraction)}</span>` +
      (sign ? `<span class="cur">${escapeHtml(sign)}</span>` : "") +
      `</span>`
    );
  }

  // Dates and times in the reader's language, their time zone - the
  // browser's or Home Assistant's, as their profile says - and their clock.
  function timeZoneOf(hass) {
    const setting = hass && hass.locale && hass.locale.time_zone;
    const server = hass && hass.config && hass.config.time_zone;
    return setting === "server" && server ? server : undefined;
  }

  function dateTime(hass, stamp, options) {
    const date = new Date(stamp);
    if (Number.isNaN(date.getTime())) return "";
    const full = { ...options };
    const zone = timeZoneOf(hass);
    if (zone) full.timeZone = zone;
    const clock = hass && hass.locale && hass.locale.time_format;
    if (full.hour && (clock === "12" || clock === "24")) full.hour12 = clock === "12";
    try {
      return new Intl.DateTimeFormat(localeOf(hass), full).format(date);
    } catch (err) {
      return date.toLocaleString();
    }
  }

  // Whether a chart's bars are shorter than a day: then a moment needs its
  // time as well as its date.
  const isIntraday = (interval) => /^\d+(m|h)$/.test(String(interval || ""));

  // What stands along the bottom of a chart, and what the pointer reads.
  function axisFormat(range, interval) {
    if (range === "1d") return { hour: "numeric", minute: "2-digit" };
    if (range === "5d") return { weekday: "short", day: "numeric" };
    if (range === "1mo" || range === "3mo" || range === "6mo") return { day: "numeric", month: "short" };
    if (isIntraday(interval)) return { day: "numeric", month: "short" };
    return { month: "short", year: "2-digit" };
  }

  function hoverFormat(interval) {
    return isIntraday(interval)
      ? { weekday: "short", day: "numeric", month: "short", hour: "numeric", minute: "2-digit" }
      : { weekday: "short", day: "numeric", month: "short", year: "numeric" };
  }

  function escapeHtml(value) {
    return String(value === undefined || value === null ? "" : value).replace(
      /[&<>"']/g,
      (ch) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[ch])
    );
  }

  const gainClass = (value) => (!isNumber(value) || value === 0 ? "" : value > 0 ? "gain" : "loss");

  // The settings an element was given in the editor, as an inline style.
  function elementStyle(config, prefix) {
    const parts = [];
    const color = config[`${prefix}_color`];
    const size = config[`${prefix}_font_size`];
    const spacing = config[`${prefix}_letter_spacing`];
    if (color) parts.push(`color: ${color}`);
    if (size) parts.push(`font-size: ${size}`);
    if (config[`${prefix}_bold`]) parts.push("font-weight: 700");
    if (config[`${prefix}_italic`]) parts.push("font-style: italic");
    if (config[`${prefix}_uppercase`]) parts.push("text-transform: uppercase");
    if (config[`${prefix}_underline`]) parts.push("text-decoration: underline");
    if (spacing) parts.push(`letter-spacing: ${spacing}`);
    // Only the elements that declare a background carry these keys; for the
    // others both reads are undefined and nothing is written.
    if (config[`${prefix}_background`] === false) {
      parts.push("background: none");
    } else if (config[`${prefix}_background_color`]) {
      parts.push(`background: ${config[`${prefix}_background_color`]}`);
    }
    return escapeHtml(parts.join("; "));
  }

  // ------------------------------------------------------------- indicators
  //
  // Each takes the closing prices and gives one figure per bar, null where
  // there are not yet enough bars behind it.

  // Simple moving average: the mean of the last `length` closes.
  function sma(values, length) {
    const out = new Array(values.length).fill(null);
    let sum = 0;
    for (let i = 0; i < values.length; i++) {
      sum += values[i];
      if (i >= length) sum -= values[i - length];
      if (i >= length - 1) out[i] = sum / length;
    }
    return out;
  }

  // Exponential moving average, started on the simple mean of its first
  // `length` closes.
  function ema(values, length) {
    const out = new Array(values.length).fill(null);
    if (values.length < length) return out;
    const weight = 2 / (length + 1);
    let last = 0;
    for (let i = 0; i < length; i++) last += values[i];
    last /= length;
    out[length - 1] = last;
    for (let i = length; i < values.length; i++) {
      last = values[i] * weight + last * (1 - weight);
      out[i] = last;
    }
    return out;
  }

  // Relative Strength Index with Wilder's smoothing, the usual one.
  function rsi(values, length) {
    const out = new Array(values.length).fill(null);
    if (values.length <= length) return out;
    let gain = 0;
    let loss = 0;
    for (let i = 1; i <= length; i++) {
      const move = values[i] - values[i - 1];
      if (move >= 0) gain += move;
      else loss -= move;
    }
    gain /= length;
    loss /= length;
    const figure = () => (loss === 0 ? (gain === 0 ? 50 : 100) : 100 - 100 / (1 + gain / loss));
    out[length] = figure();
    for (let i = length + 1; i < values.length; i++) {
      const move = values[i] - values[i - 1];
      gain = (gain * (length - 1) + Math.max(move, 0)) / length;
      loss = (loss * (length - 1) + Math.max(-move, 0)) / length;
      out[i] = figure();
    }
    return out;
  }

  // ---------------------------------------------------------------- history
  //
  // A moment as the integration sends it - seconds since 1970 - in
  // milliseconds. Milliseconds and a written date are read as well.
  function stampMs(value) {
    if (isNumber(value)) return value < 1e11 ? value * 1000 : value;
    if (typeof value === "string" && value) {
      const parsed = Date.parse(value);
      return Number.isFinite(parsed) ? parsed : null;
    }
    return null;
  }

  // The history command's columns as one bar per moment. A bar without a
  // close is left out; one without its open, high or low stands on its close.
  function normalizeHistory(answer) {
    const data = answer || {};
    const column = (name) => (Array.isArray(data[name]) ? data[name] : []);
    const stamps = column("timestamps");
    const [open, high, low, close, volume] = ["open", "high", "low", "close", "volume"].map(column);
    const bars = [];
    // The first so many bars lie before the period: they are what the
    // averages at the chart's left edge are worked out from, and are not
    // drawn or counted anywhere else.
    const warmup = Math.max(0, Math.min(stamps.length, Math.floor(toNumber(data.warmup) || 0)));
    const lead = [];
    for (let i = 0; i < stamps.length; i++) {
      const t = stampMs(stamps[i]);
      const c = toNumber(close[i]);
      if (t === null || c === null) continue;
      const first = toNumber(open[i]);
      const o = first === null ? c : first;
      const top = toNumber(high[i]);
      const bottom = toNumber(low[i]);
      (i < warmup ? lead : bars).push({
        t,
        o,
        h: top === null ? Math.max(o, c) : Math.max(top, o, c),
        l: bottom === null ? Math.min(o, c) : Math.min(bottom, o, c),
        c,
        v: toNumber(volume[i]),
      });
    }
    bars.sort((a, b) => a.t - b.t);
    lead.sort((a, b) => a.t - b.t);
    const start = data.session ? stampMs(data.session.start) : null;
    const end = data.session ? stampMs(data.session.end) : null;
    return {
      range: data.range || "",
      interval: String(data.interval || ""),
      currency: data.currency || "",
      previousClose: toNumber(data.previous_close),
      session: start !== null && end !== null && end > start ? { start, end } : null,
      bars,
      lead,
    };
  }

  // A bar's length in milliseconds, from the interval's name ("30m", "1h").
  function intervalMs(interval) {
    const match = /^(\d+)(m|h)$/.exec(String(interval || ""));
    return match ? Number(match[1]) * (match[2] === "h" ? 3600000 : 60000) : null;
  }

  // A week of bars shorter than a day, each day as wide as the next: the
  // hours of the day that the week has prices in - from the earliest bar's
  // time of day to the latest one's - are one slot per bar length, in every
  // day, and each bar stands in the slot of its time. A listing with a few
  // prices a day then shows them where they were, and a day with one price
  // is as wide as a day with twenty. Nothing where the bars do not fall
  // into slots of their own.
  function weekLayout(history) {
    const bars = history.bars;
    const step = intervalMs(history.interval);
    if (history.range !== "5d" || !step || bars.length < 2) return null;
    const dayOf = (bar) => {
      const date = new Date(bar.t);
      return { key: date.getFullYear() * 10000 + date.getMonth() * 100 + date.getDate(), at: date.getHours() * 3600000 + date.getMinutes() * 60000 };
    };
    const placed = bars.map(dayOf);
    let first = Infinity;
    let last = -Infinity;
    for (const place of placed) {
      first = Math.min(first, place.at);
      last = Math.max(last, place.at);
    }
    const perDay = Math.round((last - first) / step) + 1;
    const days = [];
    const slots = placed.map((place, i) => {
      if (!days.length || days[days.length - 1].key !== place.key) days.push({ key: place.key, t: bars[i].t });
      return (days.length - 1) * perDay + Math.min(perDay - 1, Math.round((place.at - first) / step));
    });
    const count = days.length * perDay;
    if (days.length < 2 || count > 4000) return null;
    for (let i = 1; i < slots.length; i++) if (slots[i] <= slots[i - 1]) return null;
    return {
      count,
      slots,
      from: null,
      to: null,
      days: days.map((day, i) => ({ t: day.t, at: (i / days.length) * 100 })),
    };
  }

  // Where each bar stands along the chart. As a rule the bars are spread
  // evenly, one slot each: a year of prices has no night and no weekend in
  // it. A day that is still running is different - it has its trading
  // session, and the chart keeps the room for what is still to come: one
  // slot per bar length from the session's start to its end, each bar in
  // the slot of its time. A week is drawn day by day - see weekLayout.
  // Bars outside the session, or ones that do not fall into slots of their
  // own, put the chart back on the plain spread.
  function slotLayout(history) {
    const bars = history.bars;
    const even = { count: bars.length, slots: bars.map((bar, i) => i), from: null, to: null };
    const session = history.session;
    if (!session) return weekLayout(history) || even;
    if (bars.length < 2) return even;
    const steps = [];
    for (let i = 1; i < bars.length; i++) steps.push(bars[i].t - bars[i - 1].t);
    steps.sort((a, b) => a - b);
    // The bar length the source names; without one, the usual gap - which
    // is longer than a bar where only a few prices were made.
    const step = intervalMs(history.interval) || steps[Math.floor(steps.length / 2)];
    if (!(step > 0)) return even;
    if (bars[0].t < session.start - step / 2 || bars[bars.length - 1].t > session.end + step / 2) return even;
    const count = Math.max(1, Math.round((session.end - session.start) / step));
    if (count < bars.length || count > 2000) return even;
    const slots = bars.map((bar) => Math.min(count - 1, Math.max(0, Math.round((bar.t - session.start) / step))));
    for (let i = 1; i < slots.length; i++) if (slots[i] <= slots[i - 1]) return even;
    return { count, slots, from: session.start, to: session.end };
  }

  // The first price of the day: the open of the first bar of the one-day
  // history that lies inside the trading session.
  function dayOpen(history) {
    if (!history || !history.bars.length) return null;
    const session = history.session;
    const bar = session ? history.bars.find((item) => item.t >= session.start) : history.bars[0];
    return bar ? bar.o : null;
  }

  // -------------------------------------------------------------- the data
  //
  // One table for every card and editor on the page: the instruments are
  // the same in all of them, and two cards should not ask twice.
  //
  // Everything in here is asked for through the newest hass object any card
  // was handed. One captured earlier is a snapshot: its states stand still.
  const LISTENERS = new Set();
  let liveHass = null;

  const INSTRUMENTS = {
    list: null,          // null until the first answer
    groups: [],          // { id, name, kind } - portfolios and watchlists
    base: "",            // the currency positions are added up in
    attribution: null,   // { text, url } while the integration serves logos
    key: null,           // the sensors the answer was asked for
    version: 0,
    asking: false,
    timer: null,
    tries: 0,
    failed: false,
    stale: false,        // asked for again although the sensors are the same
  };
  // The command is not there while the integration is still starting: asked
  // again at these distances in seconds, the last one repeating.
  const ASK_AGAIN = [2, 5, 10, 20, 30, 60];

  function notify() {
    for (const listener of [...LISTENERS]) {
      try {
        listener._dataChanged();
      } catch (err) {
        console.warn(`${CARD_TAG}: could not redraw`, err);
      }
    }
  }

  // The integration's sensors, as the frontend's own entity list has them.
  // When that set changes - an instrument added, removed, renamed - the
  // list of instruments is asked for again.
  function sensorKey(hass) {
    const entities = (hass && hass.entities) || {};
    const ids = [];
    for (const id in entities) {
      if (entities[id] && entities[id].platform === DOMAIN) ids.push(id);
    }
    return ids.sort().join(",");
  }

  function attributionOf(value) {
    if (!value || typeof value.text !== "string" || !value.text.trim()) return null;
    const url = typeof value.url === "string" && /^https?:\/\//i.test(value.url) ? value.url : "";
    return { text: value.text, url };
  }

  // The colours of the allocation's shares, in the order of their size.
  // Neither green nor red: those two say gain and loss.
  const ALLOC_COLORS = ["#3b82f6", "#facc15", "#c084fc", "#22d3ee", "#fb923c", "#f472b6", "#818cf8", "#2dd4bf", "#a3a3a3", "#e879f9"];

  // Home Assistant's own colours, as its colour picker names them: each is
  // the theme's variable of that name.
  const THEME_COLORS = new Set([
    "primary", "accent", "red", "pink", "purple", "deep-purple", "indigo", "blue", "light-blue", "cyan", "teal",
    "green", "light-green", "lime", "yellow", "amber", "orange", "deep-orange", "brown", "light-grey", "grey",
    "dark-grey", "blue-grey", "black", "white",
  ]);

  // What Home Assistant's default theme draws them in: to tell whether
  // one of the card's own colours would look like one that is set.
  const THEME_HEX = {
    primary: "#03a9f4", accent: "#ff9800", red: "#f44336", pink: "#e91e63", purple: "#926bc7",
    "deep-purple": "#6e41ab", indigo: "#3f51b5", blue: "#2196f3", "light-blue": "#03a9f4", cyan: "#00bcd4",
    teal: "#009688", green: "#4caf50", "light-green": "#8bc34a", lime: "#cddc39", yellow: "#ffeb3b",
    amber: "#ffc107", orange: "#ff9800", "deep-orange": "#ff6f22", brown: "#795548", "light-grey": "#bdbdbd",
    grey: "#9e9e9e", "dark-grey": "#606060", "blue-grey": "#607d8b", black: "#000000", white: "#ffffff",
  };

  // A colour's red, green and blue - of a name or a hex value - or null.
  function rgbOf(value) {
    let hex = typeof value === "string" ? THEME_HEX[value] || value : "";
    if (/^#[0-9a-f]{3}$/i.test(hex)) hex = "#" + [...hex.slice(1)].map((digit) => digit + digit).join("");
    if (!/^#[0-9a-f]{6}$/i.test(hex)) return null;
    return [1, 3, 5].map((at) => parseInt(hex.slice(at, at + 2), 16));
  }

  // Whether two colours are easily told apart.
  const coloursApart = (a, b) => Math.hypot(a[0] - b[0], a[1] - b[1], a[2] - b[2]) > 100;

  // An instrument's own colour as CSS: one of those by its name, or a hex
  // value. Anything else is no colour.
  function ownColor(value) {
    if (typeof value !== "string") return "";
    if (THEME_COLORS.has(value)) return `var(--${value}-color)`;
    return /^#(?:[0-9a-f]{3}|[0-9a-f]{6})$/i.test(value) ? value : "";
  }

  const ALLOC_VIEWS = ["none", "ring", "bar", "tiles"];
  const allocView = (config) => (ALLOC_VIEWS.includes(config.alloc_view) ? config.alloc_view : "ring");
  // Whether it can show the list of shares and values: not as tiles, and
  // not where the list is of gains with no button that leads back.
  const allocSharesShown = (config) =>
    allocView(config) !== "tiles" &&
    !(allocView(config) === "none" && config.alloc_list === "gain" && config.show_alloc_switch === false);
  // Whether the card can show the list of gains: it starts with it, or its
  // button leads there.
  const allocGainsShown = (config) =>
    config.layout === "allocation" &&
    allocView(config) === "none" &&
    (config.alloc_list === "gain" || config.show_alloc_switch !== false);

  // Tiles as large as their values, laid into a box: the values - largest
  // first - are halved again and again, the halves side by side or one
  // above the other. Gives each value's place in the box, in its own units.
  function tileRects(values, x, y, w, h, out = [], at = 0) {
    if (values.length <= 1) {
      if (values.length) out[at] = { x, y, w, h };
      return out;
    }
    const total = values.reduce((sum, value) => sum + value, 0) || 1;
    let first = 0;
    let cut = 0;
    while (cut < values.length - 1) {
      first += values[cut++];
      if (first >= total / 2) break;
    }
    const share = first / total;
    // Side by side only in a box more than twice as wide as high: a tile
    // carries a line of text, and reads better wide than tall.
    if (w >= h * 2) {
      tileRects(values.slice(0, cut), x, y, w * share, h, out, at);
      tileRects(values.slice(cut), x + w * share, y, w * (1 - share), h, out, at + cut);
    } else {
      tileRects(values.slice(0, cut), x, y, w, h * share, out, at);
      tileRects(values.slice(cut), x, y + h * share, w, h * (1 - share), out, at + cut);
    }
    return out;
  }

  // The instruments a card can show: those of its group, or - with no
  // group set, or one that is gone - all of them.
  function instrumentsOf(config) {
    const every = INSTRUMENTS.list || [];
    if (config && config.layout === "allocation") {
      const group = groupOf(config);
      return group ? every.filter((instrument) => instrument.group === group) : every;
    }
    const chosen = groupsOf(config);
    return chosen.length ? every.filter((instrument) => chosen.includes(instrument.group)) : every;
  }

  // The groups a card of the other formats shows, by their ids - empty for
  // all. A card from before several could be chosen names one, as "group".
  function groupsOf(config) {
    const known = new Set(INSTRUMENTS.groups.map((group) => group.id));
    const listed = config && Array.isArray(config.groups) ? config.groups.filter((id) => known.has(id)) : [];
    if (listed.length) return listed;
    return config && typeof config.group === "string" && known.has(config.group) ? [config.group] : [];
  }

  // The group a card shows, by its id - empty for all. The Portfolio format
  // is of one portfolio: the one set, or the first there is.
  function groupOf(config) {
    const set = config && config.group;
    if (config && config.layout === "allocation") {
      const portfolios = INSTRUMENTS.groups.filter((group) => group.kind === "portfolio");
      const chosen = portfolios.find((group) => group.id === set) || portfolios[0];
      return chosen ? chosen.id : "";
    }
    // Elsewhere: the one group where the card shows just one.
    const chosen = groupsOf(config);
    return chosen.length === 1 ? chosen[0] : "";
  }

  async function askInstruments() {
    const hass = liveHass;
    if (INSTRUMENTS.asking || !hass || !hass.connection) return;
    INSTRUMENTS.asking = true;
    INSTRUMENTS.stale = false;
    const key = sensorKey(hass);
    try {
      const answer = await hass.connection.sendMessagePromise({ type: `${DOMAIN}/instruments` });
      const list = answer && Array.isArray(answer.instruments) ? answer.instruments : [];
      INSTRUMENTS.list = list.filter((item) => item && typeof item.id === "string" && item.id);
      INSTRUMENTS.groups = (answer && Array.isArray(answer.groups) ? answer.groups : []).filter(
        (group) => group && typeof group.id === "string" && group.id
      );
      INSTRUMENTS.base = (answer && typeof answer.base_currency === "string" && answer.base_currency) || "";
      INSTRUMENTS.attribution = attributionOf(answer && answer.logo_attribution);
      // The uploaded logos' addresses are signed, and the signature runs
      // out: when they were handed out, and when to ask for new ones.
      INSTRUMENTS.signedAt = Date.now();
      INSTRUMENTS.renew = (answer && Number(answer.logo_renew) > 0 ? Number(answer.logo_renew) : 12 * 3600) * 1000;
      INSTRUMENTS.key = key;
      INSTRUMENTS.version += 1;
      INSTRUMENTS.tries = 0;
      INSTRUMENTS.failed = false;
    } catch (err) {
      INSTRUMENTS.failed = true;
      // Nobody left to draw for: the next card to appear asks again.
      if (LISTENERS.size) {
        const wait = ASK_AGAIN[Math.min(INSTRUMENTS.tries, ASK_AGAIN.length - 1)];
        INSTRUMENTS.tries += 1;
        INSTRUMENTS.timer = setTimeout(() => {
          INSTRUMENTS.timer = null;
          askInstruments();
        }, wait * 1000);
      }
    } finally {
      INSTRUMENTS.asking = false;
    }
    notify();
    // The sensors moved on while the answer was under way.
    if (!INSTRUMENTS.failed && liveHass && (INSTRUMENTS.stale || sensorKey(liveHass) !== INSTRUMENTS.key)) {
      askInstruments();
    }
  }

  // The uploaded logos are served to who is signed in, by an address with
  // a signature that is good for a day. A dashboard on a wall stays open
  // for weeks: so the addresses are asked for again while the old ones are
  // still good - on a timer, and when the page is looked at again after a
  // tablet slept through the timer.
  const OWN_LOGO_PATH = "/api/market_ticker_ultra/logo/";
  const isOwnLogo = (src) => typeof src === "string" && src.startsWith(OWN_LOGO_PATH);
  const hasOwnLogos = () => (INSTRUMENTS.list || []).some((item) => isOwnLogo(item.logo));
  function renewOwnLogos(force) {
    if (!liveHass || !hasOwnLogos()) return;
    if (!force && Date.now() - (INSTRUMENTS.signedAt || 0) < (INSTRUMENTS.renew || 12 * 3600 * 1000)) return;
    INSTRUMENTS.stale = true;
    watchInstruments(liveHass);
  }
  setInterval(() => renewOwnLogos(false), 10 * 60 * 1000);
  document.addEventListener("visibilitychange", () => {
    if (document.visibilityState === "visible") renewOwnLogos(false);
  });
  // An uploaded logo that did not load: its signature has run out, or Home
  // Assistant was restarted and signs anew. The addresses are asked for
  // again, a few times at most per picture - one that still does not load
  // then is a broken file, and gets the disc with the letter.
  const OWN_LOGO_TRIES = new Map();
  let ownLogoAsked = 0;
  function ownLogoFailed(src) {
    const path = src.split("?")[0];
    const tries = (OWN_LOGO_TRIES.get(path) || 0) + 1;
    OWN_LOGO_TRIES.set(path, tries);
    if (tries > 3) return false;
    if (Date.now() - ownLogoAsked > 15000) {
      ownLogoAsked = Date.now();
      renewOwnLogos(true);
    }
    // Still the same address a moment later: asking again brought no new
    // one, so it is the file that does not load.
    setTimeout(() => {
      if (LOGO_FAILED.has(src) || !(INSTRUMENTS.list || []).some((item) => item.logo === src)) return;
      LOGO_FAILED.add(src);
      notify();
    }, 8000);
    return true;
  }

  // How many of the instruments' sensors are not there right now.
  function sensorsAway(hass) {
    let away = 0;
    for (const instrument of INSTRUMENTS.list || []) {
      const state = hass.states ? hass.states[instrument.entity_id] : null;
      if (!state || state.state === "unavailable") away += 1;
    }
    return away;
  }
  let awayBefore = 0;

  // Called with every hass a card or an editor is handed.
  function watchInstruments(hass) {
    if (!hass) return;
    liveHass = hass;
    watchNewsSeen(hass);
    // A sensor that comes back was away - as all of them are while the
    // integration is loaded again, after its options changed: whether
    // there are logos is one of them, and nothing in the set of sensors
    // says so. The list is asked for again; that costs no request to any
    // source.
    const away = sensorsAway(hass);
    if (away < awayBefore) INSTRUMENTS.stale = true;
    awayBefore = away;
    if (INSTRUMENTS.asking || INSTRUMENTS.timer) return;
    if (INSTRUMENTS.list && !INSTRUMENTS.failed && !INSTRUMENTS.stale && sensorKey(hass) === INSTRUMENTS.key) return;
    askInstruments();
  }

  // An instrument was added, changed or removed from a card: the
  // integration loads its entry again, and the list is different a moment
  // later - how much later is its business. So the list is asked for now
  // and a few times more, rather than taken to be what the dialog said.
  const REFRESH_AFTER = [0, 1500, 4000, 9000];
  function refreshInstruments() {
    for (const wait of REFRESH_AFTER) {
      setTimeout(() => {
        INSTRUMENTS.stale = true;
        if (liveHass) watchInstruments(liveHass);
      }, wait);
    }
  }

  // The instruments a card shows: all of them in the integration's order,
  // or the chosen ones in the order they were chosen in. One that no longer
  // exists is passed over.
  function pickInstruments(list, chosen) {
    const ids = Array.isArray(chosen) ? chosen.filter((id) => typeof id === "string" && id) : [];
    if (!ids.length) return (list || []).slice();
    const byId = new Map((list || []).map((item) => [item.id, item]));
    const seen = new Set();
    const out = [];
    for (const id of ids) {
      if (seen.has(id) || !byId.has(id)) continue;
      seen.add(id);
      out.push(byId.get(id));
    }
    return out;
  }

  // An instrument with what its sensor says right now. Without a price -
  // the sensor unavailable, or gone - it keeps the name the integration
  // knows it by and nothing else.
  function quoteOf(hass, instrument) {
    const state = hass && hass.states ? hass.states[instrument.entity_id] : null;
    const attrs = (state && state.attributes) || {};
    const raw = state ? state.state : null;
    const price = raw === null || raw === "unavailable" || raw === "unknown" ? null : toNumber(raw);
    const symbol = instrument.symbol || attrs.symbol || "";
    // Where it is quoted and in which currency it is shown: what its chart
    // and its figures are kept under (see listingOf).
    LISTINGS.set(instrument.id, symbol + "|" + (attrs.unit_of_measurement || instrument.currency || ""));
    return {
      id: instrument.id,
      entity_id: instrument.entity_id,
      name: instrument.name || attrs.instrument_name || attrs.friendly_name || symbol || instrument.id,
      symbol,
      type: instrument.type || attrs.instrument_type || "",
      exchange: instrument.exchange || attrs.exchange || "",
      // An index stands in points: it has no currency, whatever its source
      // names for it.
      currency:
        (instrument.type || attrs.instrument_type) === "INDEX" ? "" : attrs.unit_of_measurement || instrument.currency || "",
      digits: toNumber(instrument.precision),
      // What TradingView calls the instrument, where the integration knows.
      tradingview: typeof instrument.tradingview === "string" && instrument.tradingview ? instrument.tradingview : null,
      // A logo the user uploaded: the logo source's line is not owed for it.
      logoOwn: instrument.logo_own === true,
      logo: typeof instrument.logo === "string" && instrument.logo ? instrument.logo : null,
      position: instrument.position && typeof instrument.position === "object" ? instrument.position : null,
      // What sales realised and what was paid in fees and taxes.
      ledger: instrument.ledger && typeof instrument.ledger === "object" ? instrument.ledger : null,
      group: typeof instrument.group === "string" ? instrument.group : "",
      // The colour it is given in the integration, for a portfolio's shares.
      color: ownColor(instrument.color),
      // The same as it was set: a name or a hex value.
      colorKey: ownColor(instrument.color) ? instrument.color : "",
      // The price alerts' limits, and one unit of the currency in the
      // currency positions are added up in.
      alertBelow: toNumber(instrument.alert_below),
      alertAbove: toNumber(instrument.alert_above),
      baseRate: toNumber(instrument.base_rate),
      unavailable: price === null,
      price,
      change: price === null ? null : toNumber(attrs.change),
      changePct: price === null ? null : toNumber(attrs.change_percent),
      previousClose: toNumber(attrs.previous_close),
      dayLow: toNumber(attrs.day_low),
      dayHigh: toNumber(attrs.day_high),
      yearLow: toNumber(attrs.fifty_two_week_low),
      yearHigh: toNumber(attrs.fifty_two_week_high),
      volume: toNumber(attrs.volume),
      marketState: typeof attrs.market_state === "string" ? attrs.market_state : "",
      stamp: state ? `${state.state}|${state.last_updated || ""}` : "",
    };
  }

  function sortItems(items, sort, locale) {
    const list = items.slice();
    if (sort === "name") {
      list.sort((a, b) => String(a.name).localeCompare(String(b.name), locale));
    } else if (sort === "change") {
      // The biggest rise first; one without a figure goes last.
      const change = (item) => (isNumber(item.changePct) ? item.changePct : -Infinity);
      list.sort((a, b) => change(b) - change(a));
    }
    return list;
  }

  // Charts and company figures, kept per instrument for a while: a pop-up
  // opened twice does not ask twice, and the small curves of a row do not
  // ask on every price.
  const HISTORY = new Map();
  const DETAILS = new Map();
  // An instrument keeps its id when it is moved to another listing or
  // shown in another currency - its chart and its figures are others then.
  // So they are kept under its listing too, and what was kept before no
  // longer fits: the new ones are asked for at once.
  const LISTINGS = new Map();
  const listingOf = (id) => LISTINGS.get(id) || "";
  const HISTORY_FRESH = { "1d": 120, "5d": 300 };
  const HISTORY_FRESH_LONG = 1800;
  const DETAILS_FRESH = 900;
  // After an answer that was an error, this long before asking by itself
  // again. The pop-up's "Try again" does not wait.
  const ERROR_PAUSE = 60;
  // A few at a time: a carousel of twenty instruments would otherwise send
  // twenty requests in one go to a source that counts them.
  const ASK_AT_ONCE = 3;
  const queue = [];
  let asking = 0;

  function pump() {
    while (asking < ASK_AT_ONCE && queue.length) {
      const job = queue.shift();
      asking += 1;
      job().then(() => {
        asking -= 1;
        pump();
      });
    }
  }

  function ask(entry, message, read, first) {
    if (entry.asking) return;
    entry.asking = true;
    const job = async () => {
      const hass = liveHass;
      try {
        if (!hass || !hass.connection) throw new Error("no connection");
        entry.data = read(await hass.connection.sendMessagePromise(message));
        entry.at = Date.now();
        entry.error = false;
      } catch (err) {
        entry.error = true;
        entry.errorAt = Date.now();
      } finally {
        entry.asking = false;
      }
      notify();
    };
    if (first) queue.unshift(job);
    else queue.push(job);
    pump();
  }

  const isFresh = (entry, seconds) =>
    (entry.data && Date.now() - entry.at < seconds * 1000) ||
    (entry.error && Date.now() - entry.errorAt < ERROR_PAUSE * 1000);

  // { data, error, asking } - and the request on its way where what is
  // there is too old. `first` puts it ahead of the small curves' requests;
  // `force` asks whatever the age.
  function historyOf(id, range, first, force) {
    const key = `${id}|${listingOf(id)}|${range}`;
    let entry = HISTORY.get(key);
    if (!entry) {
      entry = { data: null, at: 0, error: false, errorAt: 0, asking: false };
      HISTORY.set(key, entry);
    }
    if (force || !isFresh(entry, HISTORY_FRESH[range] || HISTORY_FRESH_LONG)) {
      ask(entry, { type: `${DOMAIN}/history`, instrument: id, range }, normalizeHistory, first);
    }
    return entry;
  }

  // A portfolio's performance over a period, kept the same way.
  const PERFORMANCE = new Map();
  const PERF_RANGES = ["1d", "5d", "1mo", "3mo", "6mo", "1y", "5y", "max"];
  // The periods the performance offers: those ticked in the editor, in
  // their own order.
  function perfRanges(config) {
    const on = Array.isArray(config.perf_ranges) ? config.perf_ranges : PERF_RANGES;
    return PERF_RANGES.filter((key) => on.includes(key));
  }

  function performanceOf(group, range) {
    const key = `${group}|${range}`;
    let entry = PERFORMANCE.get(key);
    if (!entry) {
      entry = { data: null, at: 0, error: false, errorAt: 0, asking: false };
      PERFORMANCE.set(key, entry);
    }
    // Asked again soon: the integration keeps the answer itself, and knows
    // when the purchases or the index have changed.
    if (!isFresh(entry, 120)) {
      ask(entry, { type: `${DOMAIN}/performance`, group, range }, (answer) => answer || {}, true);
    }
    return entry;
  }

  // The news about an instrument: asked for when its details are opened.
  // The integration keeps them half an hour itself.
  const NEWS = new Map();
  function newsOf(id, language) {
    const key = `${id}|${language || ""}`;
    let entry = NEWS.get(key);
    if (!entry) {
      entry = { data: null, at: 0, error: false, errorAt: 0, asking: false };
      NEWS.set(key, entry);
    }
    if (!isFresh(entry, 600)) {
      const wanted = language ? { language } : {};
      ask(entry, { type: `${DOMAIN}/news`, instrument: id, ...wanted }, (answer) => (answer && Array.isArray(answer.news) ? answer.news : []), true);
    }
    return entry;
  }

  // How much of an MDI symbol's 24-unit box its drawing fills, and how much
  // is left empty under it - read off the shape, the same at any size, and
  // kept per symbol. It differs a lot from one symbol to the next, so a box
  // centred beside a word leaves the drawing itself above or below it.
  const ICON_INK = new Map();
  function iconInk(el) {
    // The attribute: on an element just written with innerHTML the property
    // is not there yet.
    const name = el.getAttribute("icon") || el.icon;
    if (ICON_INK.has(name)) return ICON_INK.get(name);
    try {
      const inner = el.shadowRoot && el.shadowRoot.querySelector("ha-svg-icon");
      const svg = inner && inner.shadowRoot && inner.shadowRoot.querySelector("svg");
      if (!svg) return null;
      const view = Number((svg.getAttribute("viewBox") || "0 0 24 24").split(/\s+/)[3]) || 24;
      const box = svg.getBBox();
      if (!(box.height > 0)) return null;
      const ink = { fill: box.height / view, below: (view - (box.y + box.height)) / view };
      ICON_INK.set(name, ink);
      return ink;
    } catch (err) {
      return null;
    }
  }

  // An instrument's price alerts: none set, set, or on - the price is at
  // or beyond a limit.
  function alertState(item) {
    const below = isNumber(item.alertBelow);
    const above = isNumber(item.alertAbove);
    if (!below && !above) return "";
    const now = item.price;
    if (isNumber(now) && ((below && now <= item.alertBelow) || (above && now >= item.alertAbove))) return "on";
    return "set";
  }
  // The alert's symbol as Layout has it: while an alert is on, while one
  // is set, and where there is none.
  const alertIcon = (config, state) =>
    toolIcon(config, state === "on" ? "alert_on" : state === "set" ? "alert" : "alert_none");

  // Which headlines are new: those published since the user last had the
  // instrument's list shown - and, before they ever had, those of the last
  // day. Kept in Home Assistant with the user's own data, so that what was
  // read in one browser is read in every other; the browser keeps a copy,
  // for the moment before Home Assistant has answered.
  const NEWS_SEEN_KEY = "market-ticker-ultra-card:news-seen";
  const NEWS_SEEN_DATA = "market_ticker_ultra_news_seen";
  let NEWS_SEEN = {};
  // Counted up with every change, for whoever keeps what was drawn.
  let NEWS_SEEN_VERSION = 0;
  try {
    const kept = JSON.parse(localStorage.getItem(NEWS_SEEN_KEY) || "null");
    if (kept && typeof kept === "object") NEWS_SEEN = kept;
  } catch (err) {
    // No storage in this browser: new is what the last day brought.
  }
  const newsSeen = (id) => {
    const at = Number(NEWS_SEEN[id]);
    return Number.isFinite(at) && at > 0 ? at : Date.now() - 86400000;
  };
  // What was seen before this page showed the list: a headline keeps its
  // mark while the page is open, though the list has been looked at.
  const NEWS_BASE = new Map();
  const newsBase = (id) => {
    if (!NEWS_BASE.has(id)) NEWS_BASE.set(id, newsSeen(id));
    return NEWS_BASE.get(id);
  };
  const newsIsNew = (item, id, since) => !!item.published && Date.parse(item.published) > since(id);
  const keepNewsSeenHere = () => {
    try {
      localStorage.setItem(NEWS_SEEN_KEY, JSON.stringify(NEWS_SEEN));
    } catch (err) {
      // Holds until the page is reloaded.
    }
  };
  // What Home Assistant knows, taken in: of each instrument the later of
  // the two moments.
  let newsSeenLoaded = false;
  function mergeNewsSeen(value) {
    // The first answer: the marks drawn before it were guesses.
    if (!newsSeenLoaded) NEWS_BASE.clear();
    const first = !newsSeenLoaded;
    newsSeenLoaded = true;
    let changed = false;
    if (value && typeof value === "object") {
      for (const [id, at] of Object.entries(value)) {
        const moment = Number(at);
        if (Number.isFinite(moment) && moment > (Number(NEWS_SEEN[id]) || 0)) {
          NEWS_SEEN[id] = moment;
          changed = true;
        }
      }
    }
    if (!changed && !first) return;
    NEWS_SEEN_VERSION += 1;
    keepNewsSeenHere();
    notify();
  }
  // Listened to for as long as the connection lasts: another browser of
  // the same user marks them seen, and they are seen here.
  let newsSeenConnection = null;
  function watchNewsSeen(hass) {
    const connection = hass && hass.connection;
    if (!connection || connection === newsSeenConnection) return;
    newsSeenConnection = connection;
    connection
      .subscribeMessage((message) => mergeNewsSeen(message && message.value), {
        type: "frontend/subscribe_user_data",
        key: NEWS_SEEN_DATA,
      })
      .catch(() =>
        // A Home Assistant that cannot be listened to is asked once.
        connection
          .sendMessagePromise({ type: "frontend/get_user_data", key: NEWS_SEEN_DATA })
          .then((answer) => mergeNewsSeen(answer && answer.value))
          .catch(() => {})
      );
  }
  function markNewsSeen(ids) {
    if (!ids || !ids.length) return;
    const now = Date.now();
    for (const id of ids) {
      newsBase(id);
      NEWS_SEEN[id] = now;
    }
    // Instruments that are gone are not kept for ever.
    const known = new Set((INSTRUMENTS.list || []).map((instrument) => instrument.id));
    if (known.size) for (const id of Object.keys(NEWS_SEEN)) if (!known.has(id)) delete NEWS_SEEN[id];
    NEWS_SEEN_VERSION += 1;
    keepNewsSeenHere();
    const hass = liveHass;
    if (hass && hass.connection) {
      hass.connection
        .sendMessagePromise({ type: "frontend/set_user_data", key: NEWS_SEEN_DATA, value: NEWS_SEEN })
        .catch(() => {});
    }
    notify();
  }

  // The headlines a list shows: with a link, none older than so many days
  // (0: all), and no more than so many.
  function newsShown(items, wanted, limit) {
    const count = Math.max(1, Math.min(20, Math.round(Number(wanted)) || 5));
    const days = Number(limit) > 0 ? Number(limit) : 0;
    const since = days ? Date.now() - days * 86400000 : 0;
    if (!Array.isArray(items)) return [];
    return (
      items
        .filter((item) => item && typeof item.title === "string" && /^https?:\/\//i.test(item.url || ""))
        // With a limit on their age, one without a time is not shown:
        // nobody can say how old it is.
        .filter((item) => !since || (item.published && Date.parse(item.published) >= since))
        .slice(0, count)
    );
  }

  // The news about everything a portfolio holds.
  function groupNewsOf(group, language) {
    const key = `group:${group}|${language || ""}`;
    let entry = NEWS.get(key);
    if (!entry) {
      entry = { data: null, at: 0, error: false, errorAt: 0, asking: false };
      NEWS.set(key, entry);
    }
    if (!isFresh(entry, 600)) {
      const wanted = language ? { language } : {};
      ask(entry, { type: `${DOMAIN}/news`, group, ...wanted }, (answer) => (answer && Array.isArray(answer.news) ? answer.news : []), true);
    }
    return entry;
  }

  // The same, without asking: what is there already, if anything.
  const historyKept = (id, range) => HISTORY.get(`${id}|${listingOf(id)}|${range}`) || null;

  function detailsOf(id) {
    const key = id + "|" + listingOf(id);
    let entry = DETAILS.get(key);
    if (!entry) {
      entry = { data: null, at: 0, error: false, errorAt: 0, asking: false };
      DETAILS.set(key, entry);
    }
    if (!isFresh(entry, DETAILS_FRESH)) {
      ask(entry, { type: `${DOMAIN}/details`, instrument: id }, (answer) => answer || {}, true);
    }
    return entry;
  }

  // ------------------------------------------------------------------ logos
  //
  // The instrument's logo; where there is none - the integration serves
  // none, or the picture did not load - a disc with its first letter in a
  // colour of its own, taken from its id so that it is the same one every
  // time. Always an <img>: a logo is somebody else's picture, and nothing
  // inside an image can run.
  const LOGO_FAILED = new Set();
  const hasLogo = (item) => !!item.logo && !LOGO_FAILED.has(item.logo);

  function logoHtml(item, big) {
    if (hasLogo(item)) {
      return `<span class="logo pic${big ? " big" : ""}"><img src="${escapeHtml(item.logo)}" alt="" loading="lazy" referrerpolicy="no-referrer"></span>`;
    }
    const seed = String(item.id || item.symbol || item.name || "?");
    let hash = 0;
    for (let i = 0; i < seed.length; i += 1) hash = (hash * 31 + seed.charCodeAt(i)) % 360;
    const letter = String(item.name || item.symbol || seed).trim().charAt(0).toUpperCase() || "?";
    return (
      `<span class="logo${big ? " big" : ""}" style="background: hsl(${hash} 45% 38%)">` +
      `${escapeHtml(letter)}</span>`
    );
  }

  // The line the logos' source asks for: its own words, linked to its own
  // page, in a new tab. It stands in the card's editor and in the README -
  // nowhere on the card itself, neither on its face nor in the details.
  function creditHtml(attribution) {
    if (!attribution) return "";
    return attribution.url
      ? `<a class="credit" href="${escapeHtml(attribution.url)}" target="_blank" rel="noopener noreferrer">${escapeHtml(attribution.text)}</a>`
      : `<span class="credit">${escapeHtml(attribution.text)}</span>`;
  }

  // ------------------------------------------------------------------ charts
  //
  // One curve as an SVG. The points are spread evenly rather than by their
  // time: a week of prices has no night and no weekend in it, and a curve
  // that drew those gaps would be mostly straight lines across nothing.
  //
  // Above the reference the curve is drawn in the gain colour, below it in
  // the loss colour - one stroke with a gradient that changes colour at the
  // reference's height, so the change falls exactly where the curve crosses.
  let chartIds = 0;
  function chartSvg(values, options) {
    const opts = options || {};
    const height = opts.height || 40;
    const pad = opts.pad === undefined ? 2 : opts.pad;
    if (!values || values.length < 2) return "";
    const reference = isNumber(opts.reference) ? opts.reference : values[0];
    let low = isNumber(opts.low) ? opts.low : Math.min(reference, ...values);
    let high = isNumber(opts.high) ? opts.high : Math.max(reference, ...values);
    if (high === low) { high += 1; low -= 1; }
    const y = (value) => pad + ((high - value) / (high - low)) * (height - 2 * pad);
    const step = 100 / (values.length - 1);
    const gaps = opts.gaps || [];
    const x = (i) => (i * step).toFixed(2);
    // A path over a stretch of points, lifted at every flagged one.
    const stretch = (from, to) => {
      let d = "";
      let drawing = false;
      for (let i = from; i <= to; i++) {
        if (gaps[i]) {
          drawing = false;
          continue;
        }
        d += `${drawing ? "L" : "M"}${x(i)},${y(values[i]).toFixed(2)}`;
        drawing = true;
      }
      return d;
    };
    // The stretches between two points that are not flagged - the runs the
    // fill is closed over - and the runs of flagged points, greyed.
    const runs = (from, to, flagged) => {
      const found = [];
      let start = -1;
      for (let i = from; i <= to + 1; i++) {
        const is = i <= to && !!gaps[i] === flagged;
        if (is && start < 0) start = i;
        if (!is && start >= 0) {
          found.push([start, i - 1]);
          start = -1;
        }
      }
      return found;
    };
    // What came before the reference - the day before, in a one-day chart -
    // is drawn grey: it is there for the eye
    // to see where the price came from, and is not part of the change.
    const cut = Math.max(0, Math.min(values.length - 2, opts.cut || 0));
    const before = cut > 0 ? stretch(0, cut) : "";
    const line = stretch(cut, values.length - 1);
    const lineStart = (cut * step).toFixed(2);
    const refY = y(reference);
    const split = Math.max(0, Math.min(1, refY / height));
    const fillPath = runs(cut, values.length - 1, false)
      .filter(([from, to]) => to > from)
      .map(([from, to]) => `${stretch(from, to)}L${x(to)},${refY.toFixed(2)}L${x(from)},${refY.toFixed(2)}Z`)
      .join("");
    // Across every hole a grey line, from the last figure read before it
    // to the first read after - the flagged points lie on that line, so
    // the path runs straight through them.
    const bridges = runs(0, values.length - 1, true)
      .map(([from, to]) => {
        const left = Math.max(0, from - 1);
        const right = Math.min(values.length - 1, to + 1);
        let d = "";
        for (let i = left; i <= right; i++) d += `${d ? "L" : "M"}${x(i)},${y(values[i]).toFixed(2)}`;
        return d;
      })
      .join("");
    chartIds += 1;
    const id = `mt${chartIds}`;
    const width = opts.lineWidth || 1.5;
    return (
      `<svg viewBox="0 0 100 ${height}" preserveAspectRatio="none" aria-hidden="true">` +
      `<defs>` +
      `<linearGradient id="${id}l" gradientUnits="userSpaceOnUse" x1="0" y1="0" x2="0" y2="${height}">` +
      `<stop offset="${split}" style="stop-color: var(--mt-gain)"/>` +
      `<stop offset="${split}" style="stop-color: var(--mt-loss)"/>` +
      `</linearGradient>` +
      // The fill lies between the curve and the reference: strongest where
      // the curve is furthest from it, gone where the two meet - in the gain
      // colour above the reference and in the loss colour below.
      `<linearGradient id="${id}f" gradientUnits="userSpaceOnUse" x1="0" y1="0" x2="0" y2="${height}">` +
      `<stop offset="0" style="stop-color: var(--mt-gain); stop-opacity: 0.4"/>` +
      `<stop offset="${split}" style="stop-color: var(--mt-gain); stop-opacity: 0"/>` +
      `<stop offset="${split}" style="stop-color: var(--mt-loss); stop-opacity: 0"/>` +
      `<stop offset="1" style="stop-color: var(--mt-loss); stop-opacity: 0.5"/>` +
      `</linearGradient>` +
      `</defs>` +
      (opts.fill ? `<path d="${fillPath}" fill="url(#${id}f)" stroke="none"/>` : "") +
      (bridges
        ? `<path d="${bridges}" class="gap" fill="none" stroke-width="${width}"` +
          ` stroke-linejoin="round" stroke-linecap="round" vector-effect="non-scaling-stroke"/>`
        : "") +
      (opts.showReference
        ? `<line x1="${lineStart}" x2="100" y1="${refY.toFixed(2)}" y2="${refY.toFixed(2)}" class="ref"` +
          ` vector-effect="non-scaling-stroke"/>`
        : "") +
      (before
        ? `<path d="${before}" class="before" fill="none" stroke-width="${width}"` +
          ` stroke-linejoin="round" stroke-linecap="round" vector-effect="non-scaling-stroke"/>`
        : "") +
      `<path d="${line}" fill="none" stroke="url(#${id}l)" stroke-width="${width}"` +
      ` stroke-linejoin="round" stroke-linecap="round" vector-effect="non-scaling-stroke"/>` +
      `</svg>`
    );
  }

  // Round figures along a chart's side -
  // 50, 100, 150 rather than 82.00 and -33.87: a step of 1, 2, 4 or 5
  // times a power of ten, the smallest that puts the curve inside six
  // intervals or fewer, and the chart's edges moved out to the round
  // figures on either side of the curve.
  function niceScale(low, high) {
    const span = Math.max(high - low, 1e-9);
    const magnitude = Math.pow(10, Math.floor(Math.log10(span)) - 1);
    let step = magnitude;
    for (const power of [1, 10, 100]) {
      for (const unit of [1, 2, 4, 5]) {
        step = unit * power * magnitude;
        if (Math.ceil(high / step) - Math.floor(low / step) <= 6) break;
      }
      if (Math.ceil(high / step) - Math.floor(low / step) <= 6) break;
    }
    const bottom = Math.floor(low / step) * step;
    const top = Math.ceil(high / step) * step;
    const ticks = [];
    for (let tick = top; tick >= bottom - step / 2; tick -= step) ticks.push(Math.round(tick * 1e6) / 1e6);
    return { low: bottom, high: top, step, ticks };
  }

  function chartScale(values, reference, height, pad) {
    const ref = isNumber(reference) ? reference : values[0];
    let low = Math.min(ref, ...values);
    let high = Math.max(ref, ...values);
    if (high === low) { high += 1; low -= 1; }
    const nice = niceScale(low, high);
    low = nice.low;
    high = nice.high;
    return {
      low,
      high,
      ticks: nice.ticks,
      top: (value) => ((pad + ((high - value) / (high - low)) * (height - 2 * pad)) / height) * 100,
    };
  }

  // The pop-up's chart: three drawings over one set of slots - the prices
  // as candlesticks or a line with the three trend lines, the volume's bars
  // and the RSI - each an SVG that is stretched to its box, so every x is a
  // share of the width and every y a share of the height. What the pointer
  // reads off them comes back as `series`.
  function drawChart(history, options) {
    const opts = options || {};
    const bars = history.bars;
    const layout = slotLayout(history);
    const count = layout.count;
    const xs = layout.slots.map((slot) => ((slot + 0.5) / count) * 100);
    const closes = bars.map((bar) => bar.c);
    // Worked out over the bars before the period too, and then cut to the
    // ones that are drawn: a 20-bar average has its 20 bars at the left edge.
    const before = (history.lead || []).map((bar) => bar.c);
    const withLead = before.concat(closes);
    const smaLine = sma(withLead, 20).slice(before.length);
    const sma50Line = sma(withLead, 50).slice(before.length);
    const emaLine = ema(withLead, 9).slice(before.length);
    const rsiLine = rsi(withLead, 14).slice(before.length);
    // A series that is one figure per bar - a reference rate, fixed once a
    // day - has no candles to draw: each would be a dash. It is a line.
    const ranged = bars.some((bar) => bar.h !== bar.l || bar.o !== bar.c);
    const candles = opts.style === "candles" && ranged;
    const reference = isNumber(opts.reference) ? opts.reference : null;

    const values = [];
    for (const bar of bars) {
      if (candles) values.push(bar.h, bar.l);
      else values.push(bar.c);
    }
    if (opts.trend.sma) for (const value of smaLine) if (value !== null) values.push(value);
    if (opts.trend.sma50) for (const value of sma50Line) if (value !== null) values.push(value);
    if (opts.trend.ema) for (const value of emaLine) if (value !== null) values.push(value);
    if (isNumber(opts.last)) values.push(opts.last);
    // What a period is measured against - its starting value: the close of
    // the day before on a day's chart, otherwise the last close before the
    // period where the series brings one, and its first close where not.
    // The same value the change under the price is worked out from.
    const base = reference === null ? (before.length ? before[before.length - 1] : closes[0]) : reference;
    const scale = chartScale(values, base, 100, 4);
    const f = (number) => number.toFixed(2);
    const y = (value) => scale.top(value);
    const still = ` vector-effect="non-scaling-stroke"`;
    const last = isNumber(opts.last) ? opts.last : closes[closes.length - 1];

    const curve = (series, top) => {
      let d = "";
      let drawing = false;
      series.forEach((value, i) => {
        if (value === null) {
          drawing = false;
          return;
        }
        d += `${drawing ? "L" : "M"}${f(xs[i])},${f(top(value))}`;
        drawing = true;
      });
      return d;
    };

    let price = scale.ticks
      .map((tick) => `<line class="grid" x1="0" x2="100" y1="${f(y(tick))}" y2="${f(y(tick))}"${still}/>`)
      .join("");
    {
      // The starting value as a dashed line across the chart: where the
      // line changes its colour.
      price += `<line class="ref" x1="0" x2="100" y1="${f(y(base))}" y2="${f(y(base))}"${still}/>`;
    }
    const half = Math.max(0.08, (100 / count) * 0.34);
    if (candles) {
      const wick = { up: "", down: "" };
      const body = { up: "", down: "" };
      bars.forEach((bar, i) => {
        const side = bar.c >= bar.o ? "up" : "down";
        const x = xs[i];
        wick[side] += `M${f(x)},${f(y(bar.h))}V${f(y(bar.l))}`;
        const top = y(Math.max(bar.o, bar.c));
        // A bar that closed where it opened still gets a line to be seen by.
        const bottom = Math.max(y(Math.min(bar.o, bar.c)), top + 0.4);
        body[side] += `M${f(x - half)},${f(top)}H${f(x + half)}V${f(bottom)}H${f(x - half)}Z`;
      });
      for (const side of ["up", "down"]) {
        if (!wick[side]) continue;
        price +=
          `<path class="wick ${side}" d="${wick[side]}" fill="none"${still}/>` +
          `<path class="body ${side}" d="${body[side]}"/>`;
      }
    } else {
      // One line drawn twice, each drawing cut to its side of the starting
      // value: above it in the gain colour, below it in the loss colour.
      // The line begins on the starting value, at the chart's left edge,
      // and runs from there to the period's first price: the step in
      // between - over a night, a weekend - is part of what the period did,
      // and a line that began beside the dashed one hid it.
      const first = curve(closes, y);
      const d = first.startsWith("M") ? `M0,${f(y(base))}L${first.slice(1)}` : first;
      const edge = Math.max(0, Math.min(100, y(base)));
      const clip = `mt-line-${++CLIP_SEQ}`;
      const drawn = (side) =>
        `<path class="line ${side}" clip-path="url(#${clip}-${side})" d="${d}" fill="none"` +
        ` stroke-linejoin="round" stroke-linecap="round"${still}/>`;
      price +=
        `<defs><clipPath id="${clip}-up"><rect x="-10" y="-10" width="120" height="${f(edge + 10)}"/></clipPath>` +
        `<clipPath id="${clip}-down"><rect x="-10" y="${f(edge)}" width="120" height="${f(110 - edge)}"/></clipPath></defs>` +
        drawn("up") +
        drawn("down");
    }
    {
      for (const [name, series] of [["ema", emaLine], ["sma", smaLine], ["sma50", sma50Line]]) {
        if (!opts.trend[name] || !TREND[name]) continue;
        const d = curve(series, y);
        if (d) price += `<path class="${name}" d="${d}" fill="none" stroke-linejoin="round"${still}/>`;
      }
    }

    // The volume, from nought at the bottom to the largest bar at the top.
    let volume = "";
    let volumeTop = 0;
    for (const bar of bars) if (isNumber(bar.v) && bar.v > volumeTop) volumeTop = bar.v;
    if (opts.volume && volumeTop > 0) {
      const d = { up: "", down: "" };
      bars.forEach((bar, i) => {
        if (!isNumber(bar.v) || bar.v <= 0) return;
        const top = 100 - (bar.v / volumeTop) * 100;
        d[bar.c >= bar.o ? "up" : "down"] += `M${f(xs[i] - half)},100V${f(top)}H${f(xs[i] + half)}V100Z`;
      });
      volume = ["up", "down"].map((side) => (d[side] ? `<path class="vol ${side}" d="${d[side]}"/>` : "")).join("");
    }

    // The RSI, from 0 to 100, with a little room at either edge.
    const rsiTop = (value) => 6 + ((100 - value) / 100) * 88;
    let strength = "";
    if (opts.rsi && rsiLine.some((value) => value !== null)) {
      strength =
        [100, 50, 0].map((mark) => `<line class="grid" x1="0" x2="100" y1="${f(rsiTop(mark))}" y2="${f(rsiTop(mark))}"${still}/>`).join("") +
        `<path class="rsi" d="${curve(rsiLine, rsiTop)}" fill="none" stroke-linejoin="round"${still}/>`;
    }

    const svg = (inner) =>
      inner ? `<svg viewBox="0 0 100 100" preserveAspectRatio="none" aria-hidden="true">${inner}</svg>` : "";
    return {
      price: svg(price),
      volume: svg(volume),
      rsi: svg(strength),
      scale,
      layout,
      volumeTop,
      rsiTop,
      up: last >= base,
      lastTop: y(last),
      series: {
        count,
        xs,
        bars,
        sma: smaLine,
        sma50: sma50Line,
        ema: emaLine,
        rsi: rsiLine,
        tops: closes.map((close) => y(close)),
        candles,
        base,
      },
    };
  }

  // Whether the device asks for less motion.
  const lessMotion = () => !!(window.matchMedia && window.matchMedia("(prefers-reduced-motion: reduce)").matches);

  // The ways one entry gives way to the next. "slide" is the plain strip.
  const TK_LINE_EFFECTS = ["slide", "fade", "roll", "flap", "zoom"];
  const TK_CAROUSEL_EFFECTS = ["slide", "glide", "focus", "stagger", "coverflow"];
  const TK_SWAPS = {
    fade: () => [
      [{ opacity: 1 }, { opacity: 0 }],
      [{ opacity: 0 }, { opacity: 1 }],
    ],
    roll: (way) => [
      [{ transform: "translateY(0)" }, { transform: `translateY(${-100 * way}%)` }],
      [{ transform: `translateY(${100 * way}%)` }, { transform: "translateY(0)" }],
    ],
    zoom: () => [
      [{ opacity: 1, transform: "scale(1)" }, { opacity: 0, transform: "scale(1.06)" }],
      [{ opacity: 0, transform: "scale(0.9)" }, { opacity: 1, transform: "scale(1)" }],
    ],
  };

  // The bar nearest to a place along the chart, both in percent of its width.
  function nearestIndex(xs, x) {
    let low = 0;
    let high = xs.length - 1;
    if (high < 0) return -1;
    while (high - low > 1) {
      const mid = (low + high) >> 1;
      if (xs[mid] <= x) low = mid;
      else high = mid;
    }
    return Math.abs(xs[high] - x) < Math.abs(xs[low] - x) ? high : low;
  }

  // The times along the bottom of a day drawn across its trading session:
  // from the session's start in steps of half an hour, an hour or more -
  // the smallest that makes six steps or fewer - each with its place in
  // percent of the width. None too close to the right edge to be read.
  function sessionMarks(layout) {
    if (!layout || layout.from === null || !(layout.to > layout.from)) return null;
    const span = layout.to - layout.from;
    const hour = 3600000;
    const step = [0.5, 1, 2, 3, 4, 6, 12, 24].map((hours) => hours * hour).find((size) => span / size <= 6.5) || span;
    const marks = [];
    for (let t = layout.from; t <= layout.to; t += step) {
      const at = ((t - layout.from) / span) * 100;
      if (at > 90) break;
      marks.push({ t, at });
    }
    return marks;
  }

  // What is held of an instrument, worked out: the integration says how
  // much and what it cost - or the finished figures - and what that is
  // worth follows the price the card shows, with every poll. Each figure is
  // null where there is nothing to work it out from.
  function positionFigures(item) {
    const ledger = item.ledger || {};
    const realized = toNumber(ledger.realized);
    const costs = (toNumber(ledger.fees) || 0) + (toNumber(ledger.taxes) || 0);
    // Nothing held and nothing left of what was: no position.
    if (!item.position && !realized && !costs) return null;
    const position = item.position || {};
    const held = toNumber(position.quantity);
    const cost = toNumber(position.cost);
    let value = toNumber(position.value);
    if (value === null && held !== null && isNumber(item.price)) value = held * item.price;
    let today = toNumber(position.day_change);
    if (today === null && held !== null && isNumber(item.change)) today = held * item.change;
    let gain = toNumber(position.gain);
    if (gain === null && value !== null && cost !== null) gain = value - cost;
    let gainPct = toNumber(position.gain_percent);
    if (gainPct === null && gain !== null && cost) gainPct = (gain / cost) * 100;
    return {
      held,
      cost,
      value,
      today,
      gain,
      gainPct,
      // What one unit cost on average.
      average: cost !== null && held ? cost / held : null,
      // What sales have realised so far, and the fees and taxes paid.
      realized: realized || null,
      costs: costs || null,
      currency: position.value_currency || item.currency,
    };
  }

  // The figures of the details' list, one row each: a label, its value and
  // - for the volume - a quiet word beside it. A row without a value is not
  // in the list at all: a fund has no P/E, an index no volume.
  // The figures' switches in the editor, in the order the list has by
  // itself: the name, and the words for its label and its explanation. The
  // switch of "open" is show_fact_open.
  const FACT_SWITCHES = [
    ["alert_none", "edFactAlertNone", "hAlertNone"],
    ["alert_below", "fAlertBelow", "hAlertBelow"],
    ["alert_above", "fAlertAbove", "hAlertAbove"],
    ["open", "fOpen", "hOpen"],
    ["high_low", "fHighLow", "hHighLow"],
    ["prev", "fPrev", "hPrev"],
    ["year", "f52", "h52"],
    ["volume", "fVolume", "hVolume"],
    ["cap", "fCap", "hCap"],
    ["pe", "fPe", "hPe"],
    ["eps", "fEps", "hEps"],
    ["earnings", "fEarnings", "hEarnings"],
  ];
  const FACT_NAMES = FACT_SWITCHES.map(([name]) => name);
  // What the chart is drawn with and names ahead of the figures.
  const MARK_NAMES = ["ema", "sma", "sma50", "rsi"];
  // An order from the config, made whole: the names it lists that there
  // are, and after them those it does not list, in their own order.
  function orderOf(listed, names) {
    const order = (Array.isArray(listed) ? listed : []).filter((name, at, all) => names.includes(name) && all.indexOf(name) === at);
    return order.concat(names.filter((name) => !order.includes(name)));
  }

  function factRows(hass, str, item, details, open, config, canEdit) {
    const facts = details || {};
    const currency = item.currency;
    const price = (value) => money(hass, value, currency, false, item.digits);
    // The figure the next rows belong to: left out where it is switched
    // off, and in the end put where the card's order has it.
    const found = {};
    let rows = [];
    let shown = true;
    const of = (name) => {
      shown = !config || config[`show_fact_${name}`] !== false;
      rows = found[name] = [];
    };
    const add = (label, value, sub, help, alarm, bell) => {
      if (shown && value) rows.push({ label, value, sub: sub || "", help: help || "", alarm: alarm === true, bell: bell || "" });
    };
    // Two figures on one row where both are there, the one alone under its
    // own name where only one is.
    const pair = (both, first, second, a, b, between, help) => {
      if (a && b) add(both, `${a}${between}${b}`, "", help);
      else add(a ? first : second, a || b, "", help);
    };
    of("open");
    add(str.fOpen, price(open), "", str.hOpen);
    of("high_low");
    pair(str.fHighLow, str.fHigh, str.fLow, price(item.dayHigh), price(item.dayLow), " / ", str.hHighLow);
    of("prev");
    add(str.fPrev, price(item.previousClose), "", str.hPrev);
    of("year");
    pair(str.f52, str.f52Low, str.f52High, price(item.yearLow), price(item.yearHigh), " – ", str.h52);
    of("volume");
    const usual = toNumber(facts.average_volume);
    add(
      str.fVolume,
      isNumber(item.volume) && item.volume > 0 ? compact(hass, item.volume, "", 1) : "",
      isNumber(usual) && usual > 0 ? str.vsAvg(compact(hass, usual, "", 1)) : "",
      str.hVolume
    );
    of("cap");
    add(str.fCap, compact(hass, toNumber(facts.market_cap), isCurrency(currency) ? currency : ""), "", str.hCap);
    of("pe");
    const pe = toNumber(facts.pe);
    add(str.fPe, pe === null ? "" : numberFormat(hass, { maximumFractionDigits: 2 }).format(pe), "", str.hPe);
    of("eps");
    add(str.fEps, money(hass, toNumber(facts.eps), currency), "", str.hEps);
    of("earnings");
    // The day the next quarterly figures are due - a span where the source
    // names one -, and said so where the source only estimates it.
    const dayText = (text) => {
      const date = typeof text === "string" ? new Date(`${text}T00:00:00`) : null;
      return date && !Number.isNaN(date.getTime()) ? date.toLocaleDateString(localeOf(hass)) : "";
    };
    const due = dayText(facts.earnings_date);
    const dueEnd = dayText(facts.earnings_date_end);
    add(
      str.fEarnings,
      due && dueEnd ? `${due} – ${dueEnd}` : due,
      facts.earnings_estimate === true ? str.estimated : "",
      str.hEarnings
    );
    // The price alerts: their limits, marked while the price is beyond one.
    const now = item.price;
    const under = isNumber(now) && isNumber(item.alertBelow) && now <= item.alertBelow;
    const over = isNumber(now) && isNumber(item.alertAbove) && now >= item.alertAbove;
    // No alert yet: one line with an empty symbol, for whoever may set one.
    of("alert_none");
    if (canEdit && !isNumber(item.alertBelow) && !isNumber(item.alertAbove)) {
      add(str.fAlertNone, "–", "", str.hAlertNone, false, "none");
    }
    of("alert_below");
    add(str.fAlertBelow, price(item.alertBelow), "", str.hAlertBelow, under, under ? "on" : "set");
    of("alert_above");
    add(str.fAlertAbove, price(item.alertAbove), "", str.hAlertAbove, over, over ? "on" : "set");
    return orderOf(config && config.fact_order, FACT_NAMES).flatMap((name) => found[name] || []);
  }

  // From this width of the page on the details stand in two columns - the
  // stylesheet's container query says the same.
  const DETAIL_WIDE = 560;

  // About how tall the Details format is, in pixels, with what it is set to
  // show: side by side in a wide card, one under the other in a narrow one.
  function detailHeight(config, wide) {
    const on = (key) => config[key] !== false;
    const chart = Number(config.chart_height) > 0 ? Number(config.chart_height) : DEFAULTS.chart_height;
    const head = 100;
    const figures = on("show_detail_facts") ? 30 * FACT_NAMES.filter((name) => on(`show_fact_${name}`)).length : 0;
    const drawing = on("show_detail_chart")
      ? 36 + chart + 26 + (on("show_detail_volume") ? 48 : 0) + (on("show_detail_sma") || on("show_detail_sma50") || on("show_detail_ema") ? 24 : 0) + (on("show_detail_rsi") ? 52 : 0)
      : 0;
    const position = on("show_detail_position") ? 76 : 0;
    // The news: a heading and about two lines per headline.
    const headlines = on("show_detail_news")
      ? 40 + 56 * Math.max(1, Math.min(20, Math.round(Number(config.detail_news_count)) || 5))
      : 0;
    const around = 84;
    return around + headlines + (wide ? Math.max(head + figures, drawing + position) : head + drawing + position + figures);
  }

  // How many decimals a chart's own figures are written with: what its
  // scale's step needs, and never fewer than a price of that size has.
  function scaleDigits(scale) {
    const step = Math.abs(scale.ticks.length > 1 ? scale.ticks[0] - scale.ticks[1] : 1);
    if (step >= 1 && Number.isInteger(Math.round(step * 1e6) / 1e6)) return 0;
    if (step >= 0.01) return 2;
    return 4;
  }

  // ------------------------------------------------------------------ card
  //
  // Neither class has a constructor or a field of its own: a card holds all
  // its state from setConfig on. That is what lets a newer version of this
  // file take the registered classes over - see the end of the file.
  class MarketTickerUltraCard extends HTMLElement {
    setConfig(config) {
      this._config = defaultConfig(config);
      this._tkBuilt = null;
      this._popBuilt = null;
      // The instrument and the period the Details format opens on are
      // settings; where the reader goes from there is the reader's. So each
      // is put back only when its setting changes - which is also what lets
      // the editor's preview follow the field.
      if (this._pageFrom !== this._config.detail_instrument) {
        this._pageFrom = this._config.detail_instrument;
        this._pageId = null;
      }
      if (this._rangeFrom !== this._config.default_range) {
        this._rangeFrom = this._config.default_range;
        if (!this._detail) {
          this._popRange = rangeOf(this._config.default_range);
          this._popStyle = null;
        }
      }
      this._restartAuto();
      this._render();
    }

    set hass(hass) {
      // Here as well as in connectedCallback: a card that a newer version of
      // this file took over was connected under the older one, and would not
      // hear of what the newer one fetches.
      if (this.isConnected) LISTENERS.add(this);
      const first = !this._hass;
      this._hass = hass;
      watchInstruments(hass);
      // Home Assistant hands over a new object on every change of any
      // entity. Only the instruments' own sensors, the language and the
      // formats are worth a redraw.
      const stamp = this._stamp(hass);
      if (first || stamp !== this._seen) {
        this._seen = stamp;
        this._render();
      }
    }

    _stamp(hass) {
      const parts = [hass.language, JSON.stringify(hass.locale || {}), INSTRUMENTS.version, this._isAdmin(hass)];
      for (const instrument of INSTRUMENTS.list || []) {
        const state = hass.states ? hass.states[instrument.entity_id] : null;
        parts.push(state ? `${state.state}|${state.last_updated || ""}` : "-");
      }
      return parts.join("~");
    }

    // The shared tables changed: the instruments, a chart, a logo that did
    // not load.
    _dataChanged() {
      if (this._hass) this._seen = this._stamp(this._hass);
      this._render();
    }

    // In units of about 50 pixels, for a masonry view to share its columns
    // out by. The Details format is as tall as what it is set to show.
    getCardSize() {
      const config = this._config || {};
      if (config.layout === "allocation") return 4;
      if (config.layout === "alerts") return 3;
      if (config.layout !== "detail") return config.layout === "carousel" ? 3 : 1;
      // Two columns side by side where the card is wide enough for them,
      // which makes it much less tall; a card not yet on the page is taken
      // to be a narrow one, as a masonry column is.
      const wide = !!this._root && this._root.clientWidth >= DETAIL_WIDE + 32;
      return Math.ceil(detailHeight(config, wide) / 50);
    }

    // What sizes the card can be given in a sections view. Answering at all
    // is what tells the layout editor that the card can be resized. The
    // Details format takes the full width and its own height to begin with,
    // and scrolls inside a cell that is made shorter.
    getGridOptions() {
      if (this._config && this._config.layout === "detail") {
        return { columns: 12, rows: "auto", min_columns: 6, min_rows: 3 };
      }
      return { columns: 12, rows: "auto", min_columns: 3, min_rows: 1 };
    }

    // Who may add and change: Home Assistant lets administrators run a
    // config flow and nobody else - the flow API refuses everyone else - so
    // the "+" and the pencil are theirs alone.
    _isAdmin(hass) {
      return !!(hass && hass.user && hass.user.is_admin);
    }

    static getConfigElement() {
      return document.createElement(EDITOR_TAG);
    }

    // Deliberately bare: defaultConfig fills the rest in on load.
    static getStubConfig() {
      return {};
    }

    connectedCallback() {
      LISTENERS.add(this);
      if (this._hass) watchInstruments(this._hass);
      this._restartAuto();
      this._render();
    }

    disconnectedCallback() {
      LISTENERS.delete(this);
      if (this._tkTimer) clearInterval(this._tkTimer);
      this._tkTimer = null;
      this._tkStopGlide();
      this._tkStopScroll();
      // A card taken off the page takes its pop-up with it.
      if (this._tkDialog && this._tkDialog.open) this._tkDialog.close();
      this._detail = null;
      this._popBuilt = null;
      // And its flow dialog - but not at once: a masonry view that lays
      // itself out again takes its cards out and puts them straight back.
      queueMicrotask(() => {
        if (!this.isConnected) this._closeFlowDialog();
      });
    }

    // ------------------------------------------------------------ the list
    _tkItems() {
      const config = this._config;
      const picked = pickInstruments(instrumentsOf(config), config.instruments);
      return sortItems(
        picked.map((instrument) => quoteOf(this._hass, instrument)),
        config.sort,
        localeOf(this._hass)
      );
    }

    // --------------------------------------------------------- allocation
    // What is held of the card's instruments, each as its share of their
    // sum: a ring, the sum in its middle, and the list beside it. The values
    // are in the currency positions are added up in, at the reference rate
    // the integration gives for each instrument; one without a rate is left
    // out and said so, rather than counted at a made-up rate.
    _allocHtml(items, str) {
      const hass = this._hass;
      const hide = this._config.hide_amounts === true;
      const base = INSTRUMENTS.base;
      const parts = [];
      const left = [];
      for (const item of items) {
        const figures = positionFigures(item);
        if (!figures || !isNumber(figures.value) || !(figures.value > 0)) continue;
        const rate = item.currency === base ? 1 : item.baseRate;
        if (!isNumber(rate)) {
          left.push(item.name);
          continue;
        }
        parts.push({
          item,
          value: figures.value * rate,
          gain: isNumber(figures.gain) ? figures.gain * rate : null,
          gainPct: isNumber(figures.gainPct) ? figures.gainPct : null,
        });
      }
      if (!parts.length) return `<div class="tk-msg">${escapeHtml(str.allocEmpty)}</div>`;
      parts.sort((a, b) => b.value - a.value);
      const total = parts.reduce((sum, part) => sum + part.value, 0);
      // Each position in its instrument's own colour - or, without one, in
      // the next of the card's that is easily told from those in use; with
      // none such left, in the next there is.
      const taken = parts.map((part) => rgbOf(part.item.colorKey)).filter(Boolean);
      const free = ALLOC_COLORS.slice();
      parts.forEach((part, index) => {
        if (part.item.color) {
          part.color = part.item.color;
          return;
        }
        if (!free.length) {
          part.color = ALLOC_COLORS[index % ALLOC_COLORS.length];
          return;
        }
        const clear = free.findIndex((colour) => taken.every((other) => coloursApart(rgbOf(colour), other)));
        part.color = free.splice(Math.max(0, clear), 1)[0];
        taken.push(rgbOf(part.color));
      });
      // The ring: one arc per position, from the top, clockwise.
      const round = 2 * Math.PI * 40;
      let from = 0;
      const arcs = parts
        .map((part, index) => {
          const share = part.value / total;
          const arc =
            `<circle class="al-arc" data-action="tk-open" data-id="${escapeHtml(part.item.id)}"` +
            ` cx="50" cy="50" r="40" fill="none" stroke="${part.color}" stroke-width="14"` +
            ` stroke-dasharray="${(share * round).toFixed(3)} ${round.toFixed(3)}" stroke-dashoffset="${(-from * round).toFixed(3)}">` +
            `<title>${escapeHtml(part.item.name)}</title></circle>`;
          from += share;
          return arc;
        })
        .join("");
      const config = this._config;
      const on = (key) => config[key] !== false;
      const view = allocView(config);
      // With nothing drawn the list can say what each position gained.
      // Which of the two: what the viewer chose with the card's button,
      // until the card is set to start with the other.
      const firstList = config.alloc_list === "gain" ? "gain" : "shares";
      if (this._allocFirst !== firstList) {
        this._allocFirst = firstList;
        this._allocList = null;
      }
      const switchable = view === "none" && on("show_alloc_switch");
      const gains = view === "none" && (switchable && this._allocList ? this._allocList : firstList) === "gain";
      const otherList = gains ? "shares" : "gain";
      const switchLabel = gains ? str.toAllocShares : str.toAllocGain;
      // The button as it stands now, with the symbol, the colour and the
      // size Layout gives it.
      const switchSet = (what) => config[`alloc_to_${otherList}_${what}`];
      const switchIcon =
        typeof switchSet("icon") === "string" && switchSet("icon") ? switchSet("icon") : DEFAULTS[`alloc_to_${otherList}_icon`];
      const switchLook = escapeHtml(
        [
          switchSet("color") ? `color: ${switchSet("color")}` : "",
          CSS.supports("width", switchSet("size")) ? `--mdc-icon-size: ${switchSet("size")}` : "",
        ]
          .filter(Boolean)
          .join("; ")
      );
      const listSwitch = switchable
        ? `<button type="button" class="style-btn al-switch" data-action="alloc-list" data-key="${otherList}" style="${switchLook}"` +
          ` title="${escapeHtml(switchLabel)}" aria-label="${escapeHtml(switchLabel)}">` +
          `<ha-icon icon="${escapeHtml(switchIcon)}"></ha-icon></button>`
        : "";
      const most = Math.max(0, ...parts.map((part) => (isNumber(part.gainPct) ? Math.abs(part.gainPct) : 0))) || 1;
      const gainHtml = (part) => {
        const side = gainClass(part.gainPct !== null ? part.gainPct : part.gain);
        const width = isNumber(part.gainPct) ? Math.max(2, (Math.abs(part.gainPct) / most) * 50) : 0;
        return (
          `<span class="al-gbar">${side ? `<i class="${side}" style="width: ${width.toFixed(1)}%"></i>` : ""}</span>` +
          `<span class="al-gpct ${side}" style="${elementStyle(config, "alloc_gain_pct")}">${isNumber(part.gainPct) ? escapeHtml(percent(hass, part.gainPct)) : ""}</span>` +
          (hide
            ? ""
            : `<span class="al-gain ${side}" style="${elementStyle(config, "alloc_gain_amount")}">${isNumber(part.gain) ? escapeHtml(money(hass, part.gain, base, true)) : ""}</span>`)
        );
      };
      // A price alert on a position: a bell before its name, which opens
      // the alerts.
      const bellOf = (item) => {
        const alarm = alertState(item);
        if (!alarm) return "";
        const label = alarm === "on" ? str.alertOn : str.alertSet;
        return (
          `<span class="tk-alert ${alarm}" data-action="alerts" data-id="${escapeHtml(item.id)}" title="${escapeHtml(label)}"` +
          ` aria-label="${escapeHtml(label)}"><ha-icon icon="${escapeHtml(alertIcon(config, alarm))}"></ha-icon></span>`
        );
      };
      const rows = view === "tiles" ? "" : parts
        .map((part, index) => {
          const share = (part.value / total) * 100;
          return (
            `<div class="al-row" data-action="tk-open" data-id="${escapeHtml(part.item.id)}" tabindex="0" role="button"` +
            ` aria-label="${escapeHtml(part.item.name)}">` +
            // The colour mark belongs to the ring and the bar: with
            // neither the logo stands there, or nothing.
            (view !== "none" ? `<i style="background: ${part.color}"></i>` : on("show_alloc_logo") ? logoHtml(part.item) : "") +
            // The name says what the mark's colour stands for, so it is
            // always there with the ring and the bar. Without the name its
            // room stays: the figures keep to the right.
            (view !== "none" || on("show_alloc_name")
              ? `<span class="al-name" style="${elementStyle(config, "alloc_name")}">${bellOf(part.item)}${escapeHtml(part.item.name)}</span>`
              : `<span class="al-name">${bellOf(part.item)}</span>`) +
            (gains
              ? gainHtml(part)
              : (on("show_alloc_share")
                  ? `<span class="al-share" style="${elementStyle(config, "alloc_share")}">${escapeHtml(percent(hass, share, false))}</span>`
                  : "") +
                (hide || !on("show_alloc_value")
                  ? ""
                  : `<span class="al-value" style="${elementStyle(config, "alloc_value")}">${escapeHtml(money(hass, part.value, base))}</span>`)) +
            `</div>`
          );
        })
        .join("");
      // The sum: in the ring - or, without the ring, on a line of its own
      // above the list.
      const sum = on("show_alloc_total")
        ? `<small>${escapeHtml(str.allocTotal)}</small>` +
          `<b style="${elementStyle(config, "alloc_total")}">${escapeHtml(hide ? str.amountHidden : compact(hass, total, base))}</b>`
        : "";
      // The list's columns: the mark or the logo, the name with what room
      // is left, and the figures - each as wide as its widest entry.
      const columns = [
        view !== "none" || on("show_alloc_logo") ? "auto" : "",
        "minmax(0, 1fr)",
        ...(gains
          ? ["minmax(32px, min(22%, 90px))", "auto", hide ? "" : "auto"]
          : [on("show_alloc_share") ? "auto" : "", hide || !on("show_alloc_value") ? "" : "auto"]),
      ]
        .filter(Boolean)
        .join(" ");
      // The bar: one stretch per position, as long as its share.
      const bar =
        view === "bar"
          ? `<div class="al-bar">` +
            parts
              .map(
                (part) =>
                  `<i data-action="tk-open" data-id="${escapeHtml(part.item.id)}" title="${escapeHtml(part.item.name)}"` +
                  ` style="flex: ${(part.value / total).toFixed(4)} 1 0; background: ${part.color}"></i>`
              )
              .join("") +
            `</div>`
          : "";
      // The tiles: one per position, as large as its share and in its
      // instrument's colour.
      let tiles = "";
      if (view === "tiles") {
        const rects = tileRects(parts.map((part) => part.value), 0, 0, 300, 100);
        tiles =
          `<div class="al-tiles">` +
          parts
            .map((part, index) => {
              const rect = rects[index];
              // The text on its colour: dark on a light one, light on a
              // dark one - unless Layout gives it a colour.
              const rgb = rgbOf(part.item.colorKey || part.color);
              const ink = rgb && rgb[0] * 0.299 + rgb[1] * 0.587 + rgb[2] * 0.114 > 150 ? "#111" : "#fff";
              const width = rect.w / 3;
              // A low tile has its name and its value on one line, a tiny
              // one neither.
              const size = width < 12 || rect.h < 18 ? " xs" : rect.h < 34 ? " s" : "";
              const worth = hide || !on("show_alloc_value") ? "" : money(hass, part.value, base);
              const head =
                (config.show_alloc_tile_logo === true ? logoHtml(part.item) : "") +
                bellOf(part.item) +
                (on("show_alloc_name") ? `<b style="${elementStyle(config, "alloc_tile_name")}">${escapeHtml(part.item.name)}</b>` : "");
              return (
                `<div class="al-tile${size}" data-action="tk-open" data-id="${escapeHtml(part.item.id)}" tabindex="0" role="button"` +
                ` aria-label="${escapeHtml(part.item.name)}" title="${escapeHtml([part.item.name, worth].filter(Boolean).join(" · "))}"` +
                ` style="left: ${(rect.x / 3).toFixed(2)}%; top: ${rect.y.toFixed(2)}%; width: ${width.toFixed(2)}%; height: ${rect.h.toFixed(2)}%">` +
                `<div style="background: ${part.color}; color: ${ink}">` +
                (head ? `<div class="al-th">${head}</div>` : "") +
                (worth ? `<span style="${elementStyle(config, "alloc_tile_facts")}">${escapeHtml(worth)}</span>` : "") +
                `</div></div>`
              );
            })
            .join("") +
          `</div>`;
      }
      const ring = view === "ring"
        ? `<div class="al-ring"><svg viewBox="0 0 100 100" aria-hidden="true"><g transform="rotate(-90 50 50)">${arcs}</g></svg>` +
          `<div class="al-total">${sum}</div></div>`
        : "";
      return (
        `<div class="al-box">${ring}` +
        `<div class="al-list" style="grid-template-columns: ${columns}">${!ring && (sum || listSwitch) ? `<div class="al-sum">${sum}${listSwitch}</div>` : ""}${bar}${tiles}${rows}</div></div>` +
        (left.length ? `<div class="al-note">${escapeHtml(str.allocLeft(left.join(", ")))}</div>` : "") +
        (this._config.show_performance !== false ? this._perfHtml(str) : "") +
        (this._config.show_alloc_news !== false ? this._allocNewsHtml(str, parts) : "")
      );
    }

    // The news about what the portfolio holds - of the positions the card
    // shows -, each naming its instrument.
    _allocNewsHtml(str, parts) {
      const group = this._perfGroup();
      if (!group) return "";
      const config = this._config;
      const entry = groupNewsOf(group.id, this._hass.language);
      const held = new Set(parts.map((part) => part.item.id));
      const items = Array.isArray(entry.data) ? entry.data.filter((item) => held.has(item.instrument)) : [];
      const html = this._newsHtml(str, items, {
        count: config.alloc_news_count,
        days: config.alloc_news_days,
        compact: config.alloc_news_compact !== false,
        open: !!this._allocNewsOpen,
        action: "alloc-news",
        looks: ["alloc_news_heading", "alloc_news_title", "alloc_news_meta"],
        named: true,
        idOf: (item) => item.instrument,
        keep: (ids) => (this._allocNewsIds = ids),
      });
      return html ? `<div class="pf-box nw-box">${html}</div>` : "";
    }

    // The price alerts of the card's instruments, one line each: its lower
    // limit, a track with the price as a mark between the two, its upper
    // limit. With one limit only the track is the fifth of that limit next
    // to it; with none it is empty. The symbol at the line's head opens the
    // alerts, the line itself the details.
    _alertsHtml(items, str) {
      const hass = this._hass;
      const config = this._config;
      // A limit that is reached keeps the alert's colour, whatever colour
      // the limits are given.
      const limitLook = elementStyle(config, "alerts_limit");
      const fontOnly = elementStyle({ ...config, alerts_limit_color: "" }, "alerts_limit");
      const rows = items
        .map((item) => {
          const state = alertState(item);
          const low = isNumber(item.alertBelow) ? item.alertBelow : null;
          const high = isNumber(item.alertAbove) ? item.alertAbove : null;
          const now = item.price;
          const from = low !== null ? low : high !== null ? high * 0.8 : null;
          const to = high !== null ? high : low !== null ? low * 1.2 : null;
          const at =
            isNumber(now) && from !== null && to !== null && to > from
              ? Math.max(0, Math.min(100, ((now - from) / (to - from)) * 100))
              : null;
          const under = low !== null && isNumber(now) && now <= low;
          const over = high !== null && isNumber(now) && now >= high;
          const limit = (value) => (value === null ? "–" : escapeHtml(money(hass, value, item.currency, false, item.digits)));
          const label = state === "on" ? str.alertOn : state === "set" ? str.alertSet : str.editAlerts;
          return (
            `<div class="aa-row" data-action="tk-open" data-id="${escapeHtml(item.id)}" tabindex="0" role="button"` +
            ` aria-label="${escapeHtml(item.name)}">` +
            `<span class="tk-alert ${state || "none"}" data-action="alerts" data-id="${escapeHtml(item.id)}" title="${escapeHtml(label)}"` +
            ` aria-label="${escapeHtml(label)}"><ha-icon icon="${escapeHtml(alertIcon(config, state))}"></ha-icon></span>` +
            (config.show_row_logo !== false ? logoHtml(item) : "") +
            `<span class="aa-name" style="${elementStyle(config, "alerts_name")}">${escapeHtml(item.name)}</span>` +
            `<span class="aa-limit${under ? " on" : ""}" style="${under ? fontOnly : limitLook}">${limit(low)}</span>` +
            `<span class="aa-track" title="${escapeHtml(isNumber(now) ? money(hass, now, item.currency, false, item.digits) : "")}">` +
            (at === null ? "" : `<i class="${state === "on" ? "on" : ""}" style="left: ${at.toFixed(1)}%"></i>`) +
            `</span>` +
            `<span class="aa-limit${over ? " on" : ""}" style="${over ? fontOnly : limitLook}">${limit(high)}</span>` +
            `</div>`
          );
        })
        .join("");
      return `<div class="aa-list${config.show_row_logo !== false ? " logos" : ""}">${rows}</div>`;
    }

    // The portfolio the performance is of: the card's group where it is a
    // portfolio, or the only portfolio there is.
    _perfGroup() {
      const id = groupOf(this._config);
      return INSTRUMENTS.groups.find((group) => group.id === id && group.kind === "portfolio") || null;
    }

    // How the portfolio has done over the period chosen: its time-weighted
    // return as a line from nought, the index of its group as a second one,
    // and both figures by name above them.
    _perfHtml(str) {
      const hass = this._hass;
      const group = this._perfGroup();
      // The period: the one the viewer chose, until the card is set to
      // start with another; else the one it is set to start with.
      const first = PERF_RANGES.includes(this._config.perf_default_range) ? this._config.perf_default_range : "1y";
      if (this._perfFirst !== first) {
        this._perfFirst = first;
        this._perfRange = null;
      }
      const range = PERF_RANGES.includes(this._perfRange) ? this._perfRange : first;
      const offered = perfRanges(this._config);
      const tabs = offered.length
        ? `<div class="range-tabs" role="group">` +
          offered
            .map(
              (key) =>
                `<button type="button" class="${key === range ? "active" : ""}" aria-pressed="${key === range}"` +
                ` data-action="perf-range" data-key="${key}"` +
                ` style="${elementStyle(this._config, key === range ? "perf_range_on" : "perf_range_off")}">` +
                `${escapeHtml(str[`r${key}`])}</button>`
            )
            .join("") +
          `</div>`
        : "";
      const config = this._config;
      const head =
        `<div class="pf-head"><span class="pf-title" style="${elementStyle(config, "perf_title")}">` +
        `${escapeHtml(config.perf_heading || str.perfTitle)}</span>${tabs}</div>`;
      const say = (text) => `<div class="pf-box">${head}<div class="pf-msg">${escapeHtml(text)}</div></div>`;
      if (!group) return say(str.perfChoose);
      const entry = performanceOf(group.id, range);
      const data = entry.data;
      if (!data) return say(entry.error ? str.noData : str.loading);
      const own = Array.isArray(data.portfolio) ? data.portfolio : [];
      if (own.length < 2) return say(str.perfEmpty);
      const index = config.show_perf_index !== false && Array.isArray(data.benchmark) ? data.benchmark : null;
      const all = own.concat(index ? index.filter(isNumber) : []);
      const low = Math.min(0, ...all);
      const high = Math.max(0, ...all);
      const span = high - low || 1;
      const x = (at) => ((at / (own.length - 1)) * 100).toFixed(2);
      const y = (value) => (3 + ((high - value) / span) * 34).toFixed(2);
      const path = (values) => {
        let d = "";
        let pen = "M";
        values.forEach((value, at) => {
          if (!isNumber(value)) {
            pen = "M";
            return;
          }
          d += `${pen}${x(at)},${y(value)}`;
          pen = "L";
        });
        return d;
      };
      const still = ` vector-effect="non-scaling-stroke" fill="none" stroke-linejoin="round"`;
      const figure = (value) =>
        isNumber(value) ? `<b class="${gainClass(value)}">${escapeHtml(percent(hass, value))}</b>` : "";
      // A day - or, within a day, a minute, which the integration names in
      // universal time.
      const day = (text) => {
        const timed = text.includes("T");
        const date = new Date(timed ? `${text}:00Z` : `${text}T00:00:00`);
        if (Number.isNaN(date.getTime())) return "";
        const locale = localeOf(hass);
        return escapeHtml(
          timed
            ? date.toLocaleString(locale, { day: "numeric", month: "numeric", hour: "2-digit", minute: "2-digit" })
            : date.toLocaleDateString(locale)
        );
      };
      // The scale at the right: round steps in percent, four or five of
      // them, each with its line across the chart.
      const step = [0.1, 0.2, 0.5, 1, 2, 5, 10, 20, 50, 100, 200, 500, 1000, 2000, 5000].find((size) => span / size <= 5) || 10000;
      const ticks = [];
      for (let tick = Math.ceil(low / step) * step; tick <= high + 1e-9; tick += step) ticks.push(Math.round(tick * 10) / 10);
      const digits = step < 1 ? 1 : 0;
      const tickText = (value) =>
        numberFormat(hass, { minimumFractionDigits: digits, maximumFractionDigits: digits, signDisplay: "exceptZero" }).format(value) + "%";
      const days = Array.isArray(data.days) ? data.days : [];
      const left = Array.isArray(data.left_out) ? data.left_out : [];
      // The portfolio's line drawn twice, each drawing cut to its side of
      // the starting value: above it in the gain colour, below it in the
      // loss colour - as the price's line is.
      const edge = Math.max(0, Math.min(40, Number(y(0))));
      const clip = `mt-perf-${++CLIP_SEQ}`;
      const ownPath = path(own);
      const drawn = (side) =>
        `<path class="pf-line own ${side}" clip-path="url(#${clip}-${side})" d="${ownPath}" stroke-linecap="round"${still}/>`;
      // What the pointer reads off the chart (see _perfOver).
      this._perfSeries = {
        days,
        own,
        index,
        tops: own.map((value) => (isNumber(value) ? (Number(y(value)) / 40) * 100 : null)),
        name: group.name,
        indexName: data.benchmark_name || "",
        when: day,
      };
      return (
        `<div class="pf-box">${head}` +
        `<div class="pf-legend" style="${elementStyle(config, "perf_legend")}"><span class="pf-own ${isNumber(data.return) && data.return < 0 ? "loss" : "gain"}"><i></i>${escapeHtml(group.name)} ${figure(data.return)}</span>` +
        (index
          ? `<span class="pf-index"><i></i>${escapeHtml(data.benchmark_name || "")} ${figure(data.benchmark_return)}</span>`
          : "") +
        `</div>` +
        `<div class="pf-chart"><div class="pf-plot"><svg viewBox="0 0 100 40" preserveAspectRatio="none" aria-hidden="true">` +
        ticks
          .map((tick) => `<line class="pf-grid" x1="0" x2="100" y1="${y(tick)}" y2="${y(tick)}" vector-effect="non-scaling-stroke"/>`)
          .join("") +
        (index ? `<path class="pf-line index" d="${path(index)}"${still}/>` : "") +
        `<defs><clipPath id="${clip}-up"><rect x="-10" y="-10" width="120" height="${(edge + 10).toFixed(2)}"/></clipPath>` +
        `<clipPath id="${clip}-down"><rect x="-10" y="${edge.toFixed(2)}" width="120" height="${(50 - edge).toFixed(2)}"/></clipPath></defs>` +
        drawn("up") +
        drawn("down") +
        `</svg><div class="cursor" hidden><div class="dot"></div></div><div class="tip" hidden></div></div>` +
        `<div class="pf-axis" style="${elementStyle(config, "perf_axis")}">` +
        `<i>${escapeHtml(ticks.map(tickText).reduce((a, b) => (b.length > a.length ? b : a), ""))}</i>` +
        ticks.map((tick) => `<span style="top: ${((Number(y(tick)) / 40) * 100).toFixed(2)}%">${escapeHtml(tickText(tick))}</span>`).join("") +
        `</div></div>` +
        `<div class="pf-days"><span>${day(days[0] || "")}</span><span>${day(days[days.length - 1] || "")}</span></div>` +
        (left.length ? `<div class="pf-note">${escapeHtml(str.perfLeft(left.join(", ")))}</div>` : "") +
        `</div>`
      );
    }

    // What the pointer - or a finger - reads off the performance: a line
    // through the nearest moment, a dot on the portfolio's return, and the
    // moment with both returns in a box. The chart is drawn anew with every
    // change, so the strip listens for it.
    _perfOver(ev) {
      const plot = ev.target && ev.target.closest ? ev.target.closest(".pf-plot") : null;
      const series = this._perfSeries;
      if (!plot || !series || series.own.length < 2) return;
      const rect = plot.getBoundingClientRect();
      if (!rect.width) return;
      const last = series.own.length - 1;
      const at = Math.max(0, Math.min(last, Math.round(((ev.clientX - rect.left) / rect.width) * last)));
      const value = series.own[at];
      if (!isNumber(value)) return;
      const left = (at / last) * 100;
      const cursor = plot.querySelector(".cursor");
      const tip = plot.querySelector(".tip");
      cursor.hidden = false;
      cursor.style.left = `${left}%`;
      cursor.querySelector(".dot").style.top = `${series.tops[at]}%`;
      const row = (kind, name, figure) =>
        `<span class="avg ${kind} ${gainClass(figure)}"><i></i>${escapeHtml(name)} ` +
        `<b>${escapeHtml(percent(this._hass, figure))}</b></span>`;
      const beside = series.index ? series.index[at] : null;
      tip.hidden = false;
      // The moment is escaped where it is put into words.
      tip.innerHTML =
        `<span class="when">${series.when(series.days[at] || "")}</span>` +
        row("pf-own", series.name, value) +
        (isNumber(beside) ? row("pf-index", series.indexName, beside) : "");
      // Beside the line, on whichever side has the room.
      tip.style.left = left > 50 ? "auto" : `calc(${left}% + 8px)`;
      tip.style.right = left > 50 ? `calc(${100 - left}% + 8px)` : "auto";
    }

    _perfOut(ev) {
      const plot = ev.target;
      if (!plot || !plot.classList || !plot.classList.contains("pf-plot")) return;
      plot.querySelector(".cursor").hidden = true;
      plot.querySelector(".tip").hidden = true;
    }

    // ------------------------------------------------------- moving on alone
    // The ticker runs on CSS; the row and the carousel on this timer.
    _restartAuto() {
      if (this._tkTimer) clearInterval(this._tkTimer);
      this._tkTimer = null;
      this._tkStopGlide();
      if (!this._config || !this.isConnected) return;
      if (this._config.auto_advance === false || ["ticker", "detail", "allocation", "alerts"].includes(this._config.layout)) return;
      if (this._tkEffect() === "glide") {
        this._tkStartGlide();
        return;
      }
      this._tkTimer = setInterval(() => {
        if (this._detail || this._tkHover || this._tkDragging || document.hidden) return;
        this._tkStep(1);
      }, tickerSeconds(this._config) * 1000);
    }

    // With a loop the strip goes on past its end onto a copy of the
    // beginning, and is put back on the original where nobody can see it.
    _tkLoops(items) {
      const layout = this._config.layout;
      if (layout === "ticker" || items.length < 2) return false;
      const effect = this._tkEffect();
      // Entries stacked on one another have no end to run back from, and a
      // glide without one would have to stop.
      if (layout === "line" && effect !== "slide") return false;
      if (effect === "glide") return true;
      return this._config.endless_loop === true;
    }

    // The chosen effect, or the plain strip where it is not known or the
    // device asks for less motion.
    _tkEffect() {
      const config = this._config;
      const line = config.layout === "line";
      if (!line && config.layout !== "carousel") return "slide";
      const chosen = line ? config.line_effect : config.carousel_effect;
      if (!(line ? TK_LINE_EFFECTS : TK_CAROUSEL_EFFECTS).includes(chosen)) return "slide";
      if (lessMotion()) return "slide";
      return chosen;
    }

    // Milliseconds. An automatic change gets time to stand still in between.
    _tkFxMs() {
      const config = this._config;
      const value = Number(config.effect_duration);
      const ms = Number.isFinite(value) && value > 0 ? Math.max(100, Math.min(3000, value)) : DEFAULTS.effect_duration;
      return config.auto_advance === false ? ms : Math.min(ms, tickerSeconds(config) * 800);
    }

    // The browser's smooth scrolling has a speed of its own, so the carousel
    // moves here. Snapping stays off until it has arrived.
    _tkScrollTo(box, left) {
      this._tkStopScroll();
      const from = box.scrollLeft;
      const ms = this._tkFxMs();
      const start = performance.now();
      box.classList.add("moving");
      const frame = (now) => {
        const part = Math.min(1, Math.max(0, (now - start) / ms));
        const eased = part < 0.5 ? 2 * part * part : 1 - (-2 * part + 2) ** 2 / 2;
        box.scrollTo({ left: from + (left - from) * eased, behavior: "instant" });
        if (part < 1) {
          this._tkMoving.frame = requestAnimationFrame(frame);
        } else {
          this._tkStopScroll();
          this._tkWrapScroll(box);
        }
      };
      this._tkMoving = { box, frame: requestAnimationFrame(frame) };
    }

    _tkStopScroll() {
      if (!this._tkMoving) return;
      cancelAnimationFrame(this._tkMoving.frame);
      this._tkMoving.box.classList.remove("moving");
      this._tkMoving = null;
    }

    // Compact row, every effect but the strip: the entries lie on one another.
    _tkSwap(direction, total, effect) {
      const line = this._root.querySelector(".tk-line");
      const track = line && line.querySelector(".tk-track");
      if (!track || total < 2) return;
      if (this._tkFxEnd) this._tkFxEnd();
      const from = this._tkIndex || 0;
      const to = (from + direction + total) % total;
      this._tkIndex = to;
      const leaving = track.children[from];
      const coming = track.children[to];
      leaving.classList.remove("on");
      leaving.classList.add("off");
      coming.classList.add("on");
      let runs = [];
      let flap = null;
      const finish = () => {
        if (this._tkFxEnd !== finish) return;
        this._tkFxEnd = null;
        runs.forEach((run) => run.cancel());
        leaving.classList.remove("off");
        track.classList.remove("flapping");
        if (flap) flap.remove();
      };
      this._tkFxEnd = finish;
      if (effect === "flap") {
        flap = document.createElement("div");
        flap.className = "tk-flap";
        const half = (slide, part) => {
          const el = document.createElement("div");
          el.className = `tk-half ${part}`;
          el.appendChild(slide.cloneNode(true));
          el.querySelectorAll("[tabindex]").forEach((node) => (node.tabIndex = -1));
          flap.appendChild(el);
          return el;
        };
        half(coming, "top");
        half(leaving, "bottom");
        const falling = half(leaving, "top");
        const landing = half(coming, "bottom");
        line.appendChild(flap);
        track.classList.add("flapping");
        const half2 = this._tkFxMs() / 2;
        runs = [
          falling.animate([{ transform: "rotateX(0deg)" }, { transform: "rotateX(-90deg)" }], { duration: half2, easing: "ease-in", fill: "forwards" }),
          landing.animate([{ transform: "rotateX(90deg)" }, { transform: "rotateX(0deg)" }], { duration: half2, delay: half2, easing: "ease-out", fill: "both" }),
        ];
      } else {
        const [out, into] = TK_SWAPS[effect](direction);
        const time = { duration: this._tkFxMs(), easing: "ease" };
        runs = [leaving.animate(out, time), coming.animate(into, time)];
      }
      runs[runs.length - 1].finished.then(finish, () => {});
    }

    // Carousel, staggered: a whole page at once, its tiles appearing in turn.
    _tkStaggerStep(box, tile, direction, loops) {
      const step = tile.getBoundingClientRect().width + 10;
      const page = Math.max(1, Math.floor((box.clientWidth - 14) / step));
      if (loops) this._tkWrapScroll(box);
      const end = box.scrollWidth - box.clientWidth;
      let left = box.scrollLeft + direction * page * step;
      if (!loops && direction > 0 && box.scrollLeft >= end - 2) left = 0;
      else if (!loops && direction < 0 && box.scrollLeft <= 2) left = end;
      box.scrollTo({ left: Math.max(0, Math.min(end, left)), behavior: "instant" });
      if (loops) this._tkWrapScroll(box);
      const view = box.getBoundingClientRect();
      [...box.querySelectorAll(".tk-mini")]
        .filter((el) => {
          const rect = el.getBoundingClientRect();
          return rect.right > view.left && rect.left < view.right;
        })
        .forEach((el, index) =>
          el.animate(
            [{ opacity: 0, transform: "translateY(10px)" }, { opacity: 1, transform: "translateY(0)" }],
            { duration: this._tkFxMs() * 0.9, delay: index * this._tkFxMs() * 0.22, easing: "ease-out", fill: "backwards" }
          )
        );
    }

    // Carousel, glide: one tile per interval, without a stop. The position is
    // kept here because scrollLeft rounds away a slow movement. A hand on the
    // strip wins: when it moved the strip, the glide picks up from there.
    _tkStartGlide() {
      let last = null;
      let at = null;
      let hold = 0;
      const frame = (now) => {
        this._tkGlide = requestAnimationFrame(frame);
        const box = this._root && this._root.querySelector('.tk-scroll[data-fx="glide"]');
        const period = this._tkPeriodPx;
        const since = last === null ? 0 : Math.min(now - last, 100);
        last = now;
        if (!box || !(period > 0)) return;
        if (at === null || Math.abs(box.scrollLeft - at) > 2) {
          if (at !== null) hold = now + 800;
          at = box.scrollLeft;
        }
        if (now < hold || this._detail || this._tkHover || box.classList.contains("drag")) return;
        const perTile = period / this._tkLoopTotal;
        at += (perTile / tickerSeconds(this._config) / 1000) * since;
        if (at >= 2 * period) at -= period;
        box.scrollTo({ left: at, behavior: "instant" });
      };
      this._tkGlide = requestAnimationFrame(frame);
    }

    _tkStopGlide() {
      if (this._tkGlide) cancelAnimationFrame(this._tkGlide);
      this._tkGlide = null;
    }

    // Focus and coverflow: every tile's look follows its distance from the
    // place at the front, so they change with the scrolling itself.
    _tkPaintTiles(box) {
      const effect = box.dataset.fx;
      if (effect !== "focus" && effect !== "coverflow") return;
      const tiles = box.querySelectorAll(".tk-mini");
      if (tiles.length < 2) return;
      const origin = tiles[0].offsetLeft;
      const step = tiles[1].offsetLeft - origin;
      if (!(step > 0)) return;
      for (const tile of tiles) {
        const distance = (tile.offsetLeft - origin - box.scrollLeft) / step;
        const far = Math.min(Math.abs(distance), 1);
        if (effect === "focus") {
          // Step by step, as far as three tiles from the front.
          const steps = Math.min(Math.abs(distance), 3);
          tile.style.opacity = String(1 - 0.5 * far - 0.15 * Math.max(0, steps - 1));
          tile.style.transform = `scale(${1 - 0.08 * steps})`;
        } else {
          const turn = Math.max(-1, Math.min(1, distance)) * -38;
          tile.style.opacity = String(1 - 0.3 * Math.min(Math.abs(distance), 2) / 2);
          tile.style.transform = `perspective(500px) rotateY(${turn}deg) scale(${1 - 0.14 * far})`;
          tile.style.zIndex = String(10 - Math.min(9, Math.round(Math.abs(distance) * 2)));
        }
      }
    }

    // A coverflow has its front tile in the middle, the first one included.
    _tkFitCarousel() {
      const box = this._root && this._root.querySelector(".tk-scroll");
      if (!box) return;
      if (box.dataset.fx === "coverflow") {
        const tile = box.querySelector(".tk-mini");
        const side = tile ? Math.max(12, (box.clientWidth - tile.getBoundingClientRect().width) / 2) : 12;
        box.style.paddingLeft = `${side}px`;
        box.style.paddingRight = `${side}px`;
      }
      this._tkFitLoop();
      this._tkPaintTiles(box);
    }

    _tkStep(direction) {
      const items = this._tkItems();
      if (!items.length) return;
      const effect = this._tkEffect();
      if (this._config.layout === "line" && effect !== "slide") {
        this._tkSwap(direction, items.length, effect);
        return;
      }
      if (this._config.layout === "line") {
        if (this._tkLoops(items)) {
          this._tkSettleLine();
          this._tkIndex = (this._tkIndex || 0) + direction;
          this._tkPlaceLine();
          clearTimeout(this._tkSettle);
          this._tkSettle = setTimeout(() => this._tkSettleLine(), this._tkFxMs() + 30);
          return;
        }
        this._tkIndex = ((this._tkIndex || 0) + direction + items.length) % items.length;
        this._tkPlaceLine();
      } else if (this._config.layout === "carousel") {
        const box = this._root.querySelector(".tk-scroll");
        const tile = box && box.querySelector(".tk-mini");
        if (!tile) return;
        this._tkStopScroll();
        if (effect === "stagger") {
          this._tkStaggerStep(box, tile, direction, this._tkLoops(items));
          return;
        }
        if (this._tkLoops(items)) {
          this._tkWrapScroll(box);
          this._tkScrollTo(box, box.scrollLeft + direction * (tile.getBoundingClientRect().width + 10));
          return;
        }
        const end = box.scrollWidth - box.clientWidth;
        const left = box.scrollLeft >= end - 2 ? 0 : box.scrollLeft + tile.getBoundingClientRect().width + 10;
        this._tkScrollTo(box, left);
      }
    }

    _tkPlaceLine(offset) {
      const track = this._root.querySelector(".tk-track");
      if (track && track.classList.contains("stack")) {
        [...track.children].forEach((slide, index) => slide.classList.toggle("on", index === (this._tkIndex || 0)));
      } else if (track) {
        const at = (this._tkIndex || 0) + (track.dataset.loop ? 1 : 0);
        track.style.transform = `translateX(calc(-${at * 100}% + ${offset || 0}px))`;
      }
    }

    // A strip that hides what does not fit can still be scrolled - by the
    // browser, to something out of view. It is put back at once.
    _tkNoScroll(el) {
      el.addEventListener("scroll", () => {
        // The ticker that stands still is scrolled by hand.
        if (el.scrollLeft && !el.classList.contains("calm")) el.scrollLeft = 0;
      });
    }

    // The entry at the running ticker's left edge: the one the keyboard opens.
    _tkFront() {
      const box = this._root.querySelector(".tk-marquee");
      if (!box) return null;
      const left = box.getBoundingClientRect().left;
      const front = [...box.querySelectorAll(".tk-item")].find((el) => {
        const rect = el.getBoundingClientRect();
        return rect.left + rect.width / 2 > left;
      });
      return front ? front.dataset.id : null;
    }

    // From the copy back onto the original, without the slide that would show.
    _tkSettleLine() {
      clearTimeout(this._tkSettle);
      const track = this._root.querySelector(".tk-track");
      if (!track || !track.dataset.loop) return;
      const total = Number(track.dataset.loop);
      const at = this._tkIndex || 0;
      if (at >= 0 && at < total) return;
      this._tkIndex = ((at % total) + total) % total;
      track.classList.add("drag");
      this._tkPlaceLine();
      void track.offsetWidth;
      if (!this._tkDragging) track.classList.remove("drag");
    }

    // The carousel holds the set several times and stays in the second copy.
    _tkWrapScroll(box) {
      const period = this._tkPeriodPx;
      if (!(period > 0) || box.classList.contains("drag") || box.classList.contains("moving")) return;
      const left = box.scrollLeft;
      let target = left;
      if (left < period - 1) target = left + period;
      else if (left >= 2 * period - 1) target = left - period;
      if (target !== left) box.scrollTo({ left: target, behavior: "instant" });
    }

    _tkFitLoop() {
      const box = this._root && this._root.querySelector(".tk-scroll.loop");
      if (!box) return;
      const tiles = box.querySelectorAll(".tk-mini");
      const total = this._tkLoopTotal;
      if (tiles.length < total * 2) return;
      const period = tiles[total].offsetLeft - tiles[0].offsetLeft;
      if (!(period > 0)) return;
      this._tkPeriodPx = period;
      const copies = Math.max(3, Math.ceil(box.clientWidth / period) + 2);
      if (copies !== this._tkLoopCopies) {
        this._tkLoopCopies = copies;
        box.innerHTML = this._tkLoopClone + this._tkLoopSet + this._tkLoopClone.repeat(copies - 2);
        this._tkRefresh();
      }
      this._tkWrapScroll(box);
    }

    // ------------------------------------------------------------ drawing
    _render() {
      if (!this._config || !this._hass) return;
      const str = t(this._hass);
      if (!this._root) this._tkSetup();
      // Once what follows is drawn (see _fitSymbols).
      this._fitSymbolsSoon();
      this._applyCardLook();
      const config = this._config;
      const head = this._root.querySelector(".mt-head");
      // The title line. A title is the Details format's: a ticker has no
      // use for one. The "+" that adds an instrument stands on this line
      // only while the card shows no instrument - with one, it is among the
      // buttons over the instrument under the pointer (see _toolsOver) and
      // in the details' line of buttons (see _drawPage).
      const drawHead = (inButtons) => {
        const adds = !inButtons && config.show_add_button !== false && this._isAdmin(this._hass);
        const named = ["detail", "allocation", "alerts"].includes(config.layout) ? config.title || "" : "";
        const title =
          named || adds
            ? `<div class="mt-title" style="${elementStyle(config, "title")}">${escapeHtml(named)}</div>` +
              (adds
                ? `<button type="button" class="mt-add" data-action="add" title="${escapeHtml(str.addInstrument)}"` +
                  ` aria-label="${escapeHtml(str.addInstrument)}"><ha-icon icon="${escapeHtml(toolIcon(config, "add"))}"></ha-icon></button>`
                : "")
            : "";
        if (this._headBuilt !== title) {
          this._headBuilt = title;
          head.innerHTML = title;
        }
      };
      const detail = config.layout === "detail";
      this._root.classList.toggle("detail", detail);
      const strip = this._root.querySelector(".tk-strip");
      const page = this._root.querySelector(".tk-inline");
      const message = (text) => {
        strip.innerHTML = `<div class="tk-msg">${escapeHtml(text)}</div>`;
        this._tkBuilt = null;
      };
      let items = [];
      if (!INSTRUMENTS.list) {
        message(INSTRUMENTS.failed ? str.waiting : str.loading);
      } else {
        items = this._tkItems();
        if (!items.length) {
          // Nothing set up yet, or a choice of which nothing is left.
          message(INSTRUMENTS.list.length ? str.noneChosen : str.emptyHint);
        } else if (detail) {
          // One instrument's details on the card itself: no entries.
          if (this._tkBuilt !== null || strip.firstChild) {
            strip.innerHTML = "";
            this._tkBuilt = null;
          }
        } else if (config.layout === "allocation") {
          // Drawn anew whenever a share has changed: it is little.
          const html = this._allocHtml(items, str);
          if (html !== this._tkBuilt) {
            this._tkBuilt = html;
            strip.innerHTML = html;
          }
        } else if (config.layout === "alerts") {
          const html = this._alertsHtml(items, str);
          if (html !== this._tkBuilt) {
            this._tkBuilt = html;
            strip.innerHTML = html;
          }
        } else {
          const built = JSON.stringify([
            config,
            items.map((item) => [item.id, item.unavailable, this._tkNewsNew(item) > 0, alertState(item)]),
            this._hass.language,
            this._hass.locale || null,
            INSTRUMENTS.version,
            LOGO_FAILED.size,
          ]);
          if (built !== this._tkBuilt) {
            this._tkBuilt = built;
            this._tkBuild(strip, items, str);
          } else {
            this._tkUpdate(strip, items);
          }
        }
      }
      // The details: on the card itself in the Details format, in the
      // pop-up in every other. Never both.
      const shown = detail && items.length ? this._pageItem(items) : null;
      drawHead(items.length > 0);
      this._toolsDraw(str, detail || ["allocation", "alerts"].includes(config.layout) ? [] : items);
      strip.hidden = !!shown;
      page.hidden = !shown;
      if (detail) this._detail = null;
      if (shown) this._drawPage(page, shown, items, str, false);
      this._tkRenderPopup(str, items);
    }

    // The buttons over the instrument under the pointer, in the three
    // ticker formats: the "+", the pencil and the trash can, each where its
    // switch is on, for administrators. One plate for the whole card, set
    // on the instrument the pointer is over - the instruments themselves
    // are drawn again and again, and in the ticker several times over.
    _toolsDraw(str, items) {
      const tools = this._root.querySelector(".tk-tools");
      const config = this._config;
      const admin = items.length > 0 && this._isAdmin(this._hass);
      const button = (on, action, icon, label) =>
        on && admin
          ? `<button type="button" tabindex="-1" data-action="${action}" title="${escapeHtml(label)}" aria-label="${escapeHtml(label)}"><ha-icon icon="${icon}"></ha-icon></button>`
          : "";
      const html =
        button(config.show_add_button !== false, "add", escapeHtml(toolIcon(config, "add")), str.addInstrument) +
        button(config.show_edit_buttons !== false, "edit", escapeHtml(toolIcon(config, "edit")), str.editInstrument) +
        button(config.show_remove_button !== false, "remove", escapeHtml(toolIcon(config, "remove")), str.removeInstrument);
      if (this._toolsBuilt !== html) {
        this._toolsBuilt = html;
        tools.innerHTML = html;
        this._toolsHide();
      }
      // The instrument it stood on is gone, or the details are open over it.
      if (this._toolsId && (this._detail || !items.some((item) => item.id === this._toolsId))) this._toolsHide();
    }

    _toolsOver(ev) {
      const tools = this._root.querySelector(".tk-tools");
      if (!this._toolsBuilt || this._detail) return;
      const el = ev.composedPath().find(
        (node) => node.dataset && node.dataset.id && node.classList && /\btk-(item|mini|slide)\b/.test(node.className)
      );
      if (!el) return;
      // A compact row is the whole card; a tile and a ticker entry are
      // their own box.
      const boxEl = el.classList.contains("tk-slide") ? this._root.querySelector(".tk-line") || el : el;
      const box = boxEl.getBoundingClientRect();
      const card = this._root.getBoundingClientRect();
      const id = el.dataset.id;
      const at = `${id}|${Math.round(box.left)}|${Math.round(box.top)}`;
      if (this._toolsAt === at && !tools.hidden) return;
      this._toolsAt = at;
      this._toolsId = id;
      tools.hidden = false;
      // The ticker stands still while the plate is up (see .tkr.tools).
      this._root.classList.add("tools");
      for (const button of tools.querySelectorAll("button")) button.dataset.id = id;
      const width = tools.offsetWidth;
      const height = tools.offsetHeight;
      // At the instrument's right end, inside the card.
      const right = Math.min(box.right, card.right) - 4;
      // Half way up a row; in a tile's top corner - its middle is where the
      // pointer comes to click the tile.
      const wanted = el.classList.contains("tk-mini") ? box.top + 4 : box.top + (box.height - height) / 2;
      const top = Math.max(0, Math.min(wanted - card.top, card.height - height));
      tools.style.left = `${Math.max(2, Math.min(right - card.left - width, card.width - width - 2)).toFixed(1)}px`;
      tools.style.top = `${top.toFixed(1)}px`;
    }

    _toolsHide() {
      const tools = this._root && this._root.querySelector(".tk-tools");
      if (!tools) return;
      tools.hidden = true;
      this._toolsId = null;
      this._toolsAt = null;
      this._root.classList.remove("tools");
    }

    // The instrument the Details format shows: the one the reader stepped
    // to, else the one set in the editor, else the first of the list.
    _pageItem(items) {
      const wanted = [this._pageId, this._config.detail_instrument];
      for (const id of wanted) {
        const item = id ? items.find((entry) => entry.id === id) : null;
        if (item) return item;
      }
      return items[0];
    }

    // Colours, sizes and the backgrounds - everything the config says about
    // the whole card, written onto it as variables.
    _applyCardLook() {
      const card = this._root;
      const config = this._config;
      const setVar = (name, value) => {
        if (value === "" || value === undefined || value === null) card.style.removeProperty(name);
        else card.style.setProperty(name, String(value));
      };
      setVar("--mt-add", config.add_color || "");
      setVar("--mt-edit", config.edit_color || "");
      setVar("--mt-remove", config.remove_color || "");
      for (const name of ["add", "edit", "remove"]) {
        const size = config[`${name}_size`];
        setVar(`--mt-${name}-size`, CSS.supports("width", size) ? size : "");
      }
      setVar("--mt-gain", config.gain_color || GAIN);
      setVar("--mt-loss", config.loss_color || LOSS);
      setVar("--mt-news-new", config.news_new_color || "");
      setVar("--mt-alert", config.alert_color || "");
      setVar("--mt-alert-on", config.alert_on_color || "");
      setVar("--mt-aa-track", config.alerts_track_color || "");
      setVar("--mt-aa-mark", config.alerts_mark_color || "");
      setVar("--mt-aa-mark-width", Number(config.alerts_mark_width) > 0 ? `${Number(config.alerts_mark_width)}px` : "");
      setVar("--mt-aa-track-height", Number(config.alerts_track_height) > 0 ? `${Number(config.alerts_track_height)}px` : "");
      setVar("--mt-alert-size", CSS.supports("width", config.alert_size) ? config.alert_size : "");
      setVar("--mt-alert-on-size", CSS.supports("width", config.alert_on_size) ? config.alert_on_size : "");
      setVar("--mt-alert-none", config.alert_none_color || "");
      setVar("--mt-alert-none-size", CSS.supports("width", config.alert_none_size) ? config.alert_none_size : "");
      setVar("--mt-sma", config.sma_color || SMA_COLOR);
      setVar("--mt-sma50", config.sma50_color || SMA50_COLOR);
      setVar("--mt-ema", config.ema_color || EMA_COLOR);
      setVar("--mt-rsi", config.rsi_color || RSI_COLOR);
      const px = (value) => (Number.isFinite(Number(value)) && Number(value) > 0 ? `${Number(value)}px` : "");
      setVar("--mt-chart-height", px(config.chart_height));
      setVar("--mt-chart-line", px(config.chart_line_width));
      // Empty leaves the gain and the loss colour in charge - see the
      // stylesheet, where these fall back to them.
      setVar("--mt-line-up", config.chart_line_up_color || "");
      setVar("--mt-line-down", config.chart_line_down_color || "");
      setVar("--mt-vol-up", config.volume_up_color || "");
      setVar("--mt-vol-down", config.volume_down_color || "");
      const faint = Number(config.volume_opacity);
      setVar("--mt-vol-opacity", Number.isFinite(faint) && faint > 0 ? String(Math.min(100, faint) / 100) : "");
      setVar("--mt-sma-line", px(config.sma_width));
      setVar("--mt-sma50-line", px(config.sma50_width));
      setVar("--mt-ema-line", px(config.ema_width));
      setVar("--mt-rsi-line", px(config.rsi_width));
      // The chart's own lines. A colour of the user's own is drawn in full:
      // the paleness belongs to the theme's colour.
      for (const name of ["grid", "ref"]) {
        setVar(`--mt-${name}`, config[`${name}_color`] || "");
        setVar(`--mt-${name}-opacity`, config[`${name}_color`] ? "1" : "");
        setVar(`--mt-${name}-line`, px(config[`${name}_width`]));
      }
      setVar("--mt-ref-dash", { solid: "none", dotted: "1 3" }[config.ref_style] || "");
      setVar("--mt-grid-dash", { dashed: "3 3", dotted: "1 3" }[config.grid_style] || "");
      setVar("--mt-tv-size", CSS.supports("width", config.tv_size) ? config.tv_size : "");
      setVar("--mt-grid-show", config.grid_show === false ? "none" : "");
      // The two lines of a portfolio's performance.
      setVar("--mt-perf-up", config.perf_line_up_color || "");
      setVar("--mt-perf-down", config.perf_line_down_color || "");
      setVar("--mt-perf-line", px(config.perf_line_width));
      setVar("--mt-pf-grid", config.perf_grid_color || "");
      setVar("--mt-pf-grid-opacity", config.perf_grid_color ? "1" : "");
      setVar("--mt-pf-grid-line", px(config.perf_grid_width));
      setVar("--mt-pf-grid-dash", { dashed: "3 3", dotted: "1 3" }[config.perf_grid_style] || "");
      setVar("--mt-pf-grid-show", config.perf_grid_show === false ? "none" : "");
      setVar("--mt-perf-index", config.perf_index_color || "");
      setVar("--mt-perf-index-line", px(config.perf_index_width));
      setVar("--mt-perf-index-dash", { dashed: "4 3", dotted: "1 3" }[config.perf_index_style] || "");
      setVar("--mt-ref-show", config.ref_show === false ? "none" : "");
      // The lines between the figures; switched off, none.
      setVar("--mt-div", config.fact_divider_color || "");
      setVar("--mt-div-line", px(config.fact_divider_width));
      setVar(
        "--mt-div-style",
        config.fact_divider === false ? "none" : ["dashed", "dotted"].includes(config.fact_divider_style) ? config.fact_divider_style : ""
      );
      setVar("--mt-logo-size", CSS.supports("width", config.logo_size) ? config.logo_size : "");
      this._applyBackground();
      const style = card.style;
      for (const name of ["base", "color", "image", "size", "repeat", "opacity"]) {
        style.removeProperty(`--tk-tile-${name}`);
      }
      if (config.tile_background !== true) return;
      style.setProperty("--tk-tile-base", "transparent");
      style.setProperty("--tk-tile-color", config.tile_background_color || "var(--mt-panel)");
      if (config.tile_background_image) {
        style.setProperty("--tk-tile-image", `url("${config.tile_background_image.replace(/"/g, "%22")}")`);
      }
      const [size, repeat] = BACKGROUND_FITS[config.tile_background_size] || BACKGROUND_FITS.cover;
      style.setProperty("--tk-tile-size", size);
      style.setProperty("--tk-tile-repeat", repeat);
      const percentage = Number(config.tile_background_opacity);
      const opacity = Number.isFinite(percentage) ? Math.max(0, Math.min(100, percentage)) : 100;
      style.setProperty("--tk-tile-opacity", String(opacity / 100));
    }

    _applyBackground() {
      const card = this._root;
      for (const name of ["color", "image", "size", "repeat", "opacity"]) {
        card.style.removeProperty(`--mt-card-background-${name}`);
      }
      if (this._config.card_background !== true) return;
      if (this._config.card_background_color) {
        card.style.setProperty("--mt-card-background-color", this._config.card_background_color);
      }
      if (this._config.card_background_image) {
        card.style.setProperty(
          "--mt-card-background-image",
          `url("${this._config.card_background_image.replace(/"/g, "%22")}")`
        );
      }
      // Two properties per choice: how the image is scaled, and whether it
      // is laid out once or tiled.
      const [size, repeat] = BACKGROUND_FITS[this._config.card_background_size] || BACKGROUND_FITS.cover;
      card.style.setProperty("--mt-card-background-size", size);
      card.style.setProperty("--mt-card-background-repeat", repeat);
      const percentage = Number(this._config.card_background_opacity);
      const opacity = Number.isFinite(percentage) ? Math.max(0, Math.min(100, percentage)) : 100;
      card.style.setProperty("--mt-card-background-opacity", String(opacity / 100));
    }

    // Built once per version of this file: a newer one that takes the card
    // over has it built again (see redraw at the end of the file), on the
    // shadow root the card already has.
    _tkSetup() {
      if (!this.shadowRoot) this.attachShadow({ mode: "open" });
      if (this._tkResize) this._tkResize.disconnect();
      this.shadowRoot.innerHTML =
        `<style>${STYLE}${TICKER_STYLE}</style>` +
        `<ha-card class="tkr"><div class="mt-head"></div><div class="tk-strip"></div><div class="tk-tools" hidden></div>` +
        // The details' page twice: on the card itself for the Details
        // format, and in the pop-up. One function draws both (_drawPage).
        `<div class="tk-wrap tk-inline" hidden><div class="tk-nav"></div><div class="tk-body"></div>` +
        `</div>` +
        `<dialog class="tk-pop"><div class="tk-wrap"><div class="tk-nav"></div><div class="tk-body"></div>` +
        `</div></dialog></ha-card>`;
      this._root = this.shadowRoot.querySelector("ha-card");
      this._headBuilt = null;
      this._popBuilt = null;
      this._root.addEventListener("click", (ev) => this._onClick(ev));
      this._root.addEventListener("keydown", (ev) => {
        if (ev.key !== "Enter" && ev.key !== " ") return;
        const el = ev.composedPath().find((node) => node.dataset && node.dataset.action);
        if (!el || el.tagName === "BUTTON") return;
        ev.preventDefault();
        this._onClick(ev);
      });
      // A picture that did not load: its place is taken by the disc with the
      // letter, in every card that shows it. An error does not bubble, so it
      // is caught on its way down.
      this._root.addEventListener(
        "error",
        (ev) => {
          const img = ev.target;
          if (!img || img.localName !== "img" || !img.parentElement || !img.parentElement.classList.contains("logo")) return;
          const src = img.getAttribute("src");
          if (!src || LOGO_FAILED.has(src)) return;
          // An uploaded logo gets a new address first - see ownLogoFailed.
          if (isOwnLogo(src) && ownLogoFailed(src)) return;
          LOGO_FAILED.add(src);
          notify();
        },
        true
      );
      const strip = this._root.querySelector(".tk-strip");
      strip.addEventListener("pointerenter", () => (this._tkHover = true));
      strip.addEventListener("pointerleave", () => (this._tkHover = false));
      // The performance's chart under the pointer. Leaving does not bubble,
      // so it is caught on its way down.
      strip.addEventListener("pointermove", (ev) => this._perfOver(ev));
      strip.addEventListener("pointerdown", (ev) => this._perfOver(ev));
      strip.addEventListener("pointerleave", (ev) => this._perfOut(ev), true);
      strip.addEventListener("pointercancel", (ev) => this._perfOut(ev), true);
      // The plate of buttons over the instrument under the pointer (see
      // _toolsOver). A mouse only: a finger has nothing to hold over an
      // instrument, and its tap opens the details, where the buttons are.
      const tools = this._root.querySelector(".tk-tools");
      this._toolsBuilt = null;
      this._toolsId = null;
      strip.addEventListener("pointermove", (ev) => {
        if (ev.pointerType === "mouse" && !ev.buttons) this._toolsOver(ev);
      });
      strip.addEventListener("pointerdown", () => this._toolsHide());
      strip.addEventListener("scroll", () => this._toolsHide(), true);
      this._root.addEventListener("pointerleave", () => this._toolsHide());
      // On the plate the pointer is still on the card's instruments: what
      // stops for it there stays stopped.
      tools.addEventListener("pointerenter", () => (this._tkHover = true));
      tools.addEventListener("pointerleave", () => (this._tkHover = false));
      const dialog = this._root.querySelector("dialog");
      this._tkDialog = dialog;
      // Escape closes a modal dialog by the browser's own doing, and says so
      // with a close event - which can arrive most of a second late. Until
      // it does the card would still hold the pop-up as open, and the next
      // price would open it again. So the card is told at once: by the
      // close button and the click beside the pop-up themselves (see
      // _tkClose), and for Escape right after the event that announces it.
      // A close event that arrives after the pop-up was opened again is not
      // for the pop-up now open.
      dialog.addEventListener("cancel", () => {
        setTimeout(() => {
          if (!dialog.open) this._popGone();
        }, 0);
      });
      dialog.addEventListener("close", () => {
        if (!dialog.open) this._popGone();
      });
      // The pop-up fills its dialog, so a click that lands on the dialog
      // itself landed beside it: on the backdrop - which is also where the
      // entry lies that opened it, so a second click on that entry closes
      // what the first one opened.
      dialog.addEventListener("click", (ev) => {
        if (ev.target === dialog) this._tkClose();
      });
      dialog.addEventListener("keydown", (ev) => {
        if (ev.key === "ArrowLeft") this._tkPopStep(-1);
        else if (ev.key === "ArrowRight") this._tkPopStep(1);
      });
      // A swipe across the pop-up goes to the next instrument - but not one
      // that starts on the chart, where the finger reads the bars.
      const body = dialog.querySelector(".tk-body");
      let startX = null;
      let startY = null;
      body.addEventListener("pointerdown", (ev) => {
        startX =
          ev.pointerType !== "mouse" && !ev.composedPath().some((n) => n.classList && n.classList.contains("plot"))
            ? ev.clientX
            : null;
        startY = ev.clientY;
      });
      body.addEventListener("pointerup", (ev) => {
        if (startX === null) return;
        const dx = ev.clientX - startX;
        startX = null;
        if (Math.abs(dx) > 60 && Math.abs(ev.clientY - startY) < 40) this._tkPopStep(dx < 0 ? 1 : -1);
      });
      if (window.ResizeObserver) {
        this._tkResize = new ResizeObserver(() => {
          this._tkFitMarquee();
          this._tkFitCarousel();
        });
        this._tkResize.observe(this._root);
      }
    }

    // What an entry is made of, piece by piece. An instrument without a
    // price keeps its place and its name, greyed, and shows no figure.
    _tkParts(item) {
      const config = this._config;
      const short = config.show_row_symbol === true && item.symbol
        ? `<span class="tk-symbol" style="${elementStyle(config, "row_symbol")}">${escapeHtml(item.symbol)}</span>`
        : "";
      const long = config.show_row_name === false
        ? ""
        : `<span class="tk-name" style="${elementStyle(config, "row_name")}">${escapeHtml(item.name)}</span>`;
      // New headlines about it: a symbol behind its name.
      const fresh = this._tkNewsNew(item);
      const label = fresh ? t(this._hass).newsNewTitle(fresh) : "";
      const news = fresh
        ? `<span class="tk-news" data-action="tk-news" data-id="${escapeHtml(item.id)}" title="${escapeHtml(label)}" aria-label="${escapeHtml(label)}"><ha-icon icon="mdi:newspaper-variant-outline"></ha-icon></span>`
        : "";
      // A price alert on it: a bell, coloured while the alert is on.
      const alarm = config.show_row_alert === false ? "" : alertState(item);
      const alarmLabel = alarm === "on" ? t(this._hass).alertOn : t(this._hass).alertSet;
      const bell = alarm
        ? `<span class="tk-alert ${alarm}" data-action="alerts" data-id="${escapeHtml(item.id)}" title="${escapeHtml(alarmLabel)}" aria-label="${escapeHtml(alarmLabel)}"><ha-icon icon="${escapeHtml(alertIcon(config, alarm))}"></ha-icon></span>`
        : "";
      return {
        logo: config.show_row_logo ? logoHtml(item) : "",
        name: short || long || news || bell ? `<span class="tk-id">${short}${long}${bell}${news}</span>` : "",
        // For the carousel, where the buttons lie over the name's end: the
        // name alone, and the symbol to be put beside the change.
        nameOnly: short || long ? `<span class="tk-id">${short}${long}</span>` : "",
        news: bell + news,
        change: config.show_row_change
          ? `<span class="tk-change ${gainClass(item.changePct)}" style="${elementStyle(config, "row_change")}">${escapeHtml(percent(this._hass, item.changePct))}</span>`
          : "",
      };
    }

    // How many headlines about the instrument are new - of those its
    // details would show. Nought where the entries carry no such symbol,
    // or the details no news.
    _tkNewsNew(item) {
      const config = this._config;
      if (config.show_row_news === false || config.show_detail_news === false) return 0;
      const entry = newsOf(item.id, this._hass.language);
      return newsShown(entry.data, config.detail_news_count, config.detail_news_days).filter((one) =>
        newsIsNew(one, item.id, newsSeen)
      ).length;
    }

    // The figure an entry flashes on when it changes.
    _tkFigure(item) {
      return { amount: item.price };
    }

    _tkPrice(item, inline) {
      const config = this._config;
      if (!config.show_row_price) return "";
      const style = elementStyle(config, "row_price");
      return inline
        ? `<span class="tk-price" style="${style}">${escapeHtml(money(this._hass, item.price, item.currency, false, item.digits))}</span>`
        : `<div class="row-price tk-price" style="${style}">${splitHtml(this._hass, item.price, item.currency, item.digits)}</div>`;
    }

    // The small curve of the day, against the close of the day before.
    _tkSpark(item) {
      if (item.unavailable) return "";
      const history = historyOf(item.id, "1d").data;
      if (!history || history.bars.length < 2) return "";
      return chartSvg(history.bars.map((bar) => bar.c), {
        height: 30,
        reference: isNumber(history.previousClose) ? history.previousClose : undefined,
        lineWidth: 1.25,
      });
    }

    _tkBuild(strip, items) {
      const config = this._config;
      const effect = this._tkEffect();
      // Whatever was running ran on the elements about to be replaced.
      this._tkFxEnd = null;
      this._tkStopScroll();
      this._tkPrices = this._tkPrices || {};
      items.forEach((item) => (this._tkPrices[item.id] = this._tkFigure(item).amount));
      if (config.layout === "line") {
        const loops = this._tkLoops(items);
        this._tkIndex = (((this._tkIndex || 0) % items.length) + items.length) % items.length;
        const slides = items.map((item) => {
          const parts = this._tkParts(item);
          return (
            `<div class="tk-slide${item.unavailable ? " na" : ""}" data-id="${escapeHtml(item.id)}">${parts.logo}` +
            `<div class="tk-main">${parts.name}${parts.change}</div>` +
            (config.show_row_sparkline ? `<div class="tk-spark">${this._tkSpark(item)}</div>` : "") +
            `${this._tkPrice(item)}</div>`
          );
        });
        strip.innerHTML =
          `<div class="tk-line" data-action="tk-current" tabindex="0" role="button">` +
          `<div class="tk-track${effect === "slide" ? "" : " stack"}"${loops ? ` data-loop="${items.length}"` : ""}>` +
          (loops ? slides[slides.length - 1] : "") +
          slides.join("") +
          (loops ? slides[0] : "") +
          `</div></div>`;
        strip.querySelector(".tk-track").style.setProperty("--tk-fx", `${this._tkFxMs()}ms`);
        this._tkPlaceLine();
        this._tkWireLine(strip.querySelector(".tk-line"));
      } else if (config.layout === "carousel") {
        const loops = this._tkLoops(items);
        const tiles =
          items
            .map((item) => {
              const parts = this._tkParts(item);
              return (
                `<div class="tk-mini${item.unavailable ? " na" : ""}" data-action="tk-open" data-id="${escapeHtml(item.id)}" tabindex="0" role="button" aria-label="${escapeHtml(item.name)}">` +
                `${parts.nameOnly}<div class="tk-mini-mid"><div class="tk-mini-values">${this._tkPrice(item)}` +
                (parts.change || parts.news ? `<div class="tk-mini-change">${parts.change}${parts.news}</div>` : "") +
                `</div>${parts.logo}</div>` +
                (config.show_row_sparkline ? `<div class="tk-spark">${this._tkSpark(item)}</div>` : "") +
                `</div>`
              );
            })
            .join("");
        // Only the middle set can be reached with the keyboard.
        this._tkLoopSet = tiles;
        this._tkLoopClone = tiles.replace(/tabindex="0"/g, 'tabindex="-1" aria-hidden="true"');
        this._tkLoopTotal = items.length;
        this._tkLoopCopies = 3;
        this._tkPeriodPx = 0;
        strip.innerHTML = loops
          ? `<div class="tk-scroll loop" data-fx="${effect}">${this._tkLoopClone}${tiles}${this._tkLoopClone}</div>`
          : `<div class="tk-scroll" data-fx="${effect}">${tiles}</div>`;
        this._tkWireScroll(strip.querySelector(".tk-scroll"));
        this._tkFitCarousel();
      } else {
        this._tkSet =
          `<div class="tk-set">` +
          items
            .map((item) => {
              const parts = this._tkParts(item);
              return (
                `<div class="tk-item${item.unavailable ? " na" : ""}" data-action="tk-open" data-id="${escapeHtml(item.id)}">` +
                `${parts.logo}${parts.name}${this._tkPrice(item, true)}${parts.change}</div>`
              );
            })
            .join("") +
          `</div>`;
        this._tkCopies = 1;
        // Its entries run past and repeat: the ticker as a whole takes the
        // keyboard, and Enter opens the entry at its left edge - from where
        // the pop-up's arrows lead to every other.
        strip.innerHTML =
          `<div class="tk-marquee auto${lessMotion() ? " calm" : ""}" data-action="tk-current" tabindex="0" role="button"><div class="tk-run auto">` +
          this._tkSet.repeat(2) +
          `</div></div>`;
        this._tkNoScroll(strip.querySelector(".tk-marquee"));
        this._tkFitMarquee();
      }
    }

    // A ticker shorter than its card would run out of itself: the set is
    // repeated until one half fills the card, and the speed follows.
    _tkFitMarquee() {
      const box = this._root && this._root.querySelector(".tk-marquee.auto");
      if (!box) return;
      const run = box.querySelector(".tk-run");
      const set = run.querySelector(".tk-set");
      const width = set.getBoundingClientRect().width;
      if (!(width > 0)) return;
      const copies = Math.max(1, Math.ceil(box.clientWidth / width));
      if (copies !== this._tkCopies) {
        this._tkCopies = copies;
        run.innerHTML = this._tkSet.repeat(copies * 2);
        this._tkRefresh();
      }
      const count = run.querySelectorAll(".tk-set:first-child .tk-item").length;
      run.style.setProperty("--tk-dur", `${count * copies * tickerSeconds(this._config)}s`);
    }

    // Copies laid in after the build are as old as the build: its prices,
    // its changes, its curves. This brings them up to now.
    _tkRefresh() {
      const strip = this._root && this._root.querySelector(".tk-strip");
      if (strip && this._tkPrices && INSTRUMENTS.list) this._tkUpdate(strip, this._tkItems());
    }

    _tkUpdate(strip, items) {
      const byId = new Map(items.map((item) => [item.id, item]));
      const inline = this._config.layout === "ticker";
      for (const el of strip.querySelectorAll("[data-id]")) {
        const item = byId.get(el.dataset.id);
        if (!item) continue;
        const parts = this._tkParts(item);
        const change = el.querySelector(".tk-change");
        if (change && parts.change) change.outerHTML = parts.change;
        const price = el.querySelector(".tk-price");
        if (price) {
          price.outerHTML = this._tkPrice(item, inline);
          if (this._tkPrices[item.id] !== this._tkFigure(item).amount) {
            const fresh = el.querySelector(".tk-price");
            fresh.classList.add("tk-flash");
            setTimeout(() => fresh.classList.remove("tk-flash"), 900);
          }
        }
        const spark = el.querySelector(".tk-spark");
        if (spark) spark.innerHTML = this._tkSpark(item);
      }
      items.forEach((item) => (this._tkPrices[item.id] = this._tkFigure(item).amount));
    }

    _tkWireLine(line) {
      let startX = null;
      let moved = false;
      const track = line.querySelector(".tk-track");
      this._tkNoScroll(line);
      line.addEventListener("pointerdown", (ev) => {
        if (ev.pointerType === "mouse" && ev.button !== 0) return;
        startX = ev.clientX;
        moved = false;
        this._tkSwiped = false;
      });
      line.addEventListener("pointermove", (ev) => {
        if (startX === null) return;
        // Let go of outside the row, where no pointerup reaches it: without
        // this the row would follow the pointer with no button held.
        if (!ev.buttons) {
          startX = null;
          this._tkDragging = false;
          track.classList.remove("drag");
          this._tkPlaceLine();
          return;
        }
        const dx = ev.clientX - startX;
        if (!moved && Math.abs(dx) > 6) {
          moved = true;
          this._tkDragging = true;
          track.classList.add("drag");
          line.setPointerCapture(ev.pointerId);
        }
        if (moved) this._tkPlaceLine(dx);
      });
      const end = (ev) => {
        if (startX === null) return;
        const dx = ev.clientX - startX;
        startX = null;
        this._tkDragging = false;
        track.classList.remove("drag");
        if (moved) this._tkSwiped = true;
        if (ev.type === "pointerup" && moved && Math.abs(dx) > 30) this._tkStep(dx < 0 ? 1 : -1);
        else this._tkPlaceLine();
      };
      line.addEventListener("pointerup", end);
      line.addEventListener("pointercancel", end);
    }

    // A finger scrolls the tiles by itself; a mouse needs this.
    _tkWireScroll(box) {
      let startX = null;
      let startLeft = 0;
      let moved = false;
      box.addEventListener("pointerdown", (ev) => {
        this._tkSwiped = false;
        this._tkStopScroll();
        if (ev.pointerType !== "mouse") return;
        startX = ev.clientX;
        startLeft = box.scrollLeft;
        moved = false;
      });
      box.addEventListener("pointermove", (ev) => {
        if (startX === null) return;
        const dx = ev.clientX - startX;
        if (!moved && Math.abs(dx) > 5) {
          moved = true;
          box.classList.add("drag");
        }
        if (moved) box.scrollLeft = startLeft - dx;
      });
      const end = () => {
        if (startX === null) return;
        startX = null;
        box.classList.remove("drag");
        if (moved) this._tkSwiped = true;
      };
      box.addEventListener("pointerup", end);
      box.addEventListener("pointerleave", end);
      if (box.dataset.fx === "focus" || box.dataset.fx === "coverflow") {
        let queued = false;
        box.addEventListener("scroll", () => {
          if (queued) return;
          queued = true;
          requestAnimationFrame(() => {
            queued = false;
            this._tkPaintTiles(box);
          });
        });
      }
      if (box.classList.contains("loop")) {
        let idle = null;
        box.addEventListener("scroll", () => {
          clearTimeout(idle);
          idle = setTimeout(() => this._tkWrapScroll(box), 160);
        });
      }
    }

    // ------------------------------------------------------------ the pop-up
    _tkOpen(id) {
      // Set to open TradingView instead: the instrument's page there, in a
      // tab of its own. An instrument without a symbol there has no page -
      // its click opens the details as ever, rather than nothing.
      if (this._config.tap_action === "tradingview") {
        const item = this._tkItems().find((entry) => entry.id === id);
        const page = item ? tradingViewUrl(this._hass, item.tradingview) : null;
        if (page) {
          window.open(page, "_blank", "noopener,noreferrer");
          return;
        }
      }
      this._detail = id;
      this._popRange = rangeOf(this._config.default_range);
      this._popStyle = null;
      this._popBuilt = null;
      this._tkBodyTop = true;
      this._render();
    }

    _tkClose() {
      if (this._tkDialog && this._tkDialog.open) this._tkDialog.close();
      this._popGone();
    }

    // The pop-up is closed: the card lets go of its instrument, and the
    // ticker runs again.
    _popGone() {
      if (!this._detail) return;
      this._detail = null;
      this._popBuilt = null;
      this._series = null;
      this._render();
    }

    // To the next instrument or the one before, endlessly: in the pop-up,
    // or on the card in the Details format - where the place is the card's
    // own for as long as it stands on the page, and nothing of the config.
    _tkPopStep(direction) {
      const items = this._tkItems();
      if (items.length < 2) return;
      const next = (now) => items[(now + direction + items.length) % items.length].id;
      if (this._detail) {
        this._detail = next(items.findIndex((item) => item.id === this._detail));
        this._tkBodyTop = true;
      } else if (this._config.layout === "detail") {
        this._pageId = next(items.indexOf(this._pageItem(items)));
      } else {
        return;
      }
      this._render();
    }

    // The instrument whose details are on show, in the pop-up or on the card.
    _shownId() {
      if (this._detail) return this._detail;
      if (this._config.layout !== "detail") return null;
      const items = this._tkItems();
      return items.length ? this._pageItem(items).id : null;
    }

    // The periods as a row of plain words, the one on show underlined.
    _rangeTabsHtml(selected, str) {
      // The looks Layout gives them: one for the period on show, one for
      // the others.
      const look = elementStyle(this._config, "detail_ranges");
      const lookOn = elementStyle(this._config, "detail_range_on");
      return (
        `<div class="range-tabs" role="group">` +
        shownRanges(this._config).map(
          (range) =>
            `<button type="button" class="${range.key === selected ? "active" : ""}"` +
            ` aria-pressed="${range.key === selected}" data-action="range" data-key="${range.key}"` +
            ` style="${range.key === selected ? lookOn : look}">` +
            `${escapeHtml(str[range.name])}</button>`
        ).join("") +
        `</div>`
      );
    }

    _tkRenderPopup(str, items) {
      const dialog = this._tkDialog;
      const config = this._config;
      const item = this._detail ? items.find((entry) => entry.id === this._detail) : null;
      if (!item) {
        this._detail = null;
        this._root.classList.remove("hold");
        if (dialog.open) dialog.close();
        return;
      }
      this._root.classList.add("hold");
      this._drawPage(dialog.querySelector(".tk-wrap"), item, items, str, true);
      if (!dialog.open) dialog.showModal();
    }

    // The details of one instrument, built into `wrap` - the pop-up's or
    // the card's own (see _tkSetup): its line of buttons, its page and the
    // line the logos' source asks for.
    //
    // The page is a data sheet in two columns: on the left who it is, what
    // it costs and the list of its figures; on the right the chart with its
    // periods and, under it, what is held. Where the page is too narrow for
    // two columns the same four parts stand under one another - head,
    // chart, position, figures - which is why the columns are only boxes
    // the stylesheet can dissolve (see .d-page).
    //
    // Each part is drawn again only when what it shows has changed. A new
    // price redraws the head, the position and the figures and leaves the
    // chart standing - with the period chosen and whatever the pointer is
    // reading off it - and only moves the price on its tag.
    _drawPage(wrap, item, items, str, popup) {
      const config = this._config;
      const hass = this._hass;
      const body = wrap.querySelector(".tk-body");
      let built = this._popBuilt;
      if (!built || built.wrap !== wrap || !body.querySelector(":scope > .d-page")) {
        built = this._popBuilt = { wrap };
        body.innerHTML =
          `<div class="d-page"><div class="d-left"><div class="d-top"></div><div class="d-facts"></div></div>` +
          `<div class="d-right"><div class="d-chart"></div><div class="d-pos"></div></div></div>` +
          `<div class="d-news"></div>`;
        this._series = null;
      }
      const [topEl, factsEl, chartEl, posEl] = ["top", "facts", "chart", "pos"].map((part) => body.querySelector(`.d-${part}`));
      const range = rangeOf(this._popRange);
      // Asked for here, ahead of the drawing: what they hold decides whether
      // there is anything new to draw.
      const history = config.show_detail_chart !== false ? historyOf(item.id, range, true) : null;
      const details = config.show_detail_facts !== false ? detailsOf(item.id) : null;
      const news = config.show_detail_news !== false ? newsOf(item.id, hass.language) : null;
      const day = historyKept(item.id, "1d");
      const at = items.findIndex((entry) => entry.id === item.id);
      const edits = config.show_edit_buttons !== false && this._isAdmin(hass);
      const common = JSON.stringify([
        config,
        item.id,
        hass.language,
        hass.locale || null,
        INSTRUMENTS.version,
        LOGO_FAILED.size,
      ]);
      const draw = (part, key, run) => {
        if (built[part] === key) return;
        built[part] = key;
        run();
      };

      // The line of buttons: back and forth where there are several; at its
      // end the "+", the pencil for whoever may change the instrument, the
      // trash can that removes it, TradingView's logo - the way to the instrument's page
      // there, in a tab of its own, where the integration knows what it is
      // called there - and in the pop-up the way out, always the last.
      const adds = config.show_add_button !== false && this._isAdmin(hass);
      const removes = config.show_remove_button !== false && this._isAdmin(hass);
      const tvPage = config.show_detail_tradingview !== false ? tradingViewUrl(hass, item.tradingview) : null;
      const dark = !!(hass.themes && hass.themes.darkMode);
      draw("nav", JSON.stringify([common, at, items.length, edits, popup, adds, removes, tvPage, dark]), () => {
        const nav = wrap.querySelector(".tk-nav");
        const button = (action, icon, label) =>
          `<button type="button" data-action="${action}" title="${escapeHtml(label)}" aria-label="${escapeHtml(label)}"><ha-icon icon="${icon}"></ha-icon></button>`;
        nav.innerHTML =
          (items.length > 1
            ? button("tk-prev", "mdi:chevron-left", str.tkPrev) +
              `<span class="tk-count">${at + 1} / ${items.length}</span>` +
              button("tk-next", "mdi:chevron-right", str.tkNext)
            : "") +
          `<span class="tk-gap"></span>` +
          (adds ? button("add", escapeHtml(toolIcon(config, "add")), str.addInstrument) : "") +
          (edits ? button("edit", escapeHtml(toolIcon(config, "edit")), str.editInstrument) : "") +
          (removes ? button("remove", escapeHtml(toolIcon(config, "remove")), str.removeInstrument) : "") +
          (tvPage
            ? `<a class="tk-tv${dark ? " dark" : ""}" href="${escapeHtml(tvPage)}" target="_blank" rel="noopener noreferrer"` +
              `${config.tv_logo_color ? ` style="${escapeHtml(`color: ${config.tv_logo_color}`)}"` : ""}` +
              ` title="${escapeHtml(str.openTradingView)}" aria-label="${escapeHtml(str.openTradingView)}">${TRADINGVIEW_LOGO}</a>`
            : "") +
          (popup ? button("tk-close", "mdi:close", str.close) : "");
        nav.hidden = !popup && items.length < 2 && !edits && !adds && !removes && !tvPage;
      });

      // The change under the price is the period's: the head follows the
      // period shown and the series it is measured on.
      const measured = range !== "1d" && history && history.data ? history : null;
      draw("top", JSON.stringify([common, item.stamp, range, measured ? measured.at : 0]), () => {
        topEl.innerHTML = this._topHtml(item, str, range, measured ? measured.data : null);
        posEl.innerHTML = this._positionHtml(item, str, range, measured ? measured.data : null);
      });

      if (history) {
        // A price beyond the chart's scale needs the chart drawn again; one
        // inside it only moves the tag.
        const series = this._series;
        const fits =
          !isNumber(item.price) ||
          !series ||
          !series.scale ||
          (item.price >= series.scale.low && item.price <= series.scale.high);
        const key = JSON.stringify([
          common,
          range,
          TREND.sma,
          TREND.sma50,
          TREND.ema,
          TREND.rsi,
          this._popStyle,
          item.unavailable,
          history.at,
          history.error,
          history.data ? 0 : history.asking,
        ]);
        if (built.chart !== key || !fits) {
          built.chart = key;
          this._series = null;
          // The period just chosen with the keyboard keeps the keyboard:
          // its button is a new one after the chart was drawn again.
          const focused = this.shadowRoot.activeElement;
          const held = focused && chartEl.contains(focused) && focused.dataset.action ? { ...focused.dataset } : null;
          chartEl.innerHTML = this._chartPartHtml(item, str, range, history);
          this._wireChart(body);
          if (held) {
            const again = [...chartEl.querySelectorAll(`[data-action="${held.action}"]`)].find(
              (el) => held.action !== "range" || el.dataset.key === held.key
            );
            if (again) again.focus();
          }
        } else {
          this._moveTag(chartEl, item);
        }
      } else {
        draw("chart", "off", () => {
          chartEl.innerHTML = "";
          this._series = null;
        });
      }

      // Ahead of the figures, what the chart is drawn with: there with the
      // chart, whether the figures are shown or not.
      const marks = history ? [TREND.sma, TREND.sma50, TREND.ema, TREND.rsi, history.at, this._series ? 1 : 0] : null;
      const factsKey =
        details || marks
          ? JSON.stringify([common, item.stamp, range, details ? [details.at, details.error] : 0, day ? day.at : 0, marks])
          : "off";
      draw("facts", factsKey, () => {
        // The eye just pressed with the keyboard keeps the keyboard.
        const focused = this.shadowRoot.activeElement;
        const held = focused && factsEl.contains(focused) ? focused.dataset.key : null;
        factsEl.innerHTML =
          (marks ? this._marksHtml(item, str) : "") + (details ? this._factsHtml(item, str, range, details) : "");
        const again = held ? factsEl.querySelector(`.eye[data-key="${held}"]`) : null;
        if (again) again.focus();
      });

      // The news, under everything else. Without any - none yet, or none
      // at all - there is no heading either.
      draw("news", news ? JSON.stringify([common, news.at, !!this._popNewsOpen, NEWS_SEEN_VERSION]) : "off", () => {
        body.querySelector(".d-news").innerHTML = news
          ? this._newsHtml(str, news.data, {
              count: config.detail_news_count,
              days: config.detail_news_days,
              compact: config.detail_news_compact === true,
              open: !!this._popNewsOpen,
              action: "news-open",
              looks: ["news_heading", "news_title", "news_meta"],
              idOf: () => item.id,
              keep: (ids) => (this._popNewsIds = ids),
            })
          : "";
      });

      if (popup && this._tkBodyTop) body.scrollTop = 0;
      this._tkBodyTop = false;
    }

    // The symbols that stand beside a word - the alert's, the one for new
    // headlines: each drawing centred on the capitals of its word. Measured
    // on the page, because nothing else is right in every place they stand:
    // a line of a list, a tile, a row of figures, each laid out its own way.
    // After every drawing, and again while a symbol's shape is still on its
    // way - Home Assistant fetches it by name.
    _fitSymbolsSoon() {
      if (this._fitQueued) return;
      this._fitQueued = true;
      requestAnimationFrame(() => {
        this._fitQueued = false;
        this._fitSymbols(0);
      });
    }

    _fitSymbols(attempt) {
      const roots = [this._root, this._popBuilt && this._popBuilt.wrap].filter((root) => root && root.isConnected);
      let waiting = false;
      for (const root of roots) {
        for (const holder of root.querySelectorAll(".tk-alert, .tk-news, .fact-bell")) {
          if (!this._fitSymbol(holder)) waiting = true;
        }
      }
      if (waiting && attempt < 20) setTimeout(() => this._fitSymbols(attempt + 1), attempt < 6 ? 16 : 150);
    }

    // True once the symbol is in place, or cannot be seen; false while its
    // shape is not there yet.
    _fitSymbol(holder) {
      const icon = holder.querySelector("ha-icon");
      if (!icon) return true;
      // The word it stands beside: the one after it, the one before it, or
      // what it stands in.
      const worded = (el) => el && el.nodeType === 1 && !el.matches(".tk-alert, .tk-news, .fact-bell, .logo") && el.textContent.trim();
      // Past a logo, which is no word.
      const beside = (step) => {
        let el = holder[step];
        while (el && el.matches(".logo")) el = el[step];
        return worded(el) ? el : null;
      };
      const word = beside("nextElementSibling") || beside("previousElementSibling") || holder.parentElement;
      if (!word) return true;
      const before = icon.style.transform;
      const ink = iconInk(icon);
      // The drawing's own box: the svg inside, which is the symbol's size -
      // the element around it is a line high.
      const inner = icon.shadowRoot && icon.shadowRoot.querySelector("ha-svg-icon");
      const svg = inner && inner.shadowRoot && inner.shadowRoot.querySelector("svg");
      if (!ink || !svg) return !(icon.getBoundingClientRect().height > 0);
      icon.style.transform = "";
      const box = svg.getBoundingClientRect();
      if (!(box.height > 0)) {
        icon.style.transform = before;
        return true;
      }
      // The capitals of the word: a probe one capital high on its baseline.
      const probe = document.createElement("span");
      probe.style.cssText = "display:inline-block;width:0;height:1cap;vertical-align:baseline;visibility:hidden;";
      word.insertBefore(probe, word.firstChild);
      const cap = probe.getBoundingClientRect();
      probe.remove();
      if (!(cap.height > 0)) {
        icon.style.transform = before;
        return true;
      }
      const above = 1 - ink.fill - ink.below;
      const drawing = box.top + (above + ink.fill / 2) * box.height;
      const middle = (cap.top + cap.bottom) / 2;
      icon.style.transform = `translateY(${(middle - drawing).toFixed(2)}px)`;
      return true;
    }

    // The headlines: each a link that opens the article where it was
    // published, in a tab of its own, with its source and time beneath.
    //
    // opts: how many at most, none older than so many days (0: all),
    // whether only a line with their number stands there until it is
    // clicked - and whether it was -, the action of that click, the three
    // looks, and whether each names its instrument.
    _newsHtml(str, items, opts) {
      const config = this._config;
      const shown = newsShown(items, opts.count, opts.days);
      if (!shown.length) return "";
      // How many of them are new. A compact list says so until it is
      // opened; one that is open all the time says so while the page is.
      const ids = [...new Set(shown.map(opts.idOf))];
      const unseen = shown.filter((item) => newsIsNew(item, opts.idOf(item), newsSeen)).length;
      const fresh = opts.compact ? unseen : shown.filter((item) => newsIsNew(item, opts.idOf(item), newsBase)).length;
      const freshHtml = fresh ? `<span class="nw-new">(${escapeHtml(str.newsNew(fresh))})</span>` : "";
      // Seen: a compact list when it is opened (see _onClick), an open one
      // as soon as it is drawn.
      opts.keep(ids);
      if (!opts.compact && unseen) queueMicrotask(() => markNewsSeen(ids));
      const [headingLook, titleLook, metaLook] = opts.looks.map((name) => elementStyle(config, name));
      const when = { day: "numeric", month: "numeric", hour: "2-digit", minute: "2-digit" };
      const head = opts.compact
        ? `<button type="button" class="nw-head nw-fold" data-action="${opts.action}" aria-expanded="${opts.open ? "true" : "false"}"` +
          ` style="${headingLook}"><span>${escapeHtml(str.newsTitle)}</span>` +
          `<span class="nw-count" style="${metaLook}">${escapeHtml(str.newsCount(shown.length))}</span>${freshHtml}` +
          `<ha-icon icon="${opts.open ? "mdi:chevron-up" : "mdi:chevron-down"}"></ha-icon></button>`
        : `<div class="nw-head" style="${headingLook}">${escapeHtml(str.newsTitle)} ${freshHtml}</div>`;
      if (opts.compact && !opts.open) return head;
      return (
        head +
        shown
          .map((item) => {
            const meta = [opts.named ? item.name : "", item.source, item.published ? dateTime(this._hass, item.published, when) : ""].filter(Boolean).join(" · ");
            return (
              `<a class="nw${newsIsNew(item, opts.idOf(item), newsBase) ? " new" : ""}" href="${escapeHtml(item.url)}" target="_blank" rel="noopener noreferrer">` +
              `<span class="nw-t" style="${titleLook}">${escapeHtml(item.title)}</span>` +
              (meta ? `<span class="nw-m" style="${metaLook}">${escapeHtml(meta)}</span>` : "") +
              `</a>`
            );
          })
          .join("")
      );
    }

    // The last price on its tag at the chart's side, moved to a new price
    // without the chart being drawn again.
    _moveTag(chartEl, item) {
      const series = this._series;
      const tag = chartEl.querySelector(".y-axis .now");
      if (!series || !series.scale || !tag || !isNumber(item.price)) return;
      const text = series.figure(item.price);
      if (tag.textContent !== text) tag.textContent = text;
      tag.style.top = `${series.scale.top(item.price).toFixed(2)}%`;
      tag.classList.toggle("up", item.price >= series.base);
      tag.classList.toggle("down", item.price < series.base);
    }

    // The head of the details: logo and name with the line that says what
    // and where it is and whether its market is open, then the price and
    // under it the day's change in one coloured line.
    _topHtml(item, str, range, history) {
      const config = this._config;
      const hass = this._hass;
      const states = { open: str.stOpen, closed: str.stClosed, pre: str.stPre, post: str.stPost };
      const open = !item.unavailable && item.marketState === "open";
      const stateText = item.unavailable ? str.unavailable : states[item.marketState] || "";
      // Each part of the line in the look Layout gives it.
      const part = (text, name) => (text ? [`<span style="${elementStyle(config, name)}">${escapeHtml(text)}</span>`] : []);
      const sub = part(item.symbol, "detail_symbol")
        .concat(part(item.exchange, "detail_exchange"))
        .concat(
          stateText
            ? [
                `<span class="d-state" style="${elementStyle(config, "detail_state")}">` +
                  `${open ? `<span class="d-dot"></span>` : ""}${escapeHtml(stateText)}</span>`,
              ]
            : []
        )
        .join(" · ");
      let html =
        `<div class="d-head${item.unavailable ? " na" : ""}">${config.show_detail_logo !== false ? logoHtml(item, true) : ""}<div class="d-id">` +
        `<div class="d-name" style="${elementStyle(config, "detail_name")}">${escapeHtml(item.name)}</div>` +
        (sub ? `<div class="d-sub">${sub}</div>` : "") +
        `</div></div>`;
      if (item.unavailable) return html;
      html +=
        `<div class="total" style="${elementStyle(config, "detail_price")}">` +
        `${escapeHtml(money(hass, item.price, item.currency, false, item.digits))}</div>`;
      // Percent first, the amount in brackets behind it: "-0.55% (-$0.49) today".
      // On a day, today's change as the source gives it; on any longer
      // period, the change over that period, measured on its series. Until
      // the series is there, today's stands in.
      const over = range && range !== "1d" ? periodChange(history, item.price) : null;
      const amount = over ? over.amount : item.change;
      const points = over ? over.percent : item.changePct;
      const moved = bracketed(
        isNumber(points) ? percent(hass, points) : "",
        isNumber(amount) ? money(hass, amount, item.currency, true, item.digits) : ""
      );
      if (moved) {
        const side = gainClass(isNumber(amount) ? amount : points);
        const span = over ? str[`chg${range}`] || "" : str.changeToday;
        html += `<div class="change ${side}" style="${elementStyle(config, "detail_change")}"><span>${escapeHtml(`${moved} ${span}`.trim())}</span></div>`;
      }
      return html;
    }

    // SMA, EMA and RSI at the head of the figures: each by name with an eye
    // that shows or hides it in the chart - in its colour while it is
    // shown - and its
    // last value in the period shown - there whether it is drawn or not.
    // Each where the card's editor lets the chart have it.
    _marksHtml(item, str) {
      const config = this._config;
      const hass = this._hass;
      const series = this._series;
      const lastOf = (list) => {
        for (let index = (list || []).length - 1; index >= 0; index--) if (isNumber(list[index])) return list[index];
        return null;
      };
      const row = (name, label, text, help) => {
        const on = TREND[name];
        const tip = escapeHtml(on ? str.hideLine : str.showLine);
        return (
          `<div class="fact mark ${name}${on ? "" : " off"}"><dt style="${elementStyle(config, "fact_label")}"><span class="explained" title="${escapeHtml(help)}">${escapeHtml(label)}</span>` +
          `<button type="button" class="eye" data-action="trend-line" data-key="${name}" aria-pressed="${on ? "true" : "false"}"` +
          ` title="${tip}" aria-label="${escapeHtml(label)}: ${tip}"><ha-icon icon="${on ? "mdi:eye-outline" : "mdi:eye-off-outline"}"></ha-icon></button></dt>` +
          `<dd style="${elementStyle(config, "fact_value")}">${escapeHtml(text || "\u2013")}</dd></div>`
        );
      };
      const price = (list) => money(hass, lastOf(list), item.currency, false, item.digits);
      const strength = series ? lastOf(series.rsi) : null;
      const each = {
        sma: () => (config.show_detail_sma !== false ? row("sma", str.legSma, series ? price(series.sma) : "", str.hSma) : ""),
        sma50: () => (config.show_detail_sma50 !== false ? row("sma50", str.legSma50, series ? price(series.sma50) : "", str.hSma50) : ""),
        ema: () => (config.show_detail_ema !== false ? row("ema", str.legEma, series ? price(series.ema) : "", str.hEma) : ""),
        rsi: () => (config.show_detail_rsi !== false ? row("rsi", str.legRsi, isNumber(strength) ? plain(hass, strength, 1) : "", str.hRsi) : ""),
      };
      // In the order the card's editor gives them.
      const rows = orderOf(config.mark_order, MARK_NAMES).map((name) => each[name]()).join("");
      return rows ? `<dl class="facts marks">${rows}</dl>` : "";
    }

    // The periods as plain words at the right; at the left the quiet button
    // for candlesticks or a line; and the chart.
    _chartPartHtml(item, str, range, history) {
      const style = chartStyle(this._config.chart_style, range, this._popStyle);
      const other = style === "candles" ? "line" : "candles";
      const label = other === "line" ? str.toLine : str.toCandles;
      // The button as it stands now - the one that leads to `other` - with
      // the symbol, the colour and the size Layout gives it.
      const config = this._config;
      const set = (what) => config[`style_${other}_${what}`];
      const styleIcon = typeof set("icon") === "string" && set("icon") ? set("icon") : DEFAULTS[`style_${other}_icon`];
      const styleLook = escapeHtml(
        [
          set("color") ? `color: ${set("color")}` : "",
          CSS.supports("width", set("size")) ? `--mdc-icon-size: ${set("size")}` : "",
        ]
          .filter(Boolean)
          .join("; ")
      );
      return (
        `<div class="d-tools">` +
        `<button type="button" class="style-btn" data-action="chart-style" data-key="${other}" style="${styleLook}"` +
        ` title="${escapeHtml(label)}" aria-label="${escapeHtml(label)}">` +
        `<ha-icon icon="${escapeHtml(styleIcon)}"></ha-icon></button>` +
        `${this._rangeTabsHtml(range, str)}</div>` +
        this._chartHtml(item, str, range, history, style)
      );
    }

    // "My position": what is held of the instrument, where the integration
    // says so - in one quiet box. Its first line: how much and what that is
    // worth, and at the other end the gain. Its second, smaller: what a
    // unit cost on average and what the day did to the position. With
    // amounts hidden, everything that tells how much goes - quantity,
    // value, average, every amount of money - and the percentages stay.
    _positionHtml(item, str, range, history) {
      const config = this._config;
      const hass = this._hass;
      const figures = config.show_detail_position === false ? null : positionFigures(item);
      if (!figures) return "";
      const hide = config.hide_amounts === true;
      const mark = str.amountHidden;
      const cash = (value, signed) => money(hass, value, figures.currency, signed);
      const join = (parts) => parts.filter(Boolean).map(escapeHtml).join(" · ");
      const held = join(
        hide
          ? [figures.held !== null || figures.value !== null ? mark : ""]
          : [
              figures.held !== null ? `${quantity(hass, figures.held)} ${str.units}` : "",
              figures.value !== null ? cash(figures.value) : "",
            ]
      );
      const gainSide = gainClass(figures.gain !== null ? figures.gain : figures.gainPct);
      const gain = escapeHtml(
        bracketed(
          figures.gainPct !== null ? percent(hass, figures.gainPct) : "",
          figures.gain !== null && !hide ? cash(figures.gain, true) : ""
        )
      );
      const small = [];
      if (figures.average !== null) {
        small.push(
          `${escapeHtml(str.posAvg)} ${escapeHtml(hide ? mark : money(hass, figures.average, figures.currency, false, item.digits))}`
        );
      }
      // What the position has done over the period shown - the same period
      // the change under the price is for: today on a day, and on a longer
      // one the price's move over it times what is held now. Until that
      // period's series is there, today's stands in.
      const over = range && range !== "1d" ? periodChange(history, item.price) : null;
      const moved = over && figures.held !== null ? figures.held * over.amount : over ? null : figures.today;
      const points = over ? over.percent : item.changePct;
      if (moved !== null || (over && isNumber(points))) {
        const pct = isNumber(points) ? percent(hass, points) : "";
        const text = hide ? pct || mark : bracketed(pct, moved !== null ? cash(moved, true) : "");
        const span = over ? str[`pos${range}`] || "" : str.posToday;
        const side = gainClass(moved !== null ? moved : points);
        small.push(`${escapeHtml(span)} <span class="${side}">${escapeHtml(text)}</span>`);
      }
      if (figures.realized !== null) {
        const side = gainClass(figures.realized);
        small.push(`${escapeHtml(str.posRealized)} <span class="${side}">${escapeHtml(hide ? mark : cash(figures.realized, true))}</span>`);
      }
      if (figures.costs !== null) small.push(`${escapeHtml(str.posCosts)} ${escapeHtml(hide ? mark : cash(figures.costs))}`);
      if (!held && !gain && !small.length) return "";
      return (
        `<div class="pos-box" role="group" aria-label="${escapeHtml(str.posTitle)}"` +
        `${config.pos_box_color ? ` style="${escapeHtml(`background: ${config.pos_box_color}`)}"` : ""}>` +
        `<div class="pos-main"><span class="pos-held" style="${elementStyle(config, "pos_held")}">${held}</span>` +
        (gain ? `<span class="pos-gain ${gainSide}" style="${elementStyle(config, "pos_gain")}">${gain}</span>` : "") +
        `</div>` +
        (small.length ? `<div class="pos-sub" style="${elementStyle(config, "pos_sub")}">${small.join(" · ")}</div>` : "") +
        `</div>`
      );
    }

    // The chart with everything that hangs on it: the price scale with the
    // last price on a tag, the volume, the times along the bottom, the line
    // that names the trend lines and the RSI's strip - one grid, so the
    // drawings share their width and a bar stands at the same place in all
    // three.
    _chartHtml(item, str, range, entry, style) {
      const config = this._config;
      const hass = this._hass;
      const history = entry.data;
      const retry =
        `<button type="button" class="retry" data-action="retry"><span class="pill-text">${escapeHtml(str.retry)}</span></button>`;
      if (!history) {
        // Nothing to show yet: said quietly, with a way to ask again once
        // the source did not answer.
        return (
          `<div class="chart-big empty"><span>${escapeHtml(entry.error ? str.noData : str.loading)}</span>` +
          `${entry.error ? retry : ""}</div>`
        );
      }
      const bars = history.bars;
      if (bars.length < 2) return `<div class="chart-big empty"><span>${escapeHtml(str.noChart)}</span></div>`;
      const chart = drawChart(history, {
        style,
        trend: trendOf(config),
        volume: config.show_detail_volume !== false,
        rsi: config.show_detail_rsi !== false && TREND.rsi,
        // The close of the day before, as a dashed line across the day.
        reference: range === "1d" ? (isNumber(history.previousClose) ? history.previousClose : item.previousClose) : null,
        last: item.price,
      });
      const scale = chart.scale;
      const digits = scaleDigits(scale);
      const last = isNumber(item.price) ? item.price : bars[bars.length - 1].c;
      const figure = (value) => plain(hass, value, Math.max(digits, priceDigits(last, item.digits)));
      this._series = {
        ...chart.series,
        scale,
        figure,
        when: hoverFormat(history.interval),
      };
      this._series.trend = trendOf(config);
      this._series.labels = { sma: str.legSma, sma50: str.legSma50, ema: str.legEma };

      const near = (tick) => Math.abs(scale.top(tick) - chart.lastTop) < 8;
      const tickText = (tick) => plain(hass, tick, digits);
      const widest = [...scale.ticks.map(tickText), figure(last)].reduce(
        (longest, text) => (text.length > longest.length ? text : longest),
        ""
      );
      const axis = axisFormat(range, history.interval);
      const timeText = (time) => escapeHtml(dateTime(hass, time, axis));
      // The two axes as Layout sets them.
      const yLook = elementStyle(config, "detail_y_axis");
      const xLook = elementStyle(config, "detail_x_axis");
      // Along the bottom: five moments spread over the bars - or, on a day
      // drawn across its session, round steps from the session's start,
      // each standing where its time is; on a week drawn day by day, each
      // day where it begins.
      const marks = sessionMarks(chart.layout) || chart.layout.days || null;
      const xAxis = marks
        ? `<div class="x-axis marked" style="${xLook}">` +
          marks.map((mark) => `<span class="mark" style="left: ${mark.at.toFixed(2)}%">${timeText(mark.t)}</span>`).join("") +
          `</div>`
        : `<div class="x-axis" style="${xLook}">` +
          [0, 0.25, 0.5, 0.75, 1].map((share) => `<span>${timeText(bars[Math.round(share * (bars.length - 1))].t)}</span>`).join("") +
          `</div>`;
      const cursor = `<div class="cursor" hidden></div>`;
      let html =
        `<div class="chart-big with-axis" data-chart>` +
        `<div class="plot price">${chart.price}<div class="cursor" hidden><span class="dot"></span></div>` +
        `<div class="tip" hidden></div></div>` +
        `<div style="${yLook}" class="y-axis"><i>${escapeHtml(widest)}</i>` +
        `<span class="now ${chart.up ? "up" : "down"}" style="top: ${chart.lastTop.toFixed(2)}%">${escapeHtml(figure(last))}</span>` +
        scale.ticks
          .filter((tick) => !near(tick))
          .map((tick) => `<span style="top: ${scale.top(tick).toFixed(2)}%">${escapeHtml(tickText(tick))}</span>`)
          .join("") +
        `</div>`;
      if (chart.volume) {
        html +=
          `<div class="plot vol">${chart.volume}${cursor}</div>` +
          `<div style="${yLook}" class="y-axis flat"><span>${escapeHtml(compact(hass, chart.volumeTop, "", 1))}</span></div>`;
      }
      html += xAxis;
      if (chart.rsi) {
        // A slim strip under the chart. What it is and its figure for a
        // bar stand in the box that follows the pointer.
        html +=
          `<div class="plot rsi">${chart.rsi}${cursor}</div>` +
          // Its lines stand at 0, 50 and 100 and need no figures beside them.
          `<div style="${yLook}" class="y-axis"></div>`;
      }
      html += `</div>`;
      // The chart on show is the last one that arrived; the source did not
      // answer for a newer one.
      if (entry.error) html += `<div class="chart-note"><span>${escapeHtml(str.noData)}</span>${retry}</div>`;
      return html;
    }

    // What the pointer - or a finger - reads off the chart: a line through
    // the nearest bar in all three drawings, a dot on its close, its moment
    // and prices in a box, and the trend lines' and the RSI's figures showing
    // that bar's instead of the last one's.
    _wireChart(body) {
      const box = body.querySelector(".chart-big[data-chart]");
      const series = this._series;
      if (!box || !series) return;
      const str = t(this._hass);
      const plot = box.querySelector(".plot.price");
      const cursors = [...box.querySelectorAll(".cursor")];
      const dot = box.querySelector(".dot");
      const tip = box.querySelector(".tip");
      const move = (ev) => {
        const rect = plot.getBoundingClientRect();
        if (!rect.width) return;
        const index = nearestIndex(series.xs, ((ev.clientX - rect.left) / rect.width) * 100);
        if (index < 0) return;
        const bar = series.bars[index];
        const left = series.xs[index];
        cursors.forEach((cursor) => {
          cursor.hidden = false;
          cursor.style.left = `${left}%`;
        });
        dot.style.top = `${series.tops[index]}%`;
        tip.hidden = false;
        const side = bar.c >= series.base ? " gain" : " loss";
        tip.innerHTML =
          `<span class="when">${escapeHtml(dateTime(this._hass, bar.t, series.when))}</span>` +
          (series.candles
            ? `<span class="ohlc">` +
              [[str.barOpen, bar.o], [str.barHigh, bar.h], [str.barLow, bar.l], [str.barClose, bar.c]]
                .map(([label, value]) => `<span><i>${escapeHtml(label)}</i> ${escapeHtml(series.figure(value))}</span>`)
                .join("") +
              `</span>`
            : `<span class="val${side}">${escapeHtml(series.figure(bar.c))}</span>`) +
          // Under the bar's prices, in the order of the drawings from the
          // top down: the three averages, the volume, the RSI.
          (series.trend
            ? ["ema", "sma", "sma50"]
                .filter((name) => series.trend[name] && TREND[name] && isNumber(series[name][index]))
                .map(
                  (name) =>
                    `<span class="avg ${name}"><i></i>${escapeHtml(series.labels[name])} ` +
                    `<b>${escapeHtml(series.figure(series[name][index]))}</b></span>`
                )
                .join("")
            : "") +
          (this._config.show_detail_volume !== false && isNumber(bar.v) && bar.v > 0
            ? `<span class="avg vol"><i></i>${escapeHtml(str.fVolume)} <b>${escapeHtml(compact(this._hass, bar.v, "", 1))}</b></span>`
            : "") +
          (this._config.show_detail_rsi !== false && TREND.rsi && isNumber(series.rsi[index])
            ? `<span class="avg rsi"><i></i>${escapeHtml(str.legRsi)} <b>${escapeHtml(plain(this._hass, series.rsi[index], 1))}</b></span>`
            : "");
        // Beside the line, on whichever side has the room.
        tip.style.left = left > 50 ? "auto" : `calc(${left}% + 8px)`;
        tip.style.right = left > 50 ? `calc(${100 - left}% + 8px)` : "auto";
      };
      const leave = () => {
        cursors.forEach((cursor) => (cursor.hidden = true));
        tip.hidden = true;
      };
      for (const el of box.querySelectorAll(".plot")) {
        el.addEventListener("pointermove", move);
        el.addEventListener("pointerdown", move);
        el.addEventListener("pointerleave", leave);
        el.addEventListener("pointercancel", leave);
      }
    }

    // The figures as a plain list: the word at the left, its figure at the
    // right, a hairline between the rows.
    _factsHtml(item, str, range, entry) {
      // The day's first price is the first bar of the day's chart: there
      // once that chart was loaded, by these details or by an entry's curve.
      const day = historyKept(item.id, "1d");
      const dayKept = day && day.data && (range === "1d" || Date.now() - day.at < 6 * 3600000);
      const admin = this._isAdmin(this._hass);
      const rows = factRows(this._hass, str, item, entry.data, dayKept ? dayOpen(day.data) : null, this._config, admin);
      if (!rows.length) return "";
      // The bell before an alert's name: for an administrator the way to
      // the alerts, for anybody else a symbol.
      const config = this._config;
      const bellHtml = (state) =>
        admin
          ? `<button type="button" class="fact-bell ${state}" data-action="alerts" title="${escapeHtml(str.editAlerts)}" aria-label="${escapeHtml(str.editAlerts)}"><ha-icon icon="${escapeHtml(alertIcon(config, state))}"></ha-icon></button>`
          : `<span class="fact-bell ${state}"><ha-icon icon="${escapeHtml(alertIcon(config, state))}"></ha-icon></span>`;
      const labelLook = elementStyle(this._config, "fact_label");
      const valueLook = elementStyle(this._config, "fact_value");
      return (
        `<dl class="facts">` +
        rows
          .map(
            (row) =>
              `<div class="fact${row.alarm ? " alarm" : ""}"><dt${row.help ? ` class="explained" title="${escapeHtml(row.help)}"` : ""} style="${labelLook}">${row.bell ? bellHtml(row.bell) : ""}${escapeHtml(row.label)}</dt>` +
              `<dd style="${valueLook}">${escapeHtml(row.value)}${row.sub ? ` <small>${escapeHtml(row.sub)}</small>` : ""}</dd></div>`
          )
          .join("") +
        `</dl>`
      );
    }

    _onClick(ev) {
      const el = ev.composedPath().find((node) => node.dataset && node.dataset.action);
      const action = el && el.dataset.action;
      if (!action) return;
      if (action === "tk-news") {
        // The symbol for new headlines: the details, with the news
        // unfolded and in view - and seen with that.
        if (this._tkSwiped) {
          this._tkSwiped = false;
          return;
        }
        const id = el.dataset.id;
        this._popNewsOpen = true;
        this._tkOpen(id);
        const show = (tries) => {
          const wrap = this._popBuilt && this._popBuilt.wrap;
          const news = wrap && wrap.isConnected ? wrap.querySelector(".d-news") : null;
          if (news && news.firstChild) {
            news.scrollIntoView({ block: "nearest", behavior: "smooth" });
            markNewsSeen([id]);
          } else if (tries > 0) {
            setTimeout(() => show(tries - 1), 250);
          }
        };
        setTimeout(() => show(12), 250);
        return;
      }
      if (action === "tk-open" || action === "tk-current") {
        // The end of a swipe is not a click.
        if (this._tkSwiped) {
          this._tkSwiped = false;
          return;
        }
        if (action === "tk-open") {
          this._tkOpen(el.dataset.id);
        } else if (this._config.layout === "ticker") {
          const id = this._tkFront();
          if (id) this._tkOpen(id);
        } else {
          this._tkSettleLine();
          const item = this._tkItems()[this._tkIndex || 0];
          if (item) this._tkOpen(item.id);
        }
        return;
      }
      if (action === "tk-prev" || action === "tk-next") {
        this._tkPopStep(action === "tk-next" ? 1 : -1);
        return;
      }
      if (action === "tk-close") {
        this._tkClose();
        return;
      }
      if (action === "perf-range") {
        this._perfRange = el.dataset.key;
        this._render();
        return;
      }
      if (action === "range") {
        this._popRange = rangeOf(el.dataset.key);
        this._render();
        return;
      }
      if (action === "trend-line") {
        const name = ["sma", "sma50", "ema", "rsi"].includes(el.dataset.key) ? el.dataset.key : "sma";
        setTrend(name, !TREND[name]);
        // Every card on the page shares the choice.
        for (const listener of [...LISTENERS]) if (listener._tkRenderPopup) listener._render();
        return;
      }
      if (action === "alloc-news") {
        this._allocNewsOpen = !this._allocNewsOpen;
        this._render();
        // Opened, they are seen.
        if (this._allocNewsOpen) markNewsSeen(this._allocNewsIds);
        return;
      }
      if (action === "news-open") {
        this._popNewsOpen = !this._popNewsOpen;
        this._render();
        if (this._popNewsOpen) markNewsSeen(this._popNewsIds);
        return;
      }
      if (action === "alloc-list") {
        this._allocList = el.dataset.key === "gain" ? "gain" : "shares";
        this._render();
        return;
      }
      if (action === "chart-style") {
        this._popStyle = el.dataset.key === "line" ? "line" : "candles";
        this._render();
        return;
      }
      if (action === "retry") {
        const id = this._shownId();
        if (!id) return;
        historyOf(id, rangeOf(this._popRange), true, true);
        this._render();
        return;
      }
      if (action === "alerts") {
        // The bell: the instrument's price alerts, without the menu.
        const id = el.dataset.id || this._shownId();
        if (!id) return;
        if (this._isAdmin(this._hass)) this._openFlowDialog({ kind: "alerts", id, opener: el });
        else this._tkOpen(id);
        return;
      }
      if (action === "add" || action === "edit" || action === "remove") {
        // From the plate over an instrument: that instrument, and the plate
        // out of the way of the dialog. From the details: the one shown.
        const id = el.dataset.id || this._shownId();
        if (el.closest && el.closest(".tk-tools")) this._toolsHide();
        if (action === "add") this._openFlowDialog({ kind: "add", opener: el });
        else if (id) this._openFlowDialog({ kind: action, id, opener: el });
      }
    }

    // ------------------------------------------------------- adding, changing
    //
    // The card's one dialog over the dashboard, opened by the "+" (kind
    // "add", see show_add_button), the pencil (kind "edit", see
    // show_edit_buttons) and the trash can (kind "remove", see
    // show_remove_button) - over the instrument under the pointer and in
    // the details' line of buttons. It is the
    // Annuals card's dialog, pointed at this integration.
    //
    // An instrument is a subentry of the integration's one config entry.
    // Adding runs the integration's own "Add instrument" steps and changing
    // its own menu for one instrument, both over Home Assistant's subentry
    // flow API; removing asks once, inside the dialog, and removes the
    // subentry. Every label, option, check and error is the integration's,
    // read through its translations, and every field is drawn by Home
    // Assistant's own form element from the flow's own schema - so the form
    // here is the form there, field for field, and a field added to a flow
    // is added here without a line changing. The dialog is its own element
    // (see FLOW_STYLE), taken down with the card or the flow, whichever
    // ends first.
    async _openFlowDialog(spec) {
      if (this._flowDialog) return;
      const hass = this._hass;
      if (!hass || !this._isAdmin(hass)) return;
      // "remove" is the question "Remove X?" alone, without the menu.
      // "alerts" is a change that goes straight to one entry of the menu.
      const jump = spec && spec.kind === "alerts" ? "alerts" : null;
      const kind = jump ? "edit" : spec && (spec.kind === "edit" || spec.kind === "remove") ? spec.kind : "add";
      const strings = t(hass);
      // A native dialog, shown modal: the browser's top layer puts it above
      // whatever is open - the details pop-up, and the card editor's own
      // dialog, whose preview card has these buttons too - keeps focus
      // inside, and turns Escape into a cancel event, after any picker a
      // field has open has taken its turn. A dialog element cannot hold a
      // shadow root, so the styled part is a div inside it.
      const dialog = document.createElement("dialog");
      dialog.className = "market-ticker-ultra-flow-dialog";
      dialog.style.cssText =
        "position:fixed;inset:0;width:100vw;height:100vh;max-width:none;max-height:none;margin:0;padding:0;border:0;background:transparent;overflow:visible;";
      const host = document.createElement("div");
      dialog.appendChild(host);
      const shadow = host.attachShadow({ mode: "open" });
      shadow.innerHTML = `
        <style>${FLOW_STYLE}</style>
        <div class="backdrop"></div>
        <div class="dialog" role="dialog" aria-modal="true" aria-labelledby="flow-heading" tabindex="-1">
          <div class="head">
            <h2 class="heading" id="flow-heading"></h2>
            <button type="button" class="close"><ha-icon icon="mdi:close"></ha-icon></button>
          </div>
          <div class="body"></div>
          <div class="foot"></div>
        </div>`;
      const state = {
        kind,
        id: (spec && spec.id) || null,
        dialog,
        host,
        shadow,
        strings,
        heading: jump
          ? strings.editAlerts
          : kind === "edit" ? strings.editInstrument : kind === "remove" ? strings.removeInstrument : strings.addInstrument,
        // Where the flow lives and what its words are called.
        api: "config/config_entries/subentries/flow",
        textRoot: `component.${DOMAIN}.config_subentries.${SUBENTRY_TYPE}`,
        categories: ["config_subentries", "selector"],
        failed: strings.flowFailed,
        localize: hass.localize,
        formReady: false,
        flowId: null,
        entryId: null,
        finished: false,
        busy: false,
        step: null,
        formStepId: null,
        data: {},
        opener: (spec && spec.opener) || null,
      };
      this._flowDialog = state;
      const close = shadow.querySelector(".close");
      close.setAttribute("aria-label", strings.close);
      close.title = strings.close;
      // Each of the ways out below closes this dialog and no other: a
      // dialog says "close" a while after it was closed - most of a second,
      // measured - and by then the next one may be open. Without the check
      // that late word took the new dialog down with it.
      const leave = () => {
        if (this._flowDialog === state) this._closeFlowDialog();
      };
      close.addEventListener("click", leave);
      shadow.querySelector(".backdrop").addEventListener("click", leave);
      // Escape: the browser asks a modal dialog to cancel once nothing
      // above it - a picker, a dropdown - has taken the key. A dialog
      // closed any other way is taken down the same.
      // The dialog's own events only: a field inside sends "close" and
      // "cancel" events of its own up through the tree - a picker shutting
      // its list, for one - and those must not take the dialog with them.
      dialog.addEventListener("cancel", (ev) => {
        if (ev.target !== dialog) return;
        ev.preventDefault();
        leave();
      });
      dialog.addEventListener("close", (ev) => {
        if (ev.target === dialog) leave();
      });
      // Into the app element's own root, next to Home Assistant's dialogs:
      // some of its fields take hass from the app's context rather than
      // from a property, and a dialog hung on the body is outside that
      // context and draws them empty.
      const app = document.querySelector("home-assistant");
      ((app && app.shadowRoot) || document.body).appendChild(dialog);
      if (typeof dialog.showModal === "function") {
        try {
          dialog.showModal();
        } catch (err) {
          dialog.setAttribute("open", "");
        }
      } else {
        dialog.setAttribute("open", "");
      }
      // Escape by hand as well: a dialog already open underneath - the
      // card editor's - listens for the key on the document and answers it
      // before the browser asks this dialog to cancel. The key is read
      // here first, on its way up from the field that has focus, and left
      // alone while a picker in that path has its list open for the key to
      // close.
      state.onKey = (ev) => {
        if (ev.key !== "Escape" || ev.defaultPrevented) return;
        if (ev.composedPath().some((el) => el && el !== dialog && (el.opened === true || el.open === true))) return;
        ev.stopPropagation();
        ev.preventDefault();
        leave();
      };
      host.addEventListener("keydown", state.onKey);
      this._renderFlowStep(null);
      close.focus();
      // The entry the dialog works in is a group's: the one the instrument
      // is in - or, for a new one, the card's group, the only group there
      // is, or the one chosen from the list the dialog starts with.
      const groups = INSTRUMENTS.groups;
      if (kind === "add") {
        state.entryId = groupOf(this._config) || (groups.length === 1 ? groups[0].id : null);
      } else {
        const own = (INSTRUMENTS.list || []).find((instrument) => instrument.id === state.id);
        state.entryId = own ? own.group : null;
      }
      const run = async () => {
      let step = null;
      try {
        // The flow's words are in the integration's translations for the
        // flow's own category, its dropdowns' options in the "selector"
        // ones - loaded in turn, each returning a localize that knows both.
        const loadTranslations = async () => {
          let localize = hass.localize;
          if (typeof hass.loadBackendTranslation !== "function") return localize;
          for (const category of state.categories) {
            try {
              localize = (await hass.loadBackendTranslation(category, DOMAIN)) || localize;
            } catch (err) {
              // Keep what is loaded; a missing category only leaves keys raw.
            }
          }
          return localize;
        };
        // A subentry flow is addressed to the entry and the kind of
        // subentry - and, to change one, to the subentry itself, whose id
        // is the instrument's.
        const start = async () => {
          if (!state.entryId) throw new Error("no group");
          const body = { handler: [state.entryId, SUBENTRY_TYPE] };
          if (kind === "edit") body.subentry_id = state.id;
          return this._flowRequest("POST", state.api, body);
        };
        if (kind === "remove") {
          // No flow to run: the question alone.
          if (!state.entryId) throw new Error("no group");
          this._renderRemoveConfirm();
          return;
        }
        const [localize, formReady, first] = await Promise.all([loadTranslations(), this._ensureHaForm(), start()]);
        step = first;
        if (this._flowDialog !== state) {
          // Closed while the flow was being opened: the flow must not be
          // left standing on the server.
          if (step && step.flow_id) this._flowRequest("DELETE", `${state.api}/${step.flow_id}`).catch(() => {});
          return;
        }
        state.localize = typeof localize === "function" ? localize : hass.localize;
        state.formReady = formReady;
        // Past the menu, where the dialog was opened for one of its entries.
        if (jump && step && step.type === "menu" && step.flow_id) {
          const options = Array.isArray(step.menu_options) ? step.menu_options : Object.keys(step.menu_options || {});
          if (options.includes(jump)) {
            step = await this._flowRequest("POST", `${state.api}/${step.flow_id}`, { next_step_id: jump });
            if (this._flowDialog !== state) {
              if (step && step.flow_id) this._flowRequest("DELETE", `${state.api}/${step.flow_id}`).catch(() => {});
              return;
            }
          }
        }
        this._applyFlowStep(step);
      } catch (err) {
        if (this._flowDialog !== state) return;
        this._renderFlowFailure(this._flowErrorText(err, state.failed));
      }
      };
      if (kind === "add" && !state.entryId && groups.length > 1) {
        this._renderGroupChoice(run);
        return;
      }
      run();
    }

    // Which group the new instrument goes into: the groups as a list, the
    // dialog's first page where the card does not say.
    _renderGroupChoice(run) {
      const state = this._flowDialog;
      if (!state) return;
      const { shadow, strings } = state;
      shadow.querySelector(".heading").textContent = state.heading;
      const body = shadow.querySelector(".body");
      const foot = shadow.querySelector(".foot");
      body.textContent = "";
      foot.textContent = "";
      const description = document.createElement("div");
      description.className = "description";
      const line = document.createElement("p");
      line.textContent = strings.flowChooseGroup;
      description.appendChild(line);
      body.appendChild(description);
      const menu = document.createElement("div");
      menu.className = "menu";
      for (const group of INSTRUMENTS.groups) {
        menu.appendChild(
          this._flowButton(group.name, "menu-item", () => {
            if (this._flowDialog !== state) return;
            state.entryId = group.id;
            this._renderFlowStep(null);
            run();
          })
        );
      }
      body.appendChild(menu);
      foot.appendChild(this._flowButton(strings.flowCancel, "text", () => this._closeFlowDialog()));
      const first = menu.querySelector("button");
      if (first) first.focus();
    }

    // "Remove X?" inside the dialog - the browser's own question box is not
    // to be had here - with one red button, and a way back to the menu the
    // question came from.
    _renderRemoveConfirm() {
      const state = this._flowDialog;
      if (!state || state.busy) return;
      const { shadow, strings } = state;
      shadow.querySelector(".heading").textContent = strings.removeInstrument;
      const body = shadow.querySelector(".body");
      const foot = shadow.querySelector(".foot");
      body.textContent = "";
      foot.textContent = "";
      const instrument = (INSTRUMENTS.list || []).find((item) => item.id === state.id);
      const description = document.createElement("div");
      description.className = "description";
      const question = document.createElement("p");
      const strong = document.createElement("strong");
      strong.textContent = strings.removeConfirm((instrument && instrument.name) || "");
      question.appendChild(strong);
      const explain = document.createElement("p");
      explain.textContent = strings.removeExplain;
      description.append(question, explain);
      body.appendChild(description);
      // Back to the menu the question came from - or, asked on its own,
      // out of the dialog.
      foot.appendChild(
        state.kind === "remove"
          ? this._flowButton(strings.flowCancel, "text", () => this._closeFlowDialog())
          : this._flowButton(strings.flowBack, "text", () => this._renderFlowStep(state.step))
      );
      foot.appendChild(this._flowButton(strings.removeButton, "danger", () => this._removeInstrument()));
      foot.querySelector("button").focus();
    }

    async _removeInstrument() {
      const state = this._flowDialog;
      if (!state || state.busy || !state.entryId || !state.id) return;
      state.busy = true;
      state.shadow.querySelectorAll(".body button, .foot button").forEach((button) => (button.disabled = true));
      try {
        await this._hass.callWS({
          type: "config_entries/subentries/delete",
          entry_id: state.entryId,
          subentry_id: state.id,
        });
        refreshInstruments();
        if (this._flowDialog !== state) return;
        // Gone. The menu's own flow was never finished: closing the dialog
        // deletes it, as it does for every flow left half way.
        this._closeFlowDialog();
      } catch (err) {
        if (this._flowDialog !== state) return;
        state.busy = false;
        this._renderFlowFailure(this._flowErrorText(err, state.failed));
      }
    }

    _closeFlowDialog() {
      const state = this._flowDialog;
      if (!state) return;
      this._flowDialog = null;
      if (state.onKey) state.host.removeEventListener("keydown", state.onKey);
      try {
        if (state.dialog.open) state.dialog.close();
      } catch (err) {
        // Already closed, or no dialog support: removing it is enough.
      }
      state.dialog.remove();
      // A flow left half way is deleted, so the server is not holding a
      // form nobody will finish; a finished one is already gone.
      if (state.flowId && !state.finished) {
        this._flowRequest("DELETE", `${state.api}/${state.flowId}`).catch(() => {});
      }
      // Back to the button that opened the dialog - or, the card having
      // been drawn again underneath, to the same button as it stands now.
      const opener = state.opener;
      if (opener && opener.isConnected) {
        opener.focus();
        return;
      }
      const again =
        this.shadowRoot &&
        this.shadowRoot.querySelector(state.kind === "add" ? '[data-action="add"]' : `.tk-nav [data-action="${state.kind}"]`);
      if (again) again.focus();
    }

    _flowRequest(method, path, body) {
      return this._hass.callApi(method, path, body);
    }

    // Home Assistant's form element is loaded by its editors, not by every
    // dashboard; asking the entities card for its editor brings it in,
    // which is the same import the config dialogs make.
    async _ensureHaForm() {
      if (customElements.get("ha-form")) return true;
      try {
        const helpers = typeof window.loadCardHelpers === "function" ? await window.loadCardHelpers() : null;
        if (helpers && typeof helpers.createCardElement === "function") {
          const probe = await helpers.createCardElement({ type: "entities", entities: [] });
          if (probe && probe.constructor && typeof probe.constructor.getConfigElement === "function") {
            await probe.constructor.getConfigElement();
          }
        }
      } catch (err) {
        // Nothing to do here: the wait below decides.
      }
      if (customElements.get("ha-form")) return true;
      try {
        await Promise.race([
          customElements.whenDefined("ha-form"),
          new Promise((_, reject) => setTimeout(reject, 5000)),
        ]);
        return true;
      } catch (err) {
        return false;
      }
    }

    // A step's text in the user's language: the integration's own
    // translations, with the step's placeholders filled in - by localize
    // where it can, by hand where an older one leaves them standing.
    _flowText(state, key, placeholders) {
      let text = "";
      try {
        text = state.localize(key, placeholders || undefined) || "";
      } catch (err) {
        text = "";
      }
      if (typeof text !== "string") text = "";
      if (placeholders && text.includes("{")) {
        for (const [name, value] of Object.entries(placeholders)) {
          text = text.split(`{${name}}`).join(String(value));
        }
      }
      return text;
    }

    // What went wrong, after the dialog's own word for it: the REST API
    // answers with a body, the websocket with a message.
    _flowErrorText(err, base) {
      const message =
        (err && err.body && typeof err.body.message === "string" && err.body.message) ||
        (err && typeof err.message === "string" && err.message) ||
        "";
      return message ? `${base}: ${message}` : base;
    }

    // What the form starts out holding, the way Home Assistant's own dialog
    // fills it: a suggested value, else a default, else - for a required
    // field only - the emptiest value of its kind.
    _initialFlowData(schema) {
      const data = {};
      for (const field of schema) {
        const suggested = field.description ? field.description.suggested_value : undefined;
        if (suggested !== undefined && suggested !== null) {
          data[field.name] = suggested;
          continue;
        }
        if ("default" in field) {
          data[field.name] = field.default;
          continue;
        }
        if (!field.required) continue;
        const selector = field.selector || {};
        if (field.type === "boolean" || "boolean" in selector) data[field.name] = false;
        else if (field.type === "string" || "text" in selector) data[field.name] = "";
        else if (field.type === "integer" || field.type === "float" || "number" in selector) {
          const number = selector.number || {};
          data[field.name] = number.min != null ? number.min : 0;
        } else if ("select" in selector) {
          const options = (selector.select && selector.select.options) || [];
          if (selector.select && selector.select.multiple) data[field.name] = [];
          else if (options.length) data[field.name] = typeof options[0] === "string" ? options[0] : options[0].value;
        }
      }
      return data;
    }

    _applyFlowStep(step) {
      const state = this._flowDialog;
      if (!state || !step) return;
      state.step = step;
      if (step.flow_id) state.flowId = step.flow_id;
      const complained = step.errors && Object.keys(step.errors).length > 0;
      if (step.type === "form" && (state.formStepId !== step.step_id || !complained)) {
        // A form starts out as the flow suggests - also the same form
        // coming back for the next entry, as "add another" has it. Only
        // one shown again with errors keeps what was typed.
        state.data = this._initialFlowData(step.data_schema || []);
        state.formStepId = step.step_id;
      }
      if (step.type === "create_entry" || step.type === "abort") {
        state.finished = true;
        // Whatever it ended in, the integration may have changed.
        refreshInstruments();
      }
      // A change ends in an abort that is no failure: the change is made,
      // and there is nothing left to say.
      if (step.type === "abort" && DONE_REASONS.includes(step.reason)) {
        this._closeFlowDialog();
        return;
      }
      this._renderFlowStep(step);
    }

    async _submitFlow(payload) {
      const state = this._flowDialog;
      if (!state || !state.flowId || state.busy) return;
      state.busy = true;
      // The step's own buttons and fields wait for the answer; the close
      // button in the head does not - closing is allowed at any moment,
      // and the answer to a dialog already closed is dropped below.
      state.shadow.querySelectorAll(".body button, .foot button").forEach((button) => (button.disabled = true));
      const form = state.shadow.querySelector("ha-form");
      if (form) form.disabled = true;
      try {
        const step = await this._flowRequest("POST", `${state.api}/${state.flowId}`, payload);
        if (this._flowDialog !== state) return;
        state.busy = false;
        this._applyFlowStep(step);
      } catch (err) {
        if (this._flowDialog !== state) return;
        state.busy = false;
        this._renderFlowFailure(this._flowErrorText(err, state.failed));
      }
    }

    // The flow's descriptions are markdown; the little of it they use -
    // bold and paragraphs - drawn here without pulling in a renderer.
    _appendFlowDescription(body, text) {
      if (!text) return;
      const escape = (s) => s.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");
      const div = document.createElement("div");
      div.className = "description";
      div.innerHTML = text
        .split(/\n{2,}/)
        .map((para) => `<p>${escape(para).replace(/\*\*(.+?)\*\*/g, "<strong>$1</strong>").replace(/\n/g, "<br>")}</p>`)
        .join("");
      body.appendChild(div);
    }

    _renderFlowFailure(text) {
      const state = this._flowDialog;
      if (!state) return;
      const { shadow, strings } = state;
      shadow.querySelector(".heading").textContent = state.heading;
      const body = shadow.querySelector(".body");
      const foot = shadow.querySelector(".foot");
      body.textContent = "";
      foot.textContent = "";
      const p = document.createElement("p");
      p.className = "error";
      p.textContent = text;
      body.appendChild(p);
      foot.appendChild(this._flowButton(strings.close, "primary", () => this._closeFlowDialog()));
      foot.querySelector("button").focus();
    }

    _flowButton(label, kind, onClick) {
      const button = document.createElement("button");
      button.type = "button";
      // A menu option is its own kind of button (see .menu-item), not a
      // .btn with extras - the .btn rules would win over its own.
      button.className = kind === "menu-item" ? kind : `btn ${kind}`;
      button.textContent = label;
      button.addEventListener("click", onClick);
      return button;
    }

    _renderFlowStep(step) {
      const state = this._flowDialog;
      if (!state) return;
      const { shadow, strings } = state;
      const heading = shadow.querySelector(".heading");
      const body = shadow.querySelector(".body");
      const foot = shadow.querySelector(".foot");
      body.textContent = "";
      foot.textContent = "";
      body.scrollTop = 0;
      const text = (key, placeholders) => this._flowText(state, key, placeholders);
      if (!step) {
        heading.textContent = state.heading;
        const loading = document.createElement("div");
        loading.className = "loading";
        const spinnerTag = ["ha-spinner", "ha-circular-progress"].find((tag) => customElements.get(tag));
        if (spinnerTag) {
          const spinner = document.createElement(spinnerTag);
          if (spinnerTag === "ha-circular-progress") spinner.setAttribute("indeterminate", "");
          loading.appendChild(spinner);
        } else {
          loading.textContent = "…";
        }
        body.appendChild(loading);
        foot.appendChild(this._flowButton(strings.flowCancel, "text", () => this._closeFlowDialog()));
        return;
      }
      const stepKey = `${state.textRoot}.step.${step.step_id}`;
      const placeholders = step.description_placeholders || undefined;
      if (step.type === "menu") {
        heading.textContent = text(`${stepKey}.title`, placeholders) || state.heading;
        this._appendFlowDescription(body, text(`${stepKey}.description`, placeholders));
        const menu = document.createElement("div");
        menu.className = "menu";
        // The options as a list of ids, or as ids with their own words.
        const options = Array.isArray(step.menu_options)
          ? step.menu_options.map((option) => [option, ""])
          : Object.entries(step.menu_options || {});
        for (const [option, own] of options) {
          const label = text(`${stepKey}.menu_options.${option}`, placeholders) || own || option;
          menu.appendChild(this._flowButton(label, "menu-item", () => this._submitFlow({ next_step_id: option })));
        }
        body.appendChild(menu);
        // Beside what the instrument's own menu offers: taking it away
        // altogether, which is no step of the flow.
        if (state.kind === "edit") {
          foot.appendChild(this._flowButton(strings.removeInstrument, "text danger-text left", () => this._renderRemoveConfirm()));
        }
        foot.appendChild(this._flowButton(strings.flowCancel, "text", () => this._closeFlowDialog()));
        const first = menu.querySelector("button");
        if (first) first.focus();
        return;
      }
      if (step.type === "form") {
        heading.textContent = text(`${stepKey}.title`, placeholders) || state.heading;
        this._appendFlowDescription(body, text(`${stepKey}.description`, placeholders));
        if (!state.formReady || !customElements.get("ha-form")) {
          this._renderFlowFailure(state.failed);
          return;
        }
        const form = document.createElement("ha-form");
        form.hass = this._hass;
        form.schema = step.data_schema || [];
        form.data = state.data;
        form.error = step.errors || {};
        form.computeLabel = (field) => text(`${stepKey}.data.${field.name}`, placeholders) || field.name;
        form.computeHelper = (field) => text(`${stepKey}.data_description.${field.name}`, placeholders) || "";
        form.computeError = (error) => text(`${state.textRoot}.error.${error}`, placeholders) || error;
        form.localizeValue = (key) => text(`component.${DOMAIN}.selector.${key}`) || "";
        form.addEventListener("value-changed", (ev) => {
          ev.stopPropagation();
          state.data = ev.detail.value;
        });
        body.appendChild(form);
        foot.appendChild(this._flowButton(strings.flowCancel, "text", () => this._closeFlowDialog()));
        foot.appendChild(
          this._flowButton(
            text(`${stepKey}.submit`, placeholders) ||
              // Home Assistant's own dialog says Next where the integration
              // marks a step as leading on to another, and Submit only on
              // the last.
              (step.last_step === false ? strings.flowNext : strings.flowSubmit),
            "primary",
            () => this._submitFlow(state.data)
          )
        );
        // Into the first field once the form has drawn it, as Home
        // Assistant's own dialog does; failing that, the dialog itself,
        // so that Escape still reaches it.
        (form.updateComplete || Promise.resolve()).then(() => {
          if (this._flowDialog !== state) return;
          try {
            form.focus();
          } catch (err) {
            // A form that cannot take focus: the dialog will.
          }
          if (!shadow.activeElement) shadow.querySelector(".dialog").focus();
        });
        return;
      }
      if (step.type === "create_entry") {
        heading.textContent = state.heading;
        this._appendFlowDescription(body, strings.flowCreated(step.title || ""));
        foot.appendChild(this._flowButton(strings.close, "primary", () => this._closeFlowDialog()));
        foot.querySelector("button").focus();
        return;
      }
      if (step.type === "abort") {
        this._renderFlowFailure(text(`${state.textRoot}.abort.${step.reason}`, placeholders) || step.reason || state.failed);
        return;
      }
      // A progress or external step: nothing these flows have.
      this._renderFlowFailure(state.failed);
    }
  }

